INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(11153, 'plPL', 'Przełam blokadę', 'Wszystkie nasze statki zatonęły! Potrzebujemy twojej pomocy, żeby przełamać piracką blokadę w dole, w Strzaskanej Cieśninie!$B$BWeź te bomby kasetowe i zabierz się zeppelinem, który Harrowmeiser nam „pożyczył”. Przeleci z tobą nad pokładami tych pirackich łajdaków, a ty dopilnuj, żeby porządnie oberwali!$B$BJeśli nie rozniesiesz ich w drobny mak, obawiam się, że nigdy nie przełamiemy blokady.', 'Weź bomby kasetowe Petrova i zrzucaj je na piratów, aż zabijesz lub zniszczysz 25 piratów z blokady i 10 dział blokady. Gdy to zrobisz, wróć do bombardiera Petrova w Twierdzy Zachodniej Straży.', '', 'Wróć do bombardiera Petrova w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', '', 'Zniszczone działa blokady', '', '', 0),
(11154, 'plPL', 'Wystrasz z nich guano!', 'Ty, tak, ty... Potrzebuję twojej pomocy!$B$BPetrov wysłał mnie tu po nietoperze guano do bomb kasetowych, które robi w twierdzy. Posłał mnie na zgubę!$B$BCiemnoszpone nietoperze przesiadują w Rozdartym Lesie na północy, ale ja nie zrobię kroku z tego podestu, chyba że do domu!$B$BAle ty... ty $gmógłbyś:mogłabyś; mi je przynieść! Tak? Ładnie proszę?!!!$B$BMasz, weź te petardy. Myślę, że jak rzucisz je pod nietoperze, to guano samo z nich wyleci ze strachu!', 'Zbierz 10 porcji guana ciemnoszponego nietoperza i dostarcz je inżynierowi Feknutowi przy Stalowej Bramie.', '', 'Wróć do inżyniera Feknuta przy Stalowej Bramie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11155, 'plPL', 'Znowu zupa z łopatokła?', 'Przez te dziwne zniknięcia naszego bydła musimy szybko uzupełnić zapasy, bo inaczej tutejsze bestie będą najmniejszym z naszych zmartwień!$B$BSkoro to ja karmię tę zgraję, musisz ruszyć na wschód i zdobyć dla mnie mięso. A konkretnie chcę nam ugotować trochę delikatnego mięsa łopatokła.$B$BTylko uważaj na samce... są wredne!', 'Kuchmistrzyni Kettleblack poprosiła cię o zdobycie 6 porcji mięsa łopatokła i dostarczenie ich do niej, do Twierdzy Zachodniej Straży.', '', 'Wróć do kuchmistrzyni Kettleblack w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', '', '', '', '', 0),
(11157, 'plPL', 'Lęgi zła', '$N, nikomu poza tobą nie ufam na tyle, by ci to powierzyć. Jaja protosmokowców i protopisklęta w płonącym lesie na południowym wschodzie muszą zostać zniszczone!$B$BOd kiedy tu przybyliśmy, Żarzący Lęg stoi w ogniu; musi tam działać jakaś wynaturzona magia. A ostatnio ogień chyba się rozrasta. Moi ludzie mówią, że jeśli szybko czegoś nie zrobimy, za kilka tygodni ogień otoczy nas ze wszystkich stron!$B$BRuszaj tam i usuń zagrożenie – zniszcz te jaja i protopisklęta.', 'Zniszcz 15 jaj protosmokowców i 15 protopiskląt, a następnie wróć do kapitana Adamsa w Twierdzy Zachodniej Straży.', '', 'Wróć do kapitana Adamsa w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', 'Zniszczone jaja protosmokowców', '', '', '', 0),
(11167, 'plPL', 'Nowa Zaraza', 'Niedługo po tym, jak Arthas skazał nas na tę nędzną egzystencję, my, Królewskie Zakłady Chemiczne, postanowiliśmy stworzyć własną zarazę. Zarazę, która pożre wszelkie ciało: żywe, martwe czy nieumarłe.$B$BUdało nam się ją stworzyć i jesteśmy tu, by osobiście dostarczyć ją pod próg Plagi.$B$BPrzymierze przechwyciło statek wiozący najnowszy szczep opracowany w naszych laboratoriach w Podmieście. Udaj się do wraku na południowy wschód stąd i ocal tyle pojemników, ile zdołasz.', 'Aptekarz Lysander z Przystani Zemsty prosi cię o odzyskanie 10 nienaruszonych pojemników z zarazą z wraku statku na południowym wschodzie.', '', 'Wróć do aptekarza Lysandra w Przystani Zemsty w Wyjącym Fiordzie.', '', '', '', '', 0),
(11168, 'plPL', 'Doprawianie mieszanki', 'Mam przeczucie, że długa podróż przez morze osłabia działanie naszej zarazy. Potrzebna jest silna toksyna, która wzmocni ten szczep.$B$BKraby przy tej plaży są dalekimi krewnymi dużo mniejszego, brązowoskorupego pełzacza przypływu. Ta mniejsza, tropikalna odmiana wytwarza paraliżującą toksynę, która potrafi powalić ogra.$B$BWszyscy wiemy, że im większe, tym lepsze! Znacznie większe gruczoły tutejszej odmiany powinny okazać się silniejsze. Przynieś mi kilka!', 'Przynieś 3 olbrzymie gruczoły toksyn z olbrzymich pełzaczy przypływu aptekarzowi Lysandrowi w Przystani Zemsty w Wyjącym Fiordzie.', '', 'Wróć do aptekarza Lysandra w Przystani Zemsty w Wyjącym Fiordzie.', '', '', '', '', 0),
(11170, 'plPL', 'Próba na morzu', 'Właśnie dostaliśmy wieść, że siłom Przymierza idą z pomocą posiłki. Lepiej nie mogli tego zgrać w czasie!$B$BRozpaczliwie potrzebujemy obiektów doświadczalnych, a ci rezerwiści z Floty Północnej świetnie się nadadzą!$B$BWeź ze sobą te fiolki z zarazą i porozmawiaj z Camille, treserką nietoperzy. Powiedz jej, że musisz zarekwirować nietoperza wierzchowego do specjalnego zadania dla nas.$B$BGdy znajdziesz się nad morzem, zrzuć fiolki na flotę posiłków. Nie mogę się doczekać wyników!', 'Porozmawiaj z treserką nietoperzy Camille i poleć nietoperzem wierzchowym, by przechwycić posiłki Przymierza. Nad ich flotą użyj fiolek z zarazą, by zarazić 16 rezerwistów Floty Północnej.', '', 'Wróć do aptekarza Lysandra w Przystani Zemsty w Wyjącym Fiordzie.', 'Zarażeni rezerwiści Floty Północnej', '', '', '', 0),
(11175, 'plPL', 'Moja córka', 'Powiedz mi, czy to prawda? Czy odkrywcy, którzy weszli do Wąwozu Szeptów, oszaleli?$B$BMoja córka jest nadzorczynią wyprawy Ligi Odkrywców, która poszła na północ, do miejsca zwanego Stalową Bramą. Po tych strasznych wydarzeniach, które nas spotkały, boję się o jej bezpieczeństwo.$B$BProszę, $N, jestem za stary na taką podróż. Ma na imię Irena. Pójdziesz sprawdzić, czy nic jej nie jest?', 'Stary Kamienny Płaszcz poprosił cię o odnalezienie jego córki, nadzorczyni Ireny Kamiennego Płaszcza, przy Stalowej Bramie.', '', '', '', '', '', '', 0),
(11176, 'plPL', 'Dopilnuj prac', 'Nasza praca tutaj właściwie dopiero się zaczyna. Ale teraz, gdy sprowadziliśmy te fruwające maszyny z Twierdzy Zachodniej Straży, powinna ruszyć pełną parą.$B$BKłopot w tym, że brakuje nam wykwalifikowanych pilotów. A że w Rozdartym Lesie na północy robi się coraz gorzej, chciałabym szybko tu wszystko pozamykać i wracać do domu.$B$BJeśli możesz pomóc, pogadaj z jednym z moich głównych archeologów. Znajdziesz ich przy fruwających maszynach po północnej i południowej stronie wykopaliska.', 'Odkrywczyni Irena Kamienny Płaszcz poprosiła cię o rozmowę z głównym archeologiem Stalowej Bramy przy Stalowej Bramie.', '', '', '', '', '', '', 0),
(11179, 'plPL', '[Temporarily Deprecated Awaiting a New Mob]Finlay nie ma flaków', 'Tylu kuszników, a kto musi dbać o całą ich broń? Ja, Finlay Fletcher!$B$BDowódca zabrał mi pomocnika do przygotowań do przenosin do Fortu Wildervar, a ja nie mam czasu, żeby wyjść i zebrać wszystkie jelita, których potrzebuję na cięciwy!$B$B$N, bądź tak $gdobry:dobra; i nazbieraj mi trochę jelit. Nadadzą się mgliste szablobestie, które grasują po fiordzie, ale pamiętaj, żeby przynosić tylko najbardziej nieskazitelne jelita! Z poszarpanych flaków nie będzie żadnego pożytku.', 'Zbierz 7 nieskazitelnych jelit mglistej szablobestii dla Finlaya Fletchera i wróć do niego do Twierdzy Zachodniej Straży.', '', 'Wróć do Finlaya Fletchera w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', '', '', '', '', 0),
(11182, 'plPL', 'U korzeni problemu', 'Wszystko w naturze dąży do równowagi. Równowaga zostaje zachwiana tylko przez ingerencję tych, którzy nie współgrają z tą harmonią.$B$BMarnujesz siły, zabijając pisklęta i protosmokowce. Prawdziwymi winowajcami rozrastania się tego magicznie płonącego lasu są niedawno przebudzeni wrykule i ich pan, Skeld Drakeson.$B$BJeśli pragniesz krwi na rękach, zacznij od nich. Ich leże znajdziesz po południowej stronie Żarzącego Lęgu.', 'Zabij 5 treserów Smokołupców i Skelda Drakesona. Jeśli ci się to uda, wróć do pradrzewca z Żarzącego Lęgu w Żarzącym Lęgu.', '', 'Wróć do pradrzewca z Żarzącego Lęgu w Wyjącym Fiordzie.', '', '', '', '', 0),
(11187, 'plPL', 'Mag-porucznik Malister', 'TO SKANDAL! Te protosmokowce atakują twierdzę!$B$BTakie bestie powinny były uciec w popłochu, kiedy $gzająłeś:zajęłaś; się ich lęgami i pisklętami.$B$BBo się nimi $gzająłeś:zajęłaś;, prawda?$B$B$N, to wymaga bardziej bezpośrednich działań. Porozmawiaj z moim doradcą, magiem-porucznikiem Malisterem. Da ci środki, by dobrać się do tych piekielnych stworów.', 'Kapitan Adams poprosił cię o rozmowę ze swoim doradcą, magiem-porucznikiem Malisterem, w Twierdzy Zachodniej Straży.', '', '', '', '', '', '', 0),
(11188, 'plPL', 'Zło złem...', 'Teraz, kiedy rozjuszyliśmy protosmokowce z Żarzącego Lęgu, mogą chcieć dalej atakować twierdzę. Tak być nie może.$B$BNie cierpię dokładać jednego zła do drugiego, ale wygląda na to, że w tym przypadku będziemy musieli zgładzić te stworzenia. To godne pożałowania rozwiązanie, ale i tak musimy się go podjąć.$B$BWeź moją różdżkę. Eksperymentowałem ze zwiększeniem jej zasięgu, ale nie ma zbyt wielkiej siły rażenia. Za to z pewnością zwróci uwagę protosmokowca.', 'Mag-porucznik Malister z Twierdzy Zachodniej Straży zlecił ci zgładzenie 3 protosmokowców.', '', 'Wróć do maga-porucznika Malistera w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', '', '', '', '', 0),
(11189, 'plPL', 'Ostatni raz', 'Witaj. Czy ja nie żyję? Chyba tak, bo unoszę się nad własnym ciałem!$B$BCo za niefortunny obrót spraw. Właśnie miałem się oświadczyć Irenie, kiedy spadła na nas Plaga.$B$BWiem, że ona wciąż żyje... czuję ją w sercu.$B$B$N, jak myślisz, czy $gzdołałbyś:zdołałabyś; bezpiecznie mnie do niej doprowadzić? Plaga wciąż widzi mojego ducha i bez wątpienia może mi zrobić okropne rzeczy.$B$BChciałbym ostatni raz spojrzeć na jej piękną twarz. Możesz jej ode mnie przekazać, że ją kocham.', 'Bezpiecznie odprowadź ducha odkrywcy Jarena do odkrywczyni Ireny Kamiennego Płaszcza przy Stalowej Bramie w Wyjącym Fiordzie.', 'Duch odkrywcy Jarena bezpiecznie odprowadzony do Ireny Kamiennego Płaszcza', 'Wróć do nadzorczyni Ireny Kamiennego Płaszcza w Wąwozie Szeptów w Wyjącym Fiordzie.', '', '', '', '', 0),
(11190, 'plPL', 'Niestandardowy rozmiar', '$GChłopcze:Dziewczyno;, który to geniusz zrobił nam działa w niestandardowym rozmiarze? Teraz musim robić specjalne kule, żeby strzelać z tych piekielnych ustrojstw!$B$BByłbym ci wdzięczny, jakbyś $gposzedł:poszła; i $gpozbierał:pozbierała; kule, co żeśmy je już wystrzelili. Jak te łamagi strzelają, to na pewno leżą porozrzucane wszędzie na południu i wschodzie.$B$B<Artylerzysta rozsuwa dłonie, żeby pokazać ci, jak duże są kule armatnie.>$B$BTo będzie szybsze niż robienie ich od zera, jak amen w pacierzu.', 'Artylerzysta Ely zlecił ci zebranie 10 kul armatnich Zachodniej Straży i przyniesienie ich do niego, do Twierdzy Zachodniej Straży.', '', 'Wróć do artylerzysty Ely\'ego w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', '', '', '', '', 0),
(11199, 'plPL', 'Zamelduj się u zwiadowcy Knowlesa', '$N, teraz, gdy rozprawiliśmy się z tymi przeklętymi protostworami, mam dla ciebie kolejne zadanie.$B$BJeden z moich zwiadowców zameldował o podejrzanej działalności Porzuconych na południu. Wygląda na to, że knują coś w wiosce wrykulów zwanej Halgrind.$B$BChcę, żebyś osobiście $gprzejął:przejęła; tam śledztwo. Porozmawiaj ze zwiadowcą Knowlesem, dowiedz się, co odkrył, i działaj dalej.$B$BOstatnio meldował się z Wieży Żarzącej Włóczni, tuż na zachód od Halgrind.', 'Kapitan Adams polecił ci zameldować się u zwiadowcy Knowlesa przy Wieży Żarzącej Włóczni.', '', '', '', '', '', '', 0),
(11202, 'plPL', 'Misja: Wieczny płomień', 'Porzuceni coś knują i z tego, co widzę, te zbiorniki z zarazą pełne szlamu mają z tym wiele wspólnego.$B$BJeśli mogę coś zasugerować, $gpanie:pani;, powinniśmy je zniszczyć, zanim zdążą zrobić z nich dalszy użytek. Pozwoliłem sobie przygotować wiązkę pochodni z Żarzącego Lęgu. Płoną już od wielu dni!$B$BProszę, na pewno lepiej niż ja wykorzystasz je do zniszczenia tych zbiorników.', 'Zwiadowca Knowles z Wieży Żarzącej Włóczni radzi, byś $gużył:użyła; wiecznie płonących pochodni do zniszczenia czterech zbiorników z zarazą otaczających Halgrind.', '', 'Wróć do zwiadowcy Knowlesa przy Wieży Żarzącej Włóczni w Wyjącym Fiordzie.', 'Zniszczony południowo-zachodni zbiornik z zarazą', 'Zniszczony północno-zachodni zbiornik z zarazą', 'Zniszczony północno-wschodni zbiornik z zarazą', 'Zniszczony południowo-wschodni zbiornik z zarazą', 0),
(11218, 'plPL', 'Uwaga! Materiały wybuchowe!', '$N, kapitan zlecił mi misję. Chciałbym, żebyś mi $gpomógł:pomogła;.$B$BGrupa moich kolegów z Ligi Odkrywców dostała kręćka, kopiąc w Wąwozie Szeptów, tuż na północy. Atakują każdego, kto próbuje tam wejść!$B$BKapitana obchodzi tylko ruda dla twierdzy. Na nasze szczęście mam coś, co załatwi sprawę.$B$BWejdź tam, wysadź rudę i przynieś ją razem z klejnotami, które znajdziesz. Utrzymanie tego miejsca nie jest tanie, wiesz!$B$BMuszę cię jednak ostrzec: ta ruda jest dziwna!', 'Użyj niezawodnego dynamitu Steelringa, by zebrać 6 odłamków rudy z Wąwozu Szeptów i 18 klejnotów z Wąwozu Szeptów. Potem zanieś je saperowi Stalowemu Pierścieniowi do Twierdzy Zachodniej Straży.', '', 'Wróć do sapera Stalowego Pierścienia w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', '', '', '', '', 0),
(11221, 'plPL', 'Meldunki z pola bitwy', 'Naszą misją w Północnej Grani jest zniszczenie Arthasa. Przymierze to tylko przeszkoda, którą zmiażdżymy, gdziekolwiek ją napotkamy.$B$BUdało nam się zniszczyć ich najdalej na wschód wysuniętą flotę, ale ocaleni zabarykadowali się na Wybrzeżu Wraków, na południe stąd.$B$BNasze siły dawno powinny były przełamać ich prowizoryczną obronę, ale nie doceniliśmy ich woli życia. Odszukaj moich oficerów w polu, mroczną tropicielkę Lyanę i tropiciela śmierci Razaela, i niech zdadzą raport z sytuacji.', 'Porozmawiaj z mroczną tropicielką Lyaną i tropicielem śmierci Razaelem na polu bitwy w Krwawiącej Dolinie, na południe od Przystani Zemsty. Gdy wykonasz to zadanie, wróć do najwyższego egzekutora Anselma.', '', 'Wróć do najwyższego egzekutora Anselma w Przystani Zemsty w Wyjącym Fiordzie.', 'Wysłuchaj meldunku Razaela', 'Wysłuchaj meldunku Lyany', '', '', 0),
(11224, 'plPL', 'Przegnaj je do domu', 'Słyszałam plotki o złych rzeczach, które dzieją się w Wąwozie Szeptów na północy. Większość Ligi Odkrywców zeszła w to miejsce, a niektórzy mówią, że oszaleli od tego, co tam odkryli.$B$BTo nie zmienia jednak faktu, że zabrali ze sobą większość naszych mułów i sprzętu. Nie stracę tych mułów!$B$BJeśli się tam znajdziesz i natkniesz się na któregoś z moich mułów, podejdź do niego blisko i pogroź mu uniesioną ręką. Spłoszy się i na pewno wróci do domu.', 'Odkrywczyni Abigail poprosiła cię, byś $guniósł:uniosła; rękę (/raise) przed 10 porzuconymi mułami jucznymi, a następnie $gwrócił:wróciła; do niej do Twierdzy Zachodniej Straży.', '', 'Wróć do odkrywczyni Abigail w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', 'Przegnane porzucone muły juczne', '', '', '', 0),
(11227, 'plPL', 'Niech jedzą wronę', 'Najwyższy egzekutor chce, żebym moimi psami wywęszył wrogich zwiadowców, ale mówię ci od razu, że te plagowe ogary nigdzie się nie ruszą, póki nie zostaną porządnie nakarmione.$B$BJeśli nasze wojsko nie rozumie, że te bestie są zbyt wybredne, żeby jeść śmieci, które mi dali, to nie może oczekiwać, że będą na coś przydatne w polu.$B$BWyglądasz na kogoś, kto ma trochę wolnego czasu. Może weźmiesz jednego z tych psów na polowanie na wrony na zachodzie? Ich mięso nam nie smakuje, ale moi chłopcy je uwielbiają!', 'Pontius, psiarz z Przystani Zemsty, chce, żebyś $gużył:użyła; klatki plagowego ogara, by przywołać głodnego plagowego ogara, i $gnakarmił:nakarmiła; go mięsem wron fiordowych z okolic na zachód od Przystani Zemsty.', '', 'Wróć do Pontiusa w Przystani Zemsty w Wyjącym Fiordzie.', 'Nakarmiony plagowy ogar', '', '', '', 0),
(11228, 'plPL', 'Piekło zamarzło...', 'Fordragon grubo się myli, jeśli myśli, że banda zielonych żółtodziobów, których przysłał do obrony tego portu, długo jeszcze wytrzyma.$B$B<Macalroy unosi brew, przyglądając się twojemu ekwipunkowi.>$B$BTy za to może poradzisz sobie trochę lepiej.$B$BNie da się przecenić, jak ważne jest utrzymanie tego portu, a przez te potwory latające nad głowami sytuacja zmieniła się tu ze złej w jeszcze gorszą.$B$BZamelduj się u wiceadmirała Kellera, tuż na północny zachód stąd, i powiedz mu, że skończyła ci się guma do żucia.', 'Porozmawiaj z wiceadmirałem Kellerem w porcie w Valgardzie.', '', '', '', '', '', '', 0),
(11229, 'plPL', 'Flota „Bieżywiatru”', 'Tuż na wschód od Wybrzeża Wraków stacjonują „Bieżywiatr”, „Odwet Królowej” i „Niepamięć”. Przekaż dowódczyni floty, kapitan Harker, rozkaz zniszczenia dział Przymierza.$B$BPorozmawiaj z naszą treserką nietoperzy, Camille, i poproś o transport do floty. Pospiesz się, $N, każda minuta walki z Przymierzem to minuta, którą moglibyśmy poświęcić na walkę z Arthasem.', 'Porozmawiaj z treserką nietoperzy Camille w Przystani Zemsty i zdobądź transport na „Bieżywiatr”. Zamelduj się u kapitan Harker na pokładzie statku.', '', '', '', '', '', '', 0),
(11230, 'plPL', 'Zasadzka!', 'To miała być bułka z masłem. Ich siły są głodne, ranne i źle wyposażone. A jednak jakimś cudem wpadliśmy prosto w ich pułapkę.$B$BPodpłynęliśmy do tych raf od południa, żeby się ukryć, a te psy z Przymierza od razu wdarły się na nasze pokłady.$B$BPrzykro mi to mówić, ale jeśli chcesz, żeby nasze działa w cokolwiek strzelały, będziesz $gmusiał:musiała; pomóc nam odbić nasze statki.', 'Kapitan Harker z pokładu „Bieżywiatru” chce, żebyś $gzabił:zabiła; 15 piechurów morskich Floty Północnej.', '', 'Wróć do kapitan Harker na pokładzie „Bieżywiatru” w Wyjącym Fiordzie.', '', '', '', '', 0),
(11231, 'plPL', 'O kluczach i klatkach', 'Kapitan może się tym nie przejmować, ale z tego niewiele, co wiemy, wrykule odprawiają w Gjalerbron na północy haniebne obrzędy, jakiś rytuał „przebudzenia”.$B$BDo zasilania swoich bezbożnych rytuałów używają żywych ofiar!$B$B$N, musisz to powstrzymać! Nieważne, kto lub co siedzi w tych klatkach – trzeba ich uwolnić. Założę się, że klucze mają wrykule.$B$BŚwiatłość wie, że ostatnie, czego nam trzeba, to więcej tych dziwnych wrykulów chodzących po okolicy albo, co gorsza, żeby obudzili coś jeszcze bardziej złego!', 'Ojciec Levariol poprosił cię o zdobycie tylu kluczy do klatek z Gjalerbron, by uwolnić 10 więźniów z Gjalerbron. Gdy ci się to uda, wróć do niego do Twierdzy Zachodniej Straży.', '', 'Wróć do ojca Levariola w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', 'Uwolnieni więźniowie z Gjalerbron', '', '', '', 0),
(11232, 'plPL', 'Wskaż nam cele', 'Powinniśmy zdołać przebić się z powrotem do naszych dział. Niestety widoczność pozostawia wiele do życzenia, więc będziesz $gmusiał:musiała; oznaczyć nam cele z lądu.$B$BWeź te dymne race i oznacz nimi pozycje dział wzdłuż północnego muru na Wybrzeżu Wraków, na zachód stąd, gdzie bronią się siły Przymierza.$B$BDaj znać Lyanie, gdy tylko droga dla wojsk lądowych będzie wolna. Tutaj sami sobie poradzimy.', 'Użyj dymnych rac w miejscach, gdzie stoją działa Przymierza, na północnym murze Wybrzeża Wraków. Po wykonaniu zadania zamelduj się u mrocznej tropicielki Lyany w Krwawiącej Dolinie.', '', 'Wróć do mrocznej tropicielki Lyany w Krwawiącej Dolinie w Wyjącym Fiordzie.', 'Oznaczone wschodnie działo', 'Oznaczone zachodnie działo', '', '', 0),
(11233, 'plPL', 'Cios ostateczny', '$GDowiodłeś:Dowiodłaś; swojej wartości na polu bitwy, $N. Być może $godwróciłeś:odwróciłaś; losy walki na naszą korzyść.$B$BMam teraz dla ciebie ważne zadanie. Nie wiem, jak długo potrwa słabość, którą obnażyliśmy, więc musimy wykorzystać element zaskoczenia.$B$BChcę, żebyś $gwykorzystał:wykorzystała; zamęt wywołany naszym atakiem, $gprzedostał:przedostała; się za linie wroga i $gzgładził:zgładziła; ich dowódców. Według stopni są to: kapitan Olster, porucznik Celeyne i sierżant Lorric. Powodzenia, $N.', 'Mroczna tropicielka Lyana, na południe od Przystani Zemsty, chce, żebyś $gzabił:zabiła; kapitana Olstera, porucznik Celeyne i sierżanta Lorrica na Wybrzeżu Wraków.', '', 'Wróć do mrocznej tropicielki Lyany w Krwawiącej Dolinie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11234, 'plPL', 'Zamelduj się u Anselma', 'Poślijmy więc wieść staremu Anselmowi. Zwycięstwo przyszło później, niż się spodziewaliśmy, ale lepiej późno niż wcale. Powiedz mu, że wykończenie maruderów zajmie naszym siłom najwyżej kilka godzin.$B$BChwała Królowej Banshee!', 'Zamelduj się u najwyższego egzekutora Anselma w Przystani Zemsty w Wyjącym Fiordzie.', '', '', '', '', '', '', 0),
(11235, 'plPL', 'Rozprawa z Gjalerbron', 'A teraz mamy inny kłopot. Zwiadowcy, którzy wrócili żywi, donieśli mi, że wrykule knują coś w swojej głównej twierdzy na północy.$B$BNazywają to miejsce Gjalerbron, choć „Gj” wymawia się tam jak „Sz”. Dziwne stworzenia.$B$BAle to nieważne. Ważne jest to, żebyś tam $gposzedł:poszła; i $godebrał:odebrała; życie tylu tym stworzeniom, ilu zdołasz, próbując przy tym ustalić, co knują.$B$BWiem, że mogę na ciebie liczyć, $N.', 'Kapitan Adams poprosił cię o zabicie 15 wojowników z Gjalerbron, 8 runicznych rzucających z Gjalerbron i 8 strażników snu z Gjalerbron. Potem wróć do niego do Twierdzy Zachodniej Straży.', '', 'Wróć do kapitana Adamsa w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', '', '', '', '', 0),
(11236, 'plPL', 'Nekrowładca zwierzchni Mezhen', 'Plaga jest w Gjalerbron i ma ze sobą nekromantów! Muszą próbować przeciągnąć wrykulów na stronę Arthasa.$B$BChcę, żeby przywódca tych nekrowładców został wyeliminowany!$B$BZrób, co trzeba, $N, ale dopilnuj, żeby nekrowładca zwierzchni Mezhen i cokolwiek próbuje osiągnąć zostali zneutralizowani.$B$BNie pozwolę, by wrykule sprzymierzyli się z Plagą!$B$BSzukaj Mezhena na podeście w tylnej prawej części Gjalerbron.', 'Zabij nekrowładcę zwierzchniego Mezhena. Potem wróć do kapitana Adamsa w Twierdzy Zachodniej Straży.', '', 'Wróć do kapitana Adamsa w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', '', '', '', '', 0),
(11237, 'plPL', 'Plany ataku z Gjalerbron', 'Te plany opisują szczegółowo nadciągający atak na Twierdzę Zachodniej Straży. Wygląda na to, że do ofensywy ma zostać użyty żmij mrozu Glacion, który krąży w górze.$B$BMag-porucznik Malister z pewnością mógłby w tej sprawie pomóc. Dostarcz mu plany do twierdzy na południu.', 'Dostarcz plany ataku z Gjalerbron magowi-porucznikowi Malisterowi w Twierdzy Zachodniej Straży.', '', 'Wróć do maga-porucznika Malistera w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', '', '', '', '', 0),
(11238, 'plPL', 'Żmij mrozu i jego pan', 'Dobrze, że $gprzyniosłeś:przyniosłaś; to do mnie, $N. Musisz zabrać ze sobą pomoc, wrócić na północ do Gjalerbron i zabić tego żmija oraz jego pana, Wzywacza Żmijów Vile\'a!$B$BNawet teraz, gdy tu rozmawiamy, żmij mrozu może już być w drodze.$B$BJeśli jednak dobrze odczytuję te plany, zadęcie w róg Wzywacza Żmijów na jego podeście, na zewnątrz, w tylnej lewej części Gjalerbron, przywoła Glaciona z powrotem. Gdy stwór wyląduje, zniszcz go!$B$BI, $N, przynieś mi proszę ten róg. Nie chcielibyśmy, żeby znów wpadł w niepowołane ręce.', 'Zabij Wzywacza Żmijów Vile\'a i użyj Rogu Wzywacza Żmijów, by ściągnąć na ziemię i zabić Glaciona. Potem wróć z rogiem do maga-porucznika Malistera w Twierdzy Zachodniej Straży.', '', 'Wróć do maga-porucznika Malistera w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', '', '', '', '', 0),
(11239, 'plPL', 'W służbie Światłości', 'Twoja służba jest wzorowa, $N, ale coś nie daje mi spokoju: Plaga.$B$BŚwiatłość nie znosi jej obecności i my też nie będziemy jej znosić. Mam nadzieję, że nie proszę o zbyt wiele, ale chciałbym, żebyś $gwrócił:wróciła; na północ do Gjalerbron i $gzmiażdżył:zmiażdżyła; bezbożną Plagę w tym plugawym leżu! Poszukaj jej też w Salach Przebudzenia pod Gjalerbron.$B$BOczyszczenie jest kluczem do zbawienia, moje dziecko. Spraw, byśmy byli z ciebie dumni!', 'Zabij 10 nieśmiertelnych wartowniczek, 4 straszliwe poczwary i 2 gnijące truposze. Potem powiadom ojca Levariola w Twierdzy Zachodniej Straży o swoim sukcesie.', '', 'Wróć do ojca Levariola w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', '', '', '', '', 0),
(11240, 'plPL', 'Przywódca obłąkanych', 'Nie chcę tego mówić, ale kiedy cię nie było, kapitan bardziej zainteresował się tamtym miejscem.$B$BWygląda na to, że chce śmierci mojego dawnego szefa z Ligi Odkrywców. Zgaduję, że szykujemy się do ofensywy, żeby oczyścić teren z reszty, a kapitan chce im, że tak powiem, uciąć głowę.$B$BZrobisz coś dla mnie? Wróć do Wąwozu Szeptów i skończ ze Squeegiem Łowcą Bożków. O ile pamiętam, najpewniej siedzi w jaskini w północno-zachodnim rogu.', 'Zabij Squeega Łowcę Bożków, a następnie zamelduj się u sapera Stalowego Pierścienia w Twierdzy Zachodniej Straży.', '', 'Wróć do sapera Stalowego Pierścienia w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', '', '', '', '', 0),
(11241, 'plPL', 'Ognisty szlak', 'Dzięki, że $gwyciągnąłeś:wyciągnęłaś; mnie z tego bagna, $N. Nie uśmiechało mi się to, co te szumowiny z Przymierza dla mnie szykowały.$B$BWynośmy się stąd i zobaczmy, czy uda nam się jakoś im odpłacić. Czy to tam ognisko?', 'Wyprowadź aptekarza Hanesa z Wybrzeża Wraków. Gdy wykonasz to zadanie, zamelduj się u aptekarza Lysandra w Przystani Zemsty w Wyjącym Fiordzie.', 'Uratuj aptekarza Hanesa', 'Wróć do aptekarza Lysandra w Przystani Zemsty w Wyjącym Fiordzie.', '', '', '', '', 0),
(11243, 'plPL', 'Jeśli Valgard padnie...', 'Jeśli Valgard padnie, nasza główna linia zaopatrzenia w Północnej Grani przestanie istnieć. Potem to już tylko kwestia czasu, zanim wszyscy staniemy się sługami Króla Lisza. Nie wiem jak ty, ale ja mam w Elwynn żonę i trójkę dzieci i niech mnie diabli, jeśli dam się pokonać bez walki.$B$BSytuacja jest krytyczna i przyda nam się każda para rąk, jaką zdołasz zebrać. Udaj się do głównej bramy i pomóż strażnikom bronić miasta przed najeźdźcami!', 'Wiceadmirał Keller w porcie w Valgardzie, w Wyjącym Fiordzie, chce, żebyś $gzabił:zabiła; 12 najeźdźców Smokołupców lub worgów Smokołupców.$B', '', 'Wróć do wiceadmirała Kellera w Valgardzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11244, 'plPL', 'Ratunek dla ratowników', 'Byliśmy tu od miesiąca, kiedy te zniekształcone olbrzymy pojawiły się znikąd. Nie byliśmy przygotowani na żaden atak i słono zapłaciliśmy za naszą beztroskę. Straciliśmy cały zespół archeologów, a kilku mieszkańców porwano i zabrano do ruin. Od tamtej pory jesteśmy w defensywie.$B$BCo gorsza, zwiadowców, których wysłaliśmy na ratunek naszym ludziom, wrykule przebili harpunami i zostawili na pewną śmierć w lesie tuż na północ od Valgardu. Wyrwij te harpuny i uwolnij naszych zwiadowców!$B', 'Wiceadmirał Keller w porcie w Valgardzie, w Wyjącym Fiordzie, chce, żebyś $guratował:uratowała; 8 zwiadowców z Valgardu, których nadziano na harpuny i zostawiono na pewną śmierć.', '', 'Wróć do wiceadmirała Kellera w Valgardzie w Wyjącym Fiordzie.', 'Uratowani zwiadowcy z Valgardu', '', '', '', 0),
(11245, 'plPL', 'Wieże pewnej zguby', '$GPanie:Pani;, idąc przez Skorn, musimy zniszczyć te wieże!$B$BJeśli się im przyjrzysz, zauważysz, że na ich szczytach stoją rzucający zaklęcia. Podejście zbyt blisko oznaczałoby dla nas pewną zgubę!$B$BMamy jednak możliwość wezwania salw z dział Twierdzy Zachodniej Straży. Żeby to zrobić, musimy podejść na tyle blisko, byś $gmógł:mogła; rzucić flarę dymną na ich szczyt.$B$BTylko nie podchodź zbyt blisko!', 'Sierżant Zachodniej Straży radzi, byś $gużył:użyła; flary sierżanta, by wskazać wszystkie cztery wieże w Skorn jako cele salw artyleryjskich.', '', 'Porozmawiaj z towarzyszącym ci sierżantem Zachodniej Straży. Jeśli sierżanta Zachodniej Straży nie ma w pobliżu, użyj insygniów dowództwa Zachodniej Straży.', 'Wskazana wieża północno-zachodnia', 'Wskazana wieża wschodnia', 'Wskazana wieża południowo-zachodnia', 'Wskazana wieża południowo-wschodnia', 0),
(11246, 'plPL', 'Makabryczne, ale konieczne', 'Dostaliśmy meldunki, że ci wrykule potrafią powstawać z martwych – podobnie jak Plaga, ale to inny rodzaj nieumarłości.$B$BNie ryzykujmy.$B$BMasz, weź moją maczetę. Idąc przez to miejsce, będziesz $gmusiał:musiała; poćwiartować szczątki wrykulów, których powalimy. Sam bym to zrobił, ale mam wrażliwy żołądek.$B$B<Sierżant uśmiecha się krzywo.>$B$BCały ranek ją ostrzyłem, więc powinna dać radę.', 'Sierżant Zachodniej Straży poprosił cię, byś maczetą sierżanta $gpoćwiartował:poćwiartowała; 20 wrykulów z plemienia Zimowego Skornu w Skorn.', '', 'Porozmawiaj z towarzyszącym ci sierżantem Zachodniej Straży. Jeśli sierżanta Zachodniej Straży nie ma w pobliżu, użyj insygniów dowództwa Zachodniej Straży.', 'Poćwiartowani wrykule Zimowego Skornu', '', '', '', 0),
(11247, 'plPL', 'Płoń, Skorn, płoń!', 'Kapitan Adams dał mi ścisłe instrukcje, żeby dopilnować poważnych zniszczeń w infrastrukturze tego miejsca.$B$BAle skoro to ty tu dowodzisz, zostawiam to twojej decyzji, $gpanie:pani;.$B$BCzy mogę zasugerować, byśmy spalili dwa długie domy i koszary w dolnej części Skorn? Wystarczy wejść do każdego z nich i rzucić tę pochodnię.', 'Sierżant Zachodniej Straży ma rozkazy, byś pochodnią sierżanta $gpodpalił:podpaliła; północno-wschodni i północno-zachodni długi dom oraz koszary w Skorn.', '', 'Porozmawiaj z towarzyszącym ci sierżantem Zachodniej Straży. Jeśli sierżanta Zachodniej Straży nie ma w pobliżu, użyj insygniów dowództwa Zachodniej Straży.', 'Podpalony północno-zachodni długi dom', 'Podpalony północno-wschodni długi dom', 'Podpalone koszary', '', 0),
(11248, 'plPL', 'Operacja: Skorny gniew', '$N, muszę cię teraz poprosić o podjęcie się operacji tak niebezpiecznej, tak śmiertelnej, że tylko ty możesz ją przeprowadzić.$B$BTwierdza wrykulów, Skorn, leży na naszej wschodniej granicy. Moi zwiadowcy donoszą, że te „olbrzymy” szykują się do uderzenia na nas, a przy moich siłach rozproszonych po całym fiordzie nie mam ludzi, żeby zdobyć to miejsce siłą.$B$BZamiast tego wykorzystasz swój spryt. Wysłałem przodem sierżanta ze szczegółami. Pokaż te insygnia dowództwa w Skorn, a on się ujawni i będzie wykonywał twoje rozkazy.', 'Kapitan Adams poprosił cię, byś $gużył:użyła; insygniów dowództwa Zachodniej Straży w Skorn, a następnie $gporozmawiał:porozmawiała; z sierżantem Zachodniej Straży.', '', '', '', '', '', '', 0),
(11249, 'plPL', 'Powstrzymaj wniebowstąpienie!', 'Ten ogromny zwój wykonano ze smoczej skóry. Gdy rozwijasz go na długość ponad dziesięciu stóp, widzisz, że obrazy namalowane na jego łuskowatej powierzchni przedstawiają tajemniczy rytuał wrykulów.$B$BWrykulski than, otoczony istotami o anielskim wyglądzie, wznosi się do niebios. W tle obrazu góruje tajemnicza, mroczna postać.$B$BMrowienie w trzewiach mówi ci, że than Skorn zamierza właśnie to zrobić. Musisz go powstrzymać! Na szczycie Skorn, przed siedzibą thana, stoi wielki stos.', 'Pokaż wrykulski zwój wniebowstąpienia w pobliżu stosu thana, by go wywabić, i zabij go. Biorąc pod uwagę naturę rytuału, ojciec Levariol z Twierdzy Zachodniej Straży na pewno zechce potem obejrzeć zwój.', '', 'Wróć do ojca Levariola w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', '', '', '', '', 0),
(11250, 'plPL', 'Chwała zdobywcy Skorn!', 'My... no, właściwie ty... $gzrobiłeś:zrobiłaś; wszystko, po co nas tu wysłano, $gpanie:pani;. Muszę przyznać, że wykonywanie rozkazów tak $gwspaniałego, młodego dowódcy:wspaniałej, młodej dowódczyni; było przyjemnością.$B$BKapitan na pewno zechce usłyszeć o twoim sukcesie, ale jeśli z jakiegoś powodu postanowisz tu zostać, jestem do twojej dyspozycji.', 'Zwróć insygnia dowództwa Zachodniej Straży kapitanowi Adamsowi w Twierdzy Zachodniej Straży.', '', 'Wróć do kapitana Adamsa w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', '', '', '', '', 0),
(11251, 'plPL', 'Świeże siły', 'Drogo nas to kosztowało, ale zakończyliśmy przegląd terenu.$b$bWieści nie są dobre. Niemal wszyscy zginęli albo zostali pojmani. Nie wiemy tylko, co się stało z kilkoma weteranami straży.$b$bMy, zwiadowcy, zrobiliśmy tu wszystko, co mogliśmy. Musisz podjąć naszą pracę.$b$bZe wzgórza na północnym wschodzie dochodzą odgłosy potyczki. Rozejrzyj się tam, $N. Pozostaje nam mieć nadzieję, że ktoś przeżył i że ma informacje, które przydadzą się nam przeciwko temu wrogowi.', 'Zwiadowczyni Valory chce, żebyś $gzbadał:zbadała; odgłosy walki dochodzące z północnego wschodu od Wioski Czaszki Żmija.', '', '', '', '', '', '', 0),
(11252, 'plPL', 'Do Utgardu!', 'Słuchaj no, młody. Położyłem już swoją część tych stworów, i twoją przy okazji też. Oto, co musisz wiedzieć...$b$bWrykule nie znają strachu w walce. Zdaje się, że wręcz tęsknią za śmiercią w boju. Przy ich liczebności i tej zajadłości jesteśmy zgubieni, i tyle.$b$bJest jednak jeden, którego szanują, zwie się Ingvar. Nie wiem, czemu tak zabiegają o jego uznanie, ale jak go powalisz, zadasz potężny cios ich morale.$b$bWtedy może będziemy mieć szansę...', 'Obrońca Mordun zlecił ci zgładzenie Ingvara Łupieżcy, który przebywa głęboko w Utgardzie.$b$bNastępnie masz zanieść jego głowę wiceadmirałowi Kellerowi.', '', 'Wróć do wiceadmirała Kellera w Valgardzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11253, 'plPL', 'Wywęsz wroga', 'Teraz, kiedy ten łobuz ma pełny brzuch, może będzie chętniej współpracował. Masz tu jego smycz, przyjdź go zabrać z klatki, kiedy tylko będziesz $ggotów:gotowa;.$B$BNie wiem, co Anselm spodziewa się, że znajdziesz, ale szukaj wskazówek tam, dokąd zaprowadzi cię pies.', 'Użyj smyczy plagowego ogara przy klatkach plagowych ogarów w Przystani Zemsty i szukaj wskazówek w miejscu, do którego zaprowadzi cię plagowy ogar tropiciel.', '', '', '', '', '', '', 0),
(11254, 'plPL', 'Mapa ze smoczej skóry', 'Przy bliższych oględzinach zwój okazuje się bogato ilustrowaną mapą fiordu. Położenie różnych wiosek oznaczono czymś, co wygląda na symbole plemienne.$B$BPrzystań Zemsty oznaczono nieproporcjonalnie dużą czaszką.$B$BTa mapa niemal na pewno będzie miała wartość wojskową dla najwyższego egzekutora Anselma.', 'Zanieś mapę ze smoczej skóry najwyższemu egzekutorowi Anselmowi w Przystani Zemsty.', '', 'Wróć do najwyższego egzekutora Anselma w Przystani Zemsty w Wyjącym Fiordzie.', '', '', '', '', 0),
(11255, 'plPL', 'Więźniowie Czaszki Żmija', 'Ta bitwa jeszcze się nie skończyła, $N. Jeśli nasi ludzie wciąż żyją w tej wiosce, ktoś musi ich stamtąd wydostać.$B$B<Wiceadmirał Keller kiwa do ciebie głową.>$B$BRuszaj na północ i wejdź do Wioski Czaszki Żmija. Tam poszukaj naszych ludzi. Jeśli są uwięzieni, musisz znaleźć sposób, by ich uwolnić.$B$BMoże będą mieli więcej informacji o tym, z czym właściwie walczymy.', 'Wiceadmirał Keller w porcie w Valgardzie, w Wyjącym Fiordzie, chce, żebyś $guratował:uratowała; 3 pojmanych więźniów z Valgardu.', '', 'Wróć do wiceadmirała Kellera w Valgardzie w Wyjącym Fiordzie.', 'Uratowani więźniowie z Valgardu', '', '', '', 0),
(11256, 'plPL', 'Skorn musi upaść!', '$N, twierdza wrykulów, Skorn, leży na południu. Jej dziwne olbrzymy niedawno się przebudziły i zaczęły się rozprzestrzeniać, atakując nas, gdzie tylko mogą.$B$BMoi zwiadowcy donoszą, że szykują się, by uderzyć na nas tutaj, ale nie mam dość sił, by odeprzeć taką potęgę. Zamiast tego przygotujemy się do odejścia na północ, w mniej niebezpieczne krainy.$B$BProszę, byś swoim sprytem $gzyskał:zyskała; dla nas trochę czasu. Wysłałem przodem wojownika ze szczegółami. Pokaż ten emblemat w Skorn, a on się ujawni i zrobi wszystko, by ci pomóc.', 'Wódz Popielny Totem poprosił cię, byś $gużył:użyła; emblematu Zimowego Kopyta w Skorn, a następnie $gporozmawiał:porozmawiała; z wojownikiem Zimowego Kopyta.', '', '', '', '', '', '', 0),
(11257, 'plPL', 'Makabryczne, ale konieczne', 'Nasi starsi mówią, że ci wrykule potrafią być może powstawać z martwych – podobnie jak chodzące trupy, które nazywacie Plagą, ale to inny rodzaj nieumarłości.$B$BNie powinniśmy ryzykować.$B$BMasz, weź moją maczetę. Idąc przez to miejsce, ćwiartuj szczątki wrykulów, których zabijemy.$B$BCały ranek ją ostrzyłem, więc powinna przeciąć nawet ich grube kości.', 'Wojownik Zimowego Kopyta poprosił cię, byś maczetą wojownika $gpoćwiartował:poćwiartowała; 20 wrykulów z plemienia Zimowego Skornu w Skorn.', '', 'Porozmawiaj z towarzyszącym ci wojownikiem Zimowego Kopyta. Jeśli nie ma go w pobliżu, przywołaj go emblematem Zimowego Kopyta.', 'Poćwiartowani wrykule Zimowego Skornu', '', '', '', 0),
(11258, 'plPL', 'Płoń, Skorn, płoń!', 'Wódz Popielny Totem rozkazał mi zniszczyć tu wiele budynków.$B$BAle to ty dowodzisz, więc decyzja należy do ciebie, $N.$B$BProponuję, żebyśmy spalili dwa długie domy i koszary w dolnej części Skorn. Wystarczy wejść do każdego z nich i podpalić je tą pochodnią.', 'Wojownik Zimowego Kopyta proponuje, byś pochodnią wojownika $gpodpalił:podpaliła; północno-wschodni i północno-zachodni długi dom oraz koszary w Skorn.', '', 'Porozmawiaj z towarzyszącym ci wojownikiem Zimowego Kopyta. Jeśli nie ma go w pobliżu, przywołaj go emblematem Zimowego Kopyta.', 'Podpalony północno-zachodni długi dom', 'Podpalony północno-wschodni długi dom', 'Podpalone koszary', '', 0),
(11259, 'plPL', 'Wieże pewnej zguby', 'Idąc przez Skorn, musimy zniszczyć wieże.$B$BJeśli się im przyjrzysz, zauważysz, że na ich szczytach stoją rzucający zaklęcia. Podejście zbyt blisko oznaczałoby pewną zgubę.$B$BMożemy jednak wezwać ataki z powietrza jeźdźców wiwern z Obozu Zimowego Kopyta. Żeby to zrobić, musimy podejść na tyle blisko, byś $gmógł:mogła; rzucić flarę dymną na ich szczyt.$B$BTylko nie podchodź zbyt blisko.', 'Wojownik Zimowego Kopyta radzi, byś $gużył:użyła; flary wojownika, by wskazać wszystkie cztery wieże w Skorn jako cele ataków z powietrza.', '', 'Porozmawiaj z towarzyszącym ci wojownikiem Zimowego Kopyta. Jeśli nie ma go w pobliżu, przywołaj go emblematem Zimowego Kopyta.', 'Wskazana wieża północno-zachodnia', 'Wskazana wieża wschodnia', 'Wskazana wieża południowo-zachodnia', 'Wskazana wieża południowo-wschodnia', 0),
(11260, 'plPL', 'Powstrzymaj wniebowstąpienie!', 'Ten ogromny zwój wykonano ze smoczej skóry. Gdy rozwijasz go na długość ponad dziesięciu stóp, widzisz, że obrazy namalowane na jego łuskowatej powierzchni przedstawiają tajemniczy rytuał wrykulów.$B$BWrykulski than, otoczony istotami o anielskim wyglądzie, wznosi się do niebios. W tle obrazu góruje tajemnicza, mroczna postać.$B$BMrowienie w trzewiach mówi ci, że than Skorn zamierza właśnie to zrobić. Musisz go powstrzymać! Na szczycie Skorn, przed siedzibą thana, stoi wielki stos.', 'Pokaż wrykulski zwój wniebowstąpienia w pobliżu stosu thana, by go wywabić, i zabij go. Biorąc pod uwagę naturę rytuału, Wszechmatka Ankha z Obozu Zimowego Kopyta na pewno zechce potem obejrzeć zwój.', '', 'Wróć do Wszechmatki Ankhy w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', '', '', '', '', 0),
(11261, 'plPL', 'Zdobywca Skorn!', '$GZrobiłeś:Zrobiłaś; wszystko, po co nas tu wysłano, $N. Muszę przyznać, że dobrze walczysz. Twój lud nie jest tak dziwny, jak z początku myślałem.$B$BWódz Popielny Totem na pewno zechce usłyszeć o twoim sukcesie, ale jeśli z jakiegoś powodu postanowisz tu zostać, będę dalej walczył u twego boku.', 'Zwróć emblemat Zimowego Kopyta wodzowi Popielnemu Totemowi w Obozie Zimowego Kopyta.', '', 'Wróć do wodza Popielnego Totema w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', '', '', '', '', 0),
(11262, 'plPL', 'Ingvar musi zginąć!', 'Nareszcie ktoś przyszedł. Jestem tu zdecydowanie za długo i zaczynam tracić zmysły. Z całego naszego oddziału zwiadowczego zostałam tylko ja.$b$bZdam ci raport, a od ciebie będzie zależało, co zrobisz z tymi informacjami. Wiedz jedno, $N: nie przyszły tanim kosztem.$b$bCi wrykule to nieustępliwi wojownicy. Przy ich liczebności i dzikiej taktyce naszą jedyną nadzieją jest powalić ich przywódcę i modlić się, by wprowadziło to chaos w ich szeregi.$b$bNazywa się Ingvar. Gdy wypełnisz swój obowiązek, zanieś jego głowę Anselmowi.', 'Mroczna tropicielka Marrah poprosiła cię o zabicie Ingvara Łupieżcy w Twierdzy Utgard, a następnie o zaniesienie jego głowy najwyższemu egzekutorowi Anselmowi w Przystani Zemsty.', '', 'Wróć do najwyższego egzekutora Anselma w Przystani Zemsty w Wyjącym Fiordzie.', '', '', '', '', 0),
(11263, 'plPL', 'Rozprawa z Gjalerbron', 'Moi gońcy, którzy wrócili żywi, donieśli mi, że wrykule przebudzili się w swojej głównej twierdzy na zachodzie.$B$BTo zakazane miejsce zwane Gjalerbron. Gońcy mówią, że wrykule odprawiają tam dziwne rytuały.$B$BNie możemy na to pozwolić.$B$BCzy zechcesz dalej nam pomagać? Czy zabijesz wrykulów w Gjalerbron, zanim skończą to, co robią, i zaatakują nas tutaj?', 'Wódz Popielny Totem poprosił cię o zabicie 15 wojowników z Gjalerbron, 8 runicznych rzucających z Gjalerbron i 8 strażników snu z Gjalerbron. Potem wróć do niego do Obozu Zimowego Kopyta.', '', 'Wróć do wodza Popielnego Totema w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', '', '', '', '', 0),
(11264, 'plPL', 'Nekrowładca zwierzchni Mezhen', 'Umarli są w Gjalerbron i mają ze sobą nekromantów?$B$BMusimy wyeliminować przywódcę tych nekrowładców.$B$BZrób, co trzeba, $N, ale dopilnuj, żeby nekrowładca zwierzchni Mezhen i cokolwiek próbuje osiągnąć zostali zneutralizowani.$B$BNie możemy dopuścić, by wrykulom powiodło się to, co robią z tymi nieumarłymi stworami!$B$BSzukaj Mezhena na podeście w tylnej prawej części Gjalerbron.', 'Zabij nekrowładcę zwierzchniego Mezhena. Potem wróć do wodza Popielnego Totema w Obozie Zimowego Kopyta.', '', 'Wróć do wodza Popielnego Totema w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', '', '', '', '', 0),
(11265, 'plPL', 'O kluczach i klatkach', 'Z tego niewiele, co wiemy, wrykule odprawiają na zachodzie, w Gjalerbron, nienaturalne obrzędy, jakiś rytuał „przebudzenia”.$B$BDo zasilania swoich rytuałów używają żywych ofiar.$B$B$N, musisz to powstrzymać. Nieważne, kto lub co siedzi w tych klatkach – trzeba ich uwolnić. Sądzę, że klucze mają wrykule.$B$BOstatnie, czego nam trzeba, to więcej tych dziwnych wrykulów, którzy nam zagrażają, albo, co gorsza, żeby obudzili coś jeszcze bardziej złego...', 'Wszechmatka Ankha poprosiła cię o zdobycie tylu kluczy do klatek z Gjalerbron, by uwolnić 10 więźniów z Gjalerbron. Gdy ci się to uda, wróć do niej do Obozu Zimowego Kopyta.', '', 'Wróć do Wszechmatki Ankhy w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', 'Uwolnieni więźniowie z Gjalerbron', '', '', '', 0),
(11266, 'plPL', 'Plany ataku z Gjalerbron', 'Te plany opisują szczegółowo nadciągający atak na Obóz Zimowego Kopyta. Wygląda na to, że do ofensywy ma zostać użyty żmij mrozu Glacion, który krąży w górze.$B$BCelea Zmrożona Grzywa z pewnością mogłaby w tej sprawie pomóc. Dostarcz jej plany do obozu na wschodzie.', 'Dostarcz plany ataku z Gjalerbron Celei Zmrożonej Grzywie w Obozie Zimowego Kopyta.', '', 'Wróć do Celei Zmrożonej Grzywy w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', '', '', '', '', 0),
(11267, 'plPL', 'Żmij mrozu i jego pan', 'Instynkt dobrze ci podpowiedział, by przynieść to do mnie, ale moi jeźdźcy wiwern nie mogą walczyć ze smokiem. Musisz zabrać ze sobą pomoc, wrócić na zachód do Gjalerbron i zabić żmija mrozu oraz jego pana, Wzywacza Żmijów Vile\'a!$B$BNawet teraz może już być w drodze!$B$BJeśli dobrze odczytuję te plany, zadęcie w róg Wzywacza Żmijów na jego podeście, na zewnątrz, w tylnej lewej części Gjalerbron, przywoła Glaciona z powrotem. Gdy stwór wyląduje, zniszcz go!$B$BI, $N, przynieś mi ten róg. Nie chcielibyśmy, żeby znów wpadł w niepowołane ręce!', 'Zabij Wzywacza Żmijów Vile\'a i użyj Rogu Wzywacza Żmijów, by ściągnąć na ziemię i zabić Glaciona. Potem wróć z rogiem do Celei Zmrożonej Grzywy w Obozie Zimowego Kopyta.', '', 'Wróć do Celei Zmrożonej Grzywy w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', '', '', '', '', 0),
(11268, 'plPL', 'Żywe trupy', 'Twoja pomoc była dla nas ogromna, $N, ale coś nie daje mi spokoju: ta tak zwana Plaga.$B$BDuchy ziemi i powietrza, wód i ognia pod światem nie powinny znosić jej obecności, a jednak zdają się nic z nią nie robić. Sami dopilnujemy, by się z nią rozprawić!$B$BByć może proszę o zbyt wiele, ale chciałabym, żebyś $gwrócił:wróciła; na zachód do Gjalerbron i $gzniszczył:zniszczyła; nienaturalną Plagę w tym plugawym leżu. Sprawdź koniecznie także Sale Przebudzenia pod Gjalerbron!', 'Zabij 10 nieśmiertelnych wartowniczek, 4 straszliwe poczwary i 2 gnijące truposze. Potem powiadom Wszechmatkę Ankhę w Obozie Zimowego Kopyta o swoim sukcesie.', '', 'Wróć do Wszechmatki Ankhy w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', '', '', '', '', 0),
(11269, 'plPL', 'Puch na ostatnią chwilę', 'Awangarda sił Przymierza przybędzie w ciągu kilku dni. Żołnierze będą oczekiwać, że ich zimowy ekwipunek będzie gotowy, a ja wciąż mam do uszycia kolejne płaszcze.$B$BNa podszewki płaszczy używam puchu cętkowanego hipogryfa, ale moje zapasy się kończą!$B$BMusisz mi pomóc, $N. Kapitan Adams obedrze mnie ze skóry, jeśli te płaszcze nie będą gotowe na czas! Przynieś mi cały puch, jaki znajdziesz. Gubią go na ziemię linejące hipogryfy, które latają nad dziczą wokół fortu.', 'Gil Grisert chce, żebyś $gprzyniósł:przyniosła; mu 10 kłębków puchu cętkowanego hipogryfa.', '', 'Wróć do Gila Griserta w Forcie Wildervar w Wyjącym Fiordzie.', '', '', '', '', 0),
(11270, 'plPL', 'Wojna to piekło', 'Powoli wykańczamy resztki Floty Północnej Wichrogrodu stacjonującej na tym wybrzeżu. Ciała na zachodzie świadczą o tym, jak brutalne było to starcie.$B$BMojemu wyrafinowanemu poczuciu estetyki akurat to nie przeszkadza, ale stanowi zagrożenie dla naszego życia.$B$BNa ziemiach Króla Lisza umarli są bronią, która w każdej chwili może powstać przeciwko nam. Weź tę pochodnię – dopilnujesz, żeby do tego nie doszło.', 'Najwyższy egzekutor Anselm z Przystani Zemsty chce, żebyś $gwziął:wzięła; płonącą pochodnię i $gspalił:spaliła; nią 10 zwłok zaścielających teren na zachód od osady.', '', 'Wróć do najwyższego egzekutora Anselma w Przystani Zemsty w Wyjącym Fiordzie.', 'Spaleni polegli wojownicy', '', '', '', 0),
(11271, 'plPL', 'Pospieszne przygotowania', 'Puch cętkowanego hipogryfa jest ceniony przez mój lud i używany do wszystkiego, od lotek strzał po stroje obrzędowe. Szykujemy się do opuszczenia obozu, więc to moja ostatnia szansa, by zebrać go w tym sezonie.$B$BZ twoją pomocą będę mieć dość, by każdy miał ekwipunek potrzebny na długą wędrówkę we wzgórza. Warunki pogarszają się tam bardzo szybko, a burza może nadciągnąć bez ostrzeżenia.$B$BPuch leży na ziemi wszędzie w okolicach obozu.', 'Ahota Biały Szron z Obozu Zimowego Kopyta chce, żebyś $gprzyniósł:przyniosła; mu 10 kłębków puchu cętkowanego hipogryfa.', '', 'Wróć do Ahoty Białego Szronu w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', '', '', '', '', 0),
(11272, 'plPL', 'Rachunki do wyrównania', 'Ten elfi książę myśli, że może przyjść do mojego miasta, obrazić moją królową, zabić moich ludzi i ujść z tym na sucho? Myśli, że będziemy stać z założonymi rękami, gdy hordy z Utgardu zbierają siły do ataku?$B$BNigdy w życiu.$B$BWejdziesz prosto do Utgardu i zabijesz go na oczach tych wrykulskich goryli, które będą się przyglądać. Chcę, żeby Arthas wiedział, że przybyliśmy i gramy na serio.', 'Najwyższy egzekutor Anselm chce, żebyś $gwkroczył:wkroczyła; do Utgardu i $gzabił:zabiła; księcia Kelesetha.', '', 'Wróć do najwyższego egzekutora Anselma w Przystani Zemsty w Wyjącym Fiordzie.', '', '', '', '', 0),
(11273, 'plPL', 'Ludzka liga', 'Byliśmy o krok od przełomu archeologicznego, kiedy zaatakowały nas te potwory! Niestety tylko mnie udało się wrócić do Valgardu. Nie wiem, czy moja ekipa żyje, ale artefakty, które odkopaliśmy na tym wykopalisku, muszą zostać odnalezione!$B$BJeśli wybierasz się do Wioski Czaszki Żmija, czy rozejrzysz się za moim zespołem? Jeśli jest jakakolwiek nadzieja na odzyskanie tych informacji, musimy ją wykorzystać!$B$BNajpierw poszukaj Pulroya. Był ostatnim, którego widziałem, zanim uciekłem.', 'Poszukaj Pulroya w Wiosce Czaszki Żmija.', '', '', '', '', '', '', 0),
(11274, 'plPL', 'Zedd pewnie nie żyje', 'Do znalazcy tego dziennika:$B$BTe krwiożercze potwory zamieszkały w ruinach Czaszki Żmija. Czego chcą i po co tu są, pozostaje zagadką. Tak czy inaczej, artefakty nie są bezpieczne, gdy te zwierzoludy kręcą się w pobliżu.$B$BUkrywając się, dokonaliśmy z Zeddem nowego odkrycia: znaleźliśmy szyfr do odczytania tablic! Niestety zeszłej nocy rozdzieliliśmy się z Zeddem. Szyfr był u niego. Tablice mieli Glorenfeld i Daegarn. Miejsce pobytu nieznane...$B$BZnajdź Zedda.$B$B– Pulroy', 'Poszukaj Zedda w Wiosce Czaszki Żmija.', '', '', '', '', '', '', 0),
(11275, 'plPL', 'Róg myśliwski', 'Mój lud od pokoleń poluje na olbrzymie yeti z tych wzgórz, a w tym roku po raz pierwszy wezmę udział w łowach. Pewnie będą to ostatnie łowy, zanim na zawsze opuścimy obóz.$B$BBy przygotować się do polowania, muszę zrobić głośny róg z rogów srogich baranów, które przemierzają zaśnieżone okolice naszego obozu. Starsi mówią, że jego dźwięk naśladuje zew godowy samicy yeti, ale mam wątpliwości.$B$BPrzynieś mi najlepsze rogi srogich baranów, jakie znajdziesz, $N, a ja wybiorę spośród nich jeden.', 'Nokoma Śnieżna Wieszczka z Obozu Zimowego Kopyta chce, żebyś $gprzyniósł:przyniosła; jej 6 nieuszkodzonych rogów barana.', '', 'Wróć do Nokomy Śnieżnej Wieszczki w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', '', '', '', '', 0),
(11276, 'plPL', 'I zostało dwóch...', 'Przy Zeddzie nie ma śladu szyfru. Po dokładnym przeszukaniu okolicy odkrywasz napis wydrapany w ziemi:$B$B„Glor i Dae w katakumbach. Mają szyfr i tablice”.$B$BMoże $gpowinieneś:powinnaś; udać się do katakumb tuż na północ stąd i poszukać Glorenfelda i Daegarna. Most nad jamą worgów zaprowadzi cię prosto do tunelu wiodącego w dół, do katakumb.', 'Poszukaj Glorenfelda w Katakumbach Utgard.', '', '', '', '', '', '', 0),
(11277, 'plPL', 'Otchłań zepsucia', 'Trzymają Daegarna zamkniętego w klatce przy dużej arenie niedaleko stąd. Z tego, co zdołałem wywnioskować, Smokołupcy wyprowadzają więźniów do walki ze swoimi najpotężniejszymi gladiatorami. Przegranych wrzucają do piwnicy, gdzie nekromanci Plagi zmieniają ich w ghule! To straszne!$B$BAle po kolei! Tablice są porozrzucane po całych tych lochach. Odzyskajmy je, zanim ruszysz zgrywać bohatera.', 'Glorenfeld z Katakumb Utgard chce, żebyś $gzebrał:zebrała; 10 tablic Czaszki Żmija.', '', 'Wróć do Glorenfelda w Katakumbach Utgard w Wyjącym Fiordzie.', '', '', '', '', 0),
(11278, 'plPL', 'Powrót do Valgardu', 'Szkoda, że straciliśmy dwóch naszych najlepszych krasnoludów przy odkopywaniu tych reliktów. Poświęcili życie, żeby te informacje były bezpieczne.$B$B<Glorenfeld zawija szyfr i tablice w podartą szmatę.>$B$BZanieś to do Valgardu. McSorf będzie wiedział, co zrobić z tym znaleziskiem.$B$BA ja? Dam sobie radę sam. Dotarłem aż tutaj w jednym kawałku!', 'Zanieś paczkę Glorenfelda Beltrandowi McSorfowi w porcie w Valgardzie.', '', 'Wróć do Beltranda McSorfa w Wyjącym Fiordzie.', '', '', '', '', 0),
(11279, 'plPL', 'Zielone jajka i pisklęta', 'Ta nowa zaraza, nad którą pracujemy, jest cudowna i myślę, że powinniśmy rozszerzyć jej testy.$B$BMoże przetestujemy ją na protopisklętach?!$B$BPomyśl tylko o możliwościach. Zdolność zarażania nie tylko humanoidów, ale każdego stworzenia!$B$BMasz, odłożyłem dodatkowy kanister zarazy na odpowiedni czas i miejsce, a ty wyglądasz na odpowiednią osobę.$B$BSpryskaj jaja w Żarzącym Lęgu na północnym zachodzie, a potem zdobądź okazy zarażonych protopiskląt, które się wyklują.', 'Siewca zarazy Tillinghast poprosił cię o zebranie 10 okazów zarażonych protopiskląt i dostarczenie ich do niego, do Nowego Agamandu.', '', 'Wróć do siewcy zarazy Tillinghasta w Nowym Agamandzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11280, 'plPL', 'Draconis gastritis', 'Chwila, to podsuwa mi pomysł! A może nie zabiła piskląt, bo rozpylono ją na zewnątrz ich jaj?$B$B$N, musimy dostarczyć zarazę do ich wnętrza!$B$BWiem! Mam tu trochę zarażonego mięsa. Zanieś je do Żarzącego Lęgu i spraw, żeby je zjadły!$B$BAle nie, myślimy zbyt małostkowo. Zwabmy na dół jednego z protosmokowców, które latają w górze, żeby je zjadł.$B$BTak!$B$BTrzymaj się blisko mięsa i obserwuj, co się stanie. Owszem, może cię zaatakować, ale taka jest cena postępu.', 'Siewca zarazy Tillinghast z Nowego Agamandu chce, żebyś zarażonym mięsem Tillinghasta $gzwabił:zwabiła; na ziemię protosmokowca i $gobserwował:obserwowała; jego reakcję na zjedzenie tego świństwa.', '', 'Wróć do siewcy zarazy Tillinghasta w Nowym Agamandzie w Wyjącym Fiordzie.', 'Zaobserwowane skutki zarazy u protosmokowca', '', '', '', 0),
(11281, 'plPL', 'Na zew natury', 'Róg jest już wstępnie obrobiony, ale zanim wyrzeźbię tradycyjne wzory, chcę mieć pewność, że zadziała. Ahota mówi, że swoje rogi testuje u stóp zamarzniętego wodospadu na północny wschód od obozu. Ahota mówi, że nasi łowcy od pokoleń wykorzystują w ten sposób akustykę zamarzniętej wody. Nie mogę się doczekać, aż dowiem się więcej!$B$BPomożesz mi wypróbować róg? Jeśli wszystko zrobiłam dobrze, może nawet zwabisz yeti, więc bądź $ggotów:gotowa;! Po wypróbowaniu przynieś róg z powrotem.', 'Wypróbuj rzeźbiony róg, a następnie wróć z wynikami do Nokomy Śnieżnej Wieszczki w Obozie Zimowego Kopyta.', '', 'Wróć do Nokomy Śnieżnej Wieszczki w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', 'Wypróbuj róg Nokomy', '', '', '', 0),
(11282, 'plPL', 'Lekcja strachu', 'Jak ktoś walczy tyle razy co Gorth, to wie, że żeby dobrze pobić wroga, trzeba go bardzo nastraszyć, żeby bał się umierać!$B$BAle te wrykule nie bać się. Ty zabić jednego, a przyjść drugi... krzyczy głośniej i ma większą broń niż ten wcześniej.$B$BJedyna rzecz, co straszy wrykule, to jak my zabić największego i najgorszego wrykula ze wszystkich.$B$BIdź walczyć z Zimowym Skornem za blokadą, aż przyjdą bohaterskie wrykule! Wtedy ty zabić ich na śmierć i wbić flagę królowej w trupy. Oni muszą nauczyć się strach!', 'Gorth chce, żebyś $gzabił:zabiła; Ulfa Upuszczacza Krwi, Orica Złowrogiego i Gunnara Thorvardssona i $gwbił:wbiła; w ich zwłoki sztandar Porzuconych. Zabijaj wrykulów za blokadą Porzuconych, dopóki się nie pojawią.', '', 'Wróć do sierżanta Gortha przy Windzie Zemsty w Wyjącym Fiordzie.', 'Nadziane zwłoki Orica Złowrogiego', 'Nadziane zwłoki Ulfa Upuszczacza Krwi', 'Nadziane zwłoki Gunnara Thorvardssona', '', 0),
(11283, 'plPL', 'Trupy w Baleheimie', 'Te wrykule ciągle przychodzą i przychodzą z miasta na zachód stąd. Końca nie widać!$B$BGorth mieć pomysł. Ty iść DO ŚRODKA miasta i zabić tam Zimowy Skorn. WTEDY oni przestać tu przychodzić!', 'Sierżant Gorth chce, żebyś $gzabił:zabiła; 16 wrykulów Zimowego Skornu w Baleheimie.', '', 'Wróć do sierżanta Gortha w pobliżu Windy Zemsty w Wyjącym Fiordzie.', 'Trupy w Baleheimie', '', '', '', 0),
(11284, 'plPL', 'Yeti z sąsiedztwa', 'Może skoro wartownicy nie chcą mi pomóc, ty pomożesz? Jestem brygadzistą kopalni tuż za mostem. Moi ludzie wydobywają rudę na broń, której nasze siły ekspedycyjne będą potrzebować, by utorować sobie drogę do Wzgórz Grizli.$B$BOlbrzymi yeti wtargnął do kopalni i zablokował tunel, który musimy poszerzyć! Próbowaliśmy na niego krzyczeć i wykurzyć go dymem, ale nic nie działa.$B$BMoże $gzdołałbyś:zdołałabyś; wyrwać go ze snu posiłkiem z mięsa mroźnorogich baranów z zaśnieżonych okolic miasta? Proszę! Jesteśmy w rozpaczy!', 'Brygadzista Colbey z Fortu Wildervar chce, żebyś $gpokonał:pokonała; Strzaskanego Roga.', '', 'Wróć do brygadzisty Colbeya w Forcie Wildervar w Wyjącym Fiordzie.', '', '', '', '', 0),
(11285, 'plPL', 'Baleheim musi spłonąć!', 'Zabijanie Zimowego Skornu może nie wystarczyć. Może my spalić też ich domy! Eee... i mosty. My spalić całe miasto, żeby było bezpiecznie!$B$BTy weź tę pochodnię. Idź do Baleheimu, na zachód, i spal WSZYSTKO! To ich dobrze nauczyć.', 'Sierżant Gorth chce, żebyś $gudał:udała; się do Baleheimu i pochodnią Gortha $gspalił:spaliła; 1 dom Zimowego Skornu, 1 wieżę strażniczą Zimowego Skornu, 1 most Zimowego Skornu i 1 koszary Zimowego Skornu.', '', 'Wróć do sierżanta Gortha w pobliżu Windy Zemsty w Wyjącym Fiordzie.', 'Spalony dom Zimowego Skornu', 'Spalona wieża strażnicza Zimowego Skornu', 'Spalony most Zimowego Skornu', 'Spalone koszary Zimowego Skornu', 0),
(11286, 'plPL', 'Artefakty ze Stalowej Bramy', 'Przybyłem tu z innego powodu; stary przyjaciel wzywa mnie w snach. Ale teraz, gdy widzę, jak te małe istoty swoimi maszynami robią wielką dziurę w ziemi, krew się we mnie gotuje.$B$BZ tego, co widzę, te krasnoludy, bo tak się je nazywa, wykopują artefakty; artefakty, które mogą być ważne dla naszej przeszłości.$B$BChcę, żebyś tam $gzszedł:zeszła; i $gzdobył:zdobyła; je dla mnie. Nie pozwól, by któryś z tych krasnoludów stanął ci na drodze.', 'Mędrzec Mglisty Krok poprosił cię o zebranie 10 artefaktów ze Stalowej Bramy. Gdy zbierzesz wszystkie, wróć do niego przy Stalowej Bramie.', '', 'Wróć do mędrca Mglisty Krok przy Stalowej Bramie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11287, 'plPL', 'Odnajdź mędrca Mglisty Krok', '$N, coraz bardziej się martwię, że mojego syna, mędrca Mglisty Krok, tak długo nie ma. Ta ziemia jest okrutna i zabójcza.$B$BMówił o powracającej wizji wilka i wyruszył na zachód z niewielką grupą gońców, by odnaleźć jej źródło. Zdaje się, że miejsce, o którym wspominał, nazywa się Stalowa Brama.$B$BOdnajdziesz go? Chcę mieć pewność, że nic złego mu się nie stało.', 'Wszechmatka Ankha poprosiła cię, byś $gsprawdził:sprawdziła;, co się dzieje z mędrcem Mglisty Krok. Sądzi, że jest przy Stalowej Bramie lub w jej pobliżu.', '', '', '', '', '', '', 0),
(11288, 'plPL', 'Lśniące światło', '<Ares łapie powietrze, próbując mówić.>$B$BJestem wysłannikiem Krucjaty Argentu, obarczonym świętym obowiązkiem.$B$BNasze siły zostały zdziesiątkowane na Plagowiskach. W blasku świtu artefakt został oczyszczony i znów stał się czysty. Tak wielu zginęło w następstwie jego odkupienia.$B$BWciąż jest szansa... jeszcze jest czas.$B$BArtefakt został ciśnięty do leża poległych, daleko pod nami. Strzegą go bezlitośni umarli.$B$B<Ciało Aresa jaśnieje oślepiającym światłem.>$B$BŚwiatłość. Będzie. Cię. Chronić.$B', 'Ares Związany Przysięgą w Katakumbach Utgard chce, żebyś $godzyskał:odzyskała; święty artefakt.$B$BTo zadanie na czas.', '', 'Wróć do Aresa Związanego Przysięgą w Katakumbach Utgard w Wyjącym Fiordzie.', '', '', '', '', 0),
(11289, 'plPL', 'Wiedziony honorem', '<Ares się uśmiecha.>$B$BChwała Światłości. Udało ci się!$B$B<Ares kaszle.>$B$BWeź artefakt i zanieś go do Valgardu. Lord Irulon Prawe Ostrze czeka na jego powrót.$B$BWalcz z honorem, $gprzyjacielu:przyjaciółko;. Zawsze. Honor.$B$B<Ares umiera.>', 'Zanieś święty artefakt lordowi Irulonowi Prawemu Ostrzu w Valgardzie.', '', 'Wróć do lorda Irulona Prawego Ostrza w Valgardzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11290, 'plPL', 'Plany bitewne Smokołupców', 'Choć o miejscu pobytu Ingvara udało nam się zebrać bardzo niewiele informacji, wiemy, że Yanis przebywa w jaskini obok jamy worgów w Wiosce Czaszki Żmija.$B$BZ informacji uzyskanych od uratowanych żołnierzy wynika, że Yanis strzeże planów bitewnych Smokołupców.$B$BMusisz wrócić do Czaszki Żmija i zdobyć te plany. Zabij każdego wrykula, który stanie ci na drodze – łącznie z Yanisem!', 'Wiceadmirał Keller w porcie w Valgardzie, w Wyjącym Fiordzie, poprosił cię o przyniesienie mu planów bitewnych Smokołupców.$B', '', 'Wróć do wiceadmirała Kellera w Valgardzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11291, 'plPL', 'Do Twierdzy Zachodniej Straży!', '<Wiceadmirał Keller zwija plany bitewne.>$B$BMamy wszystkie informacje potrzebne do ochrony Valgardu. Musisz zanieść te plany do Twierdzy Zachodniej Straży, położonej na zachodnim klifie fiordu. Porozmawiaj z pomocniczką mistrza lotów, Emilune Zimowy Wiatr. Posadzi cię na grzbiecie gryfa lecącego do Zachodniej Straży.$B$BNa miejscu znajdź kapitana Adamsa. To on dowodzi. Adams będzie wiedział, co zrobić z tymi planami.', 'Zanieś plany bitewne Smokołupców kapitanowi Adamsowi w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.$B', '', 'Wróć do kapitana Adamsa w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', '', '', '', '', 0),
(11292, 'plPL', 'Żerowanie na słabszych', 'Miło cię poznać. Przybyłem tu ze Wzgórz Grizli, żeby handlować z twoimi towarzyszami. Mój lud ma tam dużą placówkę i warto, żebyś ją $godwiedził:odwiedziła;, gdy ruszysz na północ.$B$BRozstawiłem sidła w lasach i na zaśnieżonych terenach w okolicy. Mając mięso i futra ze stworzeń, które w nie wpadną, będę miał mnóstwo towaru na wymianę z mieszkańcami.$B$BMogę ci zaoferować udział w zyskach, jeśli zechcesz pomóc zbierać zdobycz z sideł. Uważaj jednak, nie będziesz tam jedynym drapieżnikiem.', 'Traper Jethan z Fortu Wildervar chce, żebyś $gprzyniósł:przyniosła; mu 8 sztuk schwytanej zdobyczy.', '', 'Wróć do trapera Jethana w Forcie Wildervar w Wyjącym Fiordzie.', '', '', '', '', 0),
(11295, 'plPL', 'Ofensywa się zaczyna', 'Nikt zdaje się nie wiedzieć zbyt wiele o wrykulach. Nasze zapiski od stuleci nie wykazują żadnych oznak aktywności na ich ziemiach. A jednak oto są, akurat gdy ruszamy przeciwko Arthasowi.$B$BMapa, którą $gzdobyłeś:zdobyłaś;, jasno pokazuje, że musimy ich pokonać, jeśli nasze siły mają posunąć się dalej w głąb Północnej Grani.$B$BJeden z moich najlepszych sierżantów, plugastwo zwane Gorthem, nadzoruje blokadę za windą. Pomóż mu przeprowadzić uderzenie wyprzedzające na Baleheim. Jeśli wrykule zaatakują, to właśnie stamtąd.', 'Porozmawiaj z sierżantem Gorthem przy blokadzie w pobliżu windy na zachód od Przystani Zemsty w Wyjącym Fiordzie.', '', '', '', '', '', '', 0),
(11296, 'plPL', 'Jeńcy Rozdartego Lasu', 'Coś – najpewniej chodzące trupy zwane Plagą – rozdrażniło tutejsze stworzenia.$B$BEskortując tu mędrca, straciliśmy większość naszych łowców przez rozdzierające wdowy – ogromne i zabójcze pająki zamieszkujące Rozdarty Las na północy.$B$BMuszę zostać tutaj, by chronić niewielki oddział, który nam został, ale ty... ty $gmógłbyś:mogłabyś; sprawdzić, czy moi gońcy wciąż żyją, uwięzieni w kokonach rozdzierających wdów.$B$BZrobisz to, $gnieznajomy:nieznajoma;?', 'Goniec Niebiański Obłok poprosił cię o uwolnienie 7 gońców Zimowego Kopyta. Gdy ci się to uda, wróć do niego przy Stalowej Bramie.', '', 'Wróć do gońca Niebiańskiego Obłoka przy Stalowej Bramie w Wyjącym Fiordzie.', 'Uwolnieni gońcy Zimowego Kopyta', '', '', '', 0),
(11297, 'plPL', 'Oko na intruzów', 'Nawet ziemia nie potrafi powstrzymać fali śmierci, która ją zalewa. Po krainie chodzą trupy, szerząc swój rozkład w zatrważającym tempie.$B$BNiewielka wyprawa wspięła się na zachodnie klify i obozuje w pobliżu Wąwozu Szeptów. Przyjrzyj się temu osobiście, $N. Spróbuj poznać ich cel i odwieść ich od wnoszenia swoich trucizn na nasze ziemie. Ruszaj z obozu na południowy zachód, w stronę klifów nad zachodnią plażą. Ich obóz znajduje się na zachód od wykopaliska przy Stalowej Bramie.', 'Porozmawiaj z aptekarzem Malthusem w Obozie Aptekarzy.', '', '', '', '', '', '', 0),
(11298, 'plPL', 'Co jest w tym trunku?', 'Na południowym wschodzie leży miejsce zwane Wąwozem Szeptów. Roi się tam od członków Ligi Odkrywców, którzy postradali zmysły! Zaatakowali naszą karawanę, gdy przejeżdżała przez tę okolicę, i nękają też nasze grupy zbierające zapasy.$B$BMuszę się dowiedzieć, co wywołuje to szaleństwo! Podejrzewam, że cokolwiek piją z beczułek porozrzucanych po wąwozie, przyczynia się do ich obłędu. Chcę, żebyś $gukradł:ukradła; te beczułki krasnoludom, kiedy będą zajęci kopaniem.', 'Aptekarz Malthus z Obozu Aptekarzy chce, żebyś $gprzyniósł:przyniosła; mu 5 krasnoludzkich beczułek.', '', 'Wróć do aptekarza Malthusa w Obozie Aptekarzy w Wyjącym Fiordzie.', '', '', '', '', 0),
(11299, 'plPL', 'Krąg Sądu', 'Możliwe, że $gwidziałeś:widziałaś; już komnatę, w której trzymają Daegarna, kiedy $gzbierałeś:zbierałaś; tablice. To tym korytarzem, a potem w dół po schodach. Daegarn będzie w komnacie u stóp schodów – zamknięty na cztery spusty!$B$BZejdź tam i go znajdź. W najgorszym razie zdobędziesz od niego szyfr.', 'Znajdź Daegarna w Kręgu Sądu w Katakumbach Utgard.', '', '', '', '', '', '', 0),
(11300, 'plPL', 'Oszałamiająca porażka w Kręgu', 'Oluf wyjdzie, jeśli pokonasz pozostałych gladiatorów. To chyba jedyny sposób, żeby odzyskać ten szyfr. Włóż swoje buty do kopania tyłków i bierz się do roboty w Kręgu Sądu. Jeśli uda ci się odzyskać szyfr, zanieś go Glorenfeldowi, tam przy wejściu do katakumb.$B$BJa? Nie martw się o mnie! Jesteśmy o krok od odkrycia brakującego ogniwa ludzkości!', 'Pokonaj gladiatorów w Kręgu Sądu i zmierz się z Olufem Gwałtownym. Pokonaj Olufa i odzyskaj starożytny szyfr.$B$BZanieś starożytny szyfr Glorenfeldowi przy wejściu do Katakumb Utgard.', '', 'Wróć do Glorenfelda w Katakumbach Utgard w Wyjącym Fiordzie.', '', '', '', '', 0),
(11301, 'plPL', 'Mózgi! Mózgi! Mózgi!', 'Malthus wciągnął cię już w swoją paplaninę o beczkach piwa i szalonych krasnoludach?$B$BNie kwestionuję, że krasnoludy są szalone, ale nie sądzę, żeby kradzież ich piwa na coś się zdała.$B$BPotrzebujemy mózgów. Mnóstwa mózgów. W mig dojdziemy do sedna tej zagadki, a może nawet znajdziemy nowy składnik zarazy.$B$BWeź tę piłę, idź na południowy wschód do Wąwozu Szeptów i zabij sobie trochę krasnoludów. Użyj piły, żeby wydobyć mózgi, i przynieś je tutaj.', 'Aptekarz Grick z Obozu Aptekarzy chce, żebyś $gprzyniósł:przyniosła; mu 12 mózgów obłąkanych odkrywców.', '', 'Wróć do aptekarza Gricka w Obozie Aptekarzy w Wyjącym Fiordzie.', '', '', '', '', 0),
(11302, 'plPL', 'Zagadkowe lodowe nimfy', 'Kiedy szukaliśmy miejsca pod fort, na dwóch polanach tu na północy natknęliśmy się na wrogie stworzenia. Gdy mijaliśmy ośnieżoną polanę tuż na południe od miasta, tamtejsze driady obserwowały nas z zaciekawieniem, ale nie zaatakowały.$B$BByliśmy zmęczeni i wyczerpani pogodą. Mogły z łatwością zabić kilku naszych ludzi, ale tego nie zrobiły.$B$BMoże, wyciągając do nich rękę, zyskamy nieoczekiwanych sojuszników. Czy zechcesz udać się na Zamarzniętą Polanę i nawiązać z nimi kontakt?', 'Porozmawiaj z Lurielle na Zamarzniętej Polanie.', '', '', '', '', '', '', 0),
(11303, 'plPL', 'Zasadzka', 'Wrykule w Baleheimie całkiem pokonane, nie ma wątpliwości. Ale ich przywódca dalej siedzi w mieście i nie chce się poddać.$B$BGorth posłać Lydella i jego zabójców, żeby zrobić dobrą zasadzkę na północnym zachodzie. Ty pogadać z Lydellem i wymyślić, jak wywabić wodza wrykulów. Potem ty go zabić. Zabić go bardzo dobrze.', 'Porozmawiaj z Lydellem przy Zasadzce Lydella.', '', '', '', '', '', '', 0),
(11304, 'plPL', 'Nowy Agamand', 'Obawiam się, że nasz sprzęt tu, w Przystani Zemsty, nie jest najlepszy. W końcu to placówka pod kontrolą wojska.$B$BMusisz zanieść próbkę tego szczepu głównemu siewcy zarazy Harrisowi w Nowym Agamandzie – idź drogą za Baleheimem na południe, a potem na zachód. Mają tam lepszy sprzęt, on będzie wiedział, co robić.$B$BMusisz się spieszyć, $N. Nasi wrogowie są silniejsi i liczniejsi od nas. Musimy opracować skuteczną broń przeciwko nim!', 'Zanieś szczep Lysandra głównemu siewcy zarazy Harrisowi w Nowym Agamandzie, w zachodniej części Wyjącego Fiordu.', '', 'Wróć do głównego siewcy zarazy Harrisa w Nowym Agamandzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11305, 'plPL', 'Formuła szyta na miarę', 'Od tygodni spryskujemy wrykulską wioskę Halgrind, a wrykule wcale nie chcą padać trupem.$B$BSpójrzmy prawdzie w oczy, $N: nasza Zaraza zetknęła się już z ludźmi, krasnoludami, psami, bydłem... czym tylko chcesz. W miarę jak nasze szczepy przystosowują się do nosicieli, do mieszanki trafia coraz więcej zanieczyszczeń. Potrzebujemy szczepu stworzonego specjalnie pod biologię wrykulów.$B$BWódz Halgrind uciekł z wioski, kiedy ją zajęliśmy; znajdziesz go na zachód stąd. Jako patriarcha klanu Smokołupców ma idealną krew.', 'Zdobądź krew patriarchy Smokołupców od Thorvalda w Obozie Thorvalda i zanieś ją głównemu siewcy zarazy Harrisowi w Nowym Agamandzie.', '', 'Wróć do głównego siewcy zarazy Harrisa w Nowym Agamandzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11306, 'plPL', 'Podgrzać i zamieszać', 'Jak dotąd dobrze ci idzie, $N. Chciałbym nauczyć cię kilku moich bardziej zaawansowanych technik, żebyś lepiej $gzrozumiał:zrozumiała; zarazę.$B$BWeź tę pustą flaszkę i napełnij ją krwią z kotła po mojej lewej. Mieszaj ją z próbkami zarazy po mojej prawej, aż uzyskasz dobrze zrównoważoną mieszankę.', 'Napełnij pustą flaszkę aptekarza przy kotle wrykulskiej krwi, a następnie mieszaj flaszkę wrykulskiej krwi z pobliskimi próbkami zarazy Harrisa, aż uzyskasz zrównoważoną miksturę.$B$BPo wykonaniu zadania wróć do głównego siewcy zarazy Harrisa.', '', 'Wróć do głównego siewcy zarazy Harrisa w Nowym Agamandzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11307, 'plPL', 'Próba w terenie', 'Skoro mamy szczep zarazy przystosowany do wrykulskich nosicieli, naprawdę powinniśmy przetestować go na naszych okazach w Halgrind. Jeśli wszystko pójdzie zgodnie z planem, rozpadną się natychmiast, gdy zaraza pożre im wnętrzności!$B$BHalgrind znajdziesz na północ stąd. Nasi siewcy zarazy rozpylają tam poprzedni szczep – nie powinno być trudno ich wypatrzyć.', 'Udaj się do Halgrind i użyj sprayu zarazy na 10 zarażonych wrykulach ze Smokołupców. Wróć do głównego siewcy zarazy Harrisa, by zdać sprawę z wyników.', '', 'Wróć do głównego siewcy zarazy Harrisa w Nowym Agamandzie w Wyjącym Fiordzie.', 'Spryskani zarażeni wrykule', '', '', '', 0),
(11308, 'plPL', 'Czas na sprzątanie', 'Jako człowiek praktyczny ogłaszam nasze badania tutaj za sukces. W końcu której armii nie da się powstrzymać, obracając jej szeregowych żołnierzy przeciwko sobie?$B$BNiedługo poślę wieść o naszych osiągnięciach do Przystani Zemsty. Ale najpierw musisz posprzątać nasz teren doświadczalny.$B$BPomów z Jenny „Piła” o zrobieniu ci plugastwa na zamówienie. Takiego z wybuchową siłą, jeśli rozumiesz, o co mi chodzi.', 'Porozmawiaj z Jenny „Piła” w Nowym Agamandzie.', '', '', '', '', '', '', 0),
(11309, 'plPL', 'Części do roboty', 'Więc Harris chce roboty rozbiórkowej, co? Jasne, mogę pomóc.$B$BBędziesz $gmusiał:musiała; jednak zdobyć mi trochę części. Nie mogę sobie pozwolić na zużycie moich najlepszych komponentów na coś, co i tak wyleci w powietrze.$B$BPo pierwsze, będę potrzebować ścięgien łopatokła... są o niebo lepsze niż ludzkie.$B$BPotrzebuję też funta ciała. Gość imieniem Anton sprzedaje tanie mięso. Kręci się po drodze na zachodzie.', 'Jenny „Piła” z Nowego Agamandu chce, żebyś $gzdobył:zdobyła; 6 ścięgien łopatokła i 1 świeży funt ciała.', '', 'Wróć do Jenny „Piła” w Nowym Agamandzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11310, 'plPL', 'Uwaga: wymaga złożenia', 'No to proszę! Nasz przyjaciel będzie nieco... niestabilny. Więc radzę nie składać go, dopóki nie dotrzesz do Halgrind.$B$BNa miejscu użyj plugastwa, żeby zgonić jak najwięcej wrykulów, zanim samo się zniszczy.$B$BKiedy skończysz, wróć z tym, co zostanie. Zawsze przydadzą mi się dodatkowe części ciała!', 'Użyj zestawu do składania plugastwa w Halgrind i zganiaj zarażonych wrykulów swoim bezmyślnym plugastwem. Zabij co najmniej 20, a gdy skończysz, wróć do Jenny „Piła” w Nowym Agamandzie.', '', 'Wróć do Jenny „Piła” w Nowym Agamandzie w Wyjącym Fiordzie.', 'Wytępieni zarażeni wrykule', '', '', '', 0),
(11311, 'plPL', 'Poskramianie żywiołów', 'Jeśli masz tu przetrwać, tak jak my, musisz nauczyć się stawiać czoła wyzwaniom otoczenia. Żywioły odbiorą ci życie, jeśli nie zachowasz czujności, o czym świadczy mnogość żywiołaków na tych północnych wzgórzach.$B$BMusimy ostatni raz przetrzebić żywiołaki, zanim opuścimy to miejsce. Czy zechcesz nam pomóc, gdy będziemy kontynuować przygotowania?$B$BMusisz zabić wszystkie żywiołaki lodowych odłamków i wyjące cyklony, które napotkasz na zaśnieżonych wzgórzach wokół obozu.', 'Poskramiacz wiatru Kagan z Obozu Zimowego Kopyta chce, żebyś $gzabił:zabiła; 8 górskich żywiołaków. Możesz zabijać wyjące cyklony lub żywiołaki lodowych odłamków.', '', 'Wróć do poskramiacza wiatru Kagana w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', 'Zabite górskie żywiołaki', '', '', '', 0),
(11312, 'plPL', 'Zamarznięta Polana', 'Od pokoleń mój lud opowiada o lodowych nimfach swawolących na polanach ukrytych w dziczy. Jako dziecko szukałam ich wbrew radom rodziców, aż omal nie zamarzłam na śmierć.$B$BDziś nie trzeba przeczesywać lasów, by je znaleźć. Postanowiły się ujawnić z powodów, których mogę się tylko domyślać, ale nie sądzę, by można było zignorować tę zmianę. Wyrusz na południowy wschód, na Zamarzniętą Polanę, i odszukaj nimfy, ale uważaj – po drodze miniesz Pokręconą Polanę.', 'Porozmawiaj z Lurielle na Zamarzniętej Polanie.', '', '', '', '', '', '', 0),
(11313, 'plPL', 'Duchy lodu', 'Lodowe żywiołaki otaczające naszą polanę były kiedyś naszymi towarzyszami, ale przez ziemię przetoczyła się niestabilna i niszczycielska siła, która zwróciła je przeciwko nam!$B$BTo tylko jedna z okropności, które znosiłyśmy z siostrami. Ujawniłyśmy się przed tobą w nadziei, że pomożesz nam powstrzymać rozkład, który wkradł się na nasze polany i zatruł nasze siostry!$B$BZbieramy rdzenie lodowych żywiołaków i przechowujemy je bezpiecznie, byśmy pewnego dnia mogły je przywrócić. Pomożesz?', 'Lurielle z Zamarzniętej Polany chce, żebyś $gprzyniósł:przyniosła; jej 15 lodowych rdzeni.', '', 'Wróć do Lurielle na Zamarzniętej Polanie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11314, 'plPL', 'Upadłe siostry', 'Na południowym zachodzie była polana, która kiedyś wyglądała bardzo podobnie do tej. Tajemnicze siły i obca magia zmieniają oblicze ziemi. Polana odtajała, a mieszkające tam siostry oszalały od nagłej zmiany.$B$BChciałyśmy do nich dotrzeć, ale nas zaatakowały. Obawiam się, że wiele z nich nie da się już ocalić, ale nie mogę tracić nadziei.$B$BWeź mój wisior, udaj się na południowy zachód, na Tętniącą Polanę, i użyj go, by spróbować uwolnić moje siostry.', 'Lurielle z Zamarzniętej Polany chce, żebyś $gużył:użyła; jej wisiora na 7 mroźnych nimfach.', '', 'Wróć do Lurielle na Zamarzniętej Polanie w Wyjącym Fiordzie.', 'Uwolnione mroźne nimfy', '', '', '', 0),
(11315, 'plPL', 'Dzikie pnącza', 'Siostry, które mieszkały na Tętniącej Polanie na południowym zachodzie, pielęgnowały tam przepiękne kobierce szkarłatnego bluszczu, ale ta sama siła, która doprowadziła je do szaleństwa, przemieniła ich ukochany bluszcz.$B$BPnącza chwytają teraz za nogi nieostrożnych albo smagają każdego, kto zbliży się do polany. Zanim odzyskamy polanę, pnącza trzeba poskromić i wyrwać z korzeniami.$B$BOczyść z bluszczu tyle, ile zdołasz. Już zaczął rozrastać się bez kontroli.', 'Lurielle z Zamarzniętej Polany chce, żebyś $gzabił:zabiła; 8 szkarłatnych bluszczy.', '', 'Wróć do Lurielle na Zamarzniętej Polanie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11316, 'plPL', 'Pomioty Pokręconej Polany', 'Polana na zachodzie zmieniła się w ohydne miejsce zwane Pokręconą Polaną. Wśród drzew, kamieni i w sadzawce polany żyją okropne bestie.$B$BNie potrafię zgadnąć, skąd się wzięły te stworzenia ani jakie straszne siły je ożywiają, ale trzeba się z nimi rozprawić!$B$BObawiam się, że jeśli pozwolimy im zawładnąć polaną, zatrują ją bezpowrotnie. Oczyść polanę z tych stworzeń, które wymordowały nasze siostry.', 'Lurielle z Zamarzniętej Polany chce, żebyś $gzabił:zabiła; 10 ciernistych pełzaczy.', '', 'Wróć do Lurielle na Zamarzniętej Polanie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11317, 'plPL', 'Oczyszczenie', 'Zapuściliśmy się do Rozdartego Lasu z powodu moich niespokojnych snów o przyjacielu na śmierć i życie, worgu Ulfangu. Wzywał pomocy, a ty musisz do niego pójść.$B$BNie masz jednak sposobu, by z nim rozmawiać ani chodzić wśród innych worgów. Znam na to sposób.$B$BNajpierw musisz oczyścić swój wewnętrzny zamęt.$B$BNa wierzchołku Szczytu Mroźnego Ostrza, na północny wschód od Obozu Zimowego Kopyta, stoi kapliczka. Prowadzi do niej jedna ścieżka od zachodniego podnóża góry.$B$BMedytuj tam, a potem wróć do mnie.', 'Mędrzec Mglisty Krok przy Stalowej Bramie radzi ci oczyścić się z twojego wewnętrznego zamętu, medytując przy Kapliczce Mroźnego Ostrza.', '', 'Wróć do mędrca Mglisty Krok przy Stalowej Bramie w Wyjącym Fiordzie.', 'Oczyszczenie z wewnętrznego zamętu', '', '', '', 0),
(11319, 'plPL', 'Nasiona czarnodusznych opiekunów', 'Polana na północnym zachodzie, dziś Pokręcona Polana, była kiedyś domem wielu opiekunów polany. Razem z siostrami dbali o nią.$B$BGdy polana się zmieniła, siostry zginęły, ale opiekunom jakoś udało się przetrwać. Teraz obsiewają ziemię trującymi zarodnikami, od których więdnie zdrowa zieleń.$B$BDam ci jeden z rdzeni lodowych żywiołaków. Gdy zniszczysz zarodnik, zamroź go lodowym kryształem, żeby się nie odrodził.', 'Lurielle z Zamarzniętej Polany chce, żebyś $gzamroził:zamroziła; 8 zarodników.', '', 'Wróć do Lurielle na Zamarzniętej Polanie w Wyjącym Fiordzie.', 'Zamrożone zarodniki', '', '', '', 0),
(11322, 'plPL', 'Oczyszczenie', 'Ostatnio dręczą mnie koszmary o worgu imieniem Ulfang. Wzywał pomocy, a ty musisz do niego pójść.$B$BNie masz jednak sposobu, by z nim rozmawiać ani chodzić wśród innych worgów. Znam na to sposób.$B$BAle najpierw musisz oczyścić swój wewnętrzny zamęt przez medytację.$B$BNa wierzchołku Szczytu Mroźnego Ostrza, daleko na północnym wschodzie, stoi kapliczka. Prowadzi do niej jedna ścieżka od zachodniego podnóża góry.$B$BMedytuj tam, by się oczyścić, a potem wróć do mnie.', 'Wartowniczka Księżycowy Liść przy Stalowej Bramie radzi ci oczyścić się z twojego wewnętrznego zamętu, medytując przy Kapliczce Mroźnego Ostrza.', '', 'Wróć do wartowniczki Księżycowego Liścia przy Stalowej Bramie w Wyjącym Fiordzie.', 'Oczyszczenie z wewnętrznego zamętu', '', '', '', 0),
(11323, 'plPL', 'W worgowej skórze', 'Z moich snów wiem, że Ulfang jest w jaskini na zaśnieżonym północno-zachodnim skraju Rozdartego Lasu.$B$BGrozi mu wielkie niebezpieczeństwo.$B$BOpracowałem magiczne przebranie, dzięki któremu w Rozdartym Lesie będziesz wyglądać jak worg. Przebranie jest słabe, opiera się na dziwnej magii tego nawiedzonego lasu. Choć zwiedzie tylko worgi, pozwoli ci zbliżyć się do Ulfanga.$B$BProszę, $N, odnajdź go i pomóż mu.', 'Mędrzec Mglisty Krok poprosił cię, byś $godnalazł:odnalazła; Ulfanga w Rozdartym Lesie i $gpomógł:pomogła; mu.$B$BJeśli w jakiś sposób stracisz przebranie worga, wróć do mędrca Mglisty Krok po nowe.', '', '', '', '', '', '', 0),
(11324, 'plPL', 'Worg alfa', 'Gdy zjesz oczy Szponodzierzby, powinno ci się udać zobaczyć Garwala i rozszarpać mu gardło!$B$BObcy stworze, odszukaj i zabij Garwala w zachodniej części Rozdartego Lasu. Gdy go zabijesz, idź i powiedz Mglistemu Krokowi, że znów jestem worgiem alfa!', 'Ulfang poprosił cię o zabicie Garwala. Potem zwróć przebranie worga mędrcowi Mglisty Krok przy Stalowej Bramie.', '', 'Wróć do mędrca Mglisty Krok przy Stalowej Bramie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11325, 'plPL', 'W worgowej skórze', 'Z moich snów wiem, że Ulfang jest w jaskini na zaśnieżonym północno-zachodnim skraju Rozdartego Lasu.$B$BGrozi mu wielkie niebezpieczeństwo!$B$BOpracowałam magiczne przebranie, dzięki któremu w Rozdartym Lesie będziesz wyglądać jak worg. Przebranie jest słabe, opiera się na dziwnej magii tego nawiedzonego lasu. Choć zwiedzie tylko worgi, pozwoli ci zbliżyć się do Ulfanga.$B$BProszę, $N, odnajdź go i pomóż mu.', 'Wartowniczka Księżycowy Liść poprosiła cię, byś $godnalazł:odnalazła; Ulfanga w Rozdartym Lesie i $gpomógł:pomogła; mu.$B$BJeśli w jakiś sposób stracisz przebranie worga, wróć do wartowniczki Księżycowego Liścia po nowe.', '', '', '', '', '', '', 0),
(11326, 'plPL', 'Worg alfa', 'Gdy zjesz oczy Szponodzierzby, powinno ci się udać zobaczyć Garwala i rozszarpać mu gardło!$B$BObcy stworze, odszukaj i zabij Garwala w zachodniej części Rozdartego Lasu. Gdy go zabijesz, idź i powiedz Księżycowemu Liściowi, że znów jestem worgiem alfa!', 'Ulfang poprosił cię o zabicie Garwala. Potem zwróć przebranie worga wartowniczce Księżycowemu Liściowi przy Stalowej Bramie.', '', 'Wróć do wartowniczki Księżycowego Liścia przy Stalowej Bramie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11327, 'plPL', 'Misja: odzyskanie paczki', 'No, do licha, potrzebujemy trochę tego zarazowego świństwa.$B$BWiem!$B$BKiedy $gniszczyłeś:niszczyłaś; kadzie, przypadkiem wypatrzyłem jednego z aptekarzy z Nowego Agamandu, którego wrykule wciągali do Halgrind. Biedaczysko.$B$B$N, założę się o co chcesz, że ten aptekarz ma przy sobie towar. Myślisz, że $gzdołałbyś:zdołałabyś; wejść do Halgrind i odzyskać jego paczkę?', 'Zwiadowca Knowles poprosił cię o odzyskanie paczki aptekarza z wnętrza Halgrind. Gdy ją zdobędziesz, wróć do zwiadowcy przy Wieży Żarzącej Włóczni.', '', 'Wróć do zwiadowcy Knowlesa przy Wieży Żarzącej Włóczni w Wyjącym Fiordzie.', '', '', '', '', 0),
(11328, 'plPL', 'Misja: sekrety Porzuconych', 'Dobra, myślę, że $gpowinieneś:powinnaś; zanieść to Peppy Krzywej Dyszy w twierdzy. Jest kimś w rodzaju alchemiczki amatorki, ale nikogo lepszego nie mamy.$B$BJedno o Peppy: bardzo lubi wypić. Więc pewnie znajdziesz ją w tawernie, jak „chłonie atmosferę”.$B$BJestem pewien, że będzie wiedziała, co robić.', 'Zwiadowca Knowles poprosił cię o dostarczenie paczki aptekarza Peppy Krzywej Dyszy w Twierdzy Zachodniej Straży.', '', 'Wróć do Peppy Krzywej Dyszy w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', '', '', '', '', 0),
(11329, 'plPL', 'Spróbuję wszystkiego!', 'Nie chcę już nigdy w życiu oglądać beczki solonej ryby! Dzień w dzień napełniam beczki, a wciąż są kolejne do napełnienia!$B$BSzkoda, że zużyłem całą przynętę, którą kupiłem od Nata Pagle\'a. Działała jak czary, naprawdę. Teraz mam szczęście, jeśli złowię jedną rybę na godzinę!$B$BSłyszałem, że północne kolczaste ryby to całkiem dobra przynęta, ale kto jest na tyle szalony, żeby nurkować w lodowatym jeziorze i siekać wodne rośliny w ich poszukiwaniu? Nie ja... ale może, tylko może, uda mi się namówić ciebie...', 'Christopher Sloan z Fortu Wildervar chce, żebyś $gprzyniósł:przyniosła; mu 5 północnych kolczastych ryb.', '', 'Wróć do Christophera Sloana w Forcie Wildervar w Wyjącym Fiordzie.', '', '', '', '', 0),
(11330, 'plPL', 'Abszolutnie... to szię uda!', 'Voilà, błyszkawiczna szczepionka na zarazę!$B$BAle na pewno nie wypróbuję tego na szobie. I wiem, że ty też nie chceszsz być moim króliczkiem doszwiadczalnym!$B$BO, mam... mam pomysł!$B$BW celach pod twierdzą trzymamy wrykulskiego więźnia. Może zaniesieszsz tam tę mieszankę, którą zmajsztrowałam, i każesz temu olbrzymowi ją wypić ...hik?!', 'Peppy Krzywa Dysza z Twierdzy Zachodniej Straży zasugerowała, byś $gpodał:podała; specjalną mieszankę Peppy pojmanemu wrykulowi ze Smokołupców i $gzobaczył:zobaczyła;, jak działa.', '', 'Wróć do Peppy Krzywej Dyszy w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', 'Mieszanka Peppy podana wrykulskiemu więźniowi', '', '', '', 0),
(11331, 'plPL', 'Ty mu powiedz ...hik!', 'Szłuchaj. Nie idę do kapitana z tymi wieszciami. Jesztem alchemiczką amatorką, to nie moja robota, a w ogóle mam przerwę!$B$BPoza tym on jeszt wielkim marudą... a ty znaszsz go lepiej niż ja!$B$BTo szobie idź na górę do twierdzy i mu powiedz. Na pewno podejdzie do całej szprawy rozsządnie ...hik.$B$B<Peppy wraca do picia.>', 'Peppy Krzywa Dysza wrobiła cię w przekazanie kapitanowi Adamsowi złych wieści o zarazie Porzuconych. Odwiedź go w Twierdzy Zachodniej Straży.', '', '', '', '', '', '', 0),
(11332, 'plPL', 'Misja: Zaraza na nich!', 'Królewskie Zakłady Chemiczne myślą, że udoskonalą nową zarazę, która rozpuści nas tam, gdzie stoimy?!$B$BNie za mojej warty!$B$BIdź na dziedziniec i porozmawiaj z Greerem Orehammerem. Ma dla ciebie gotowego gryfa i trochę bomb. Rozbombarduj zbiorniki z zarazą w Nowym Agamandzie w drobny mak!', 'Kapitan Adams rozkazał ci trafić bombami 5 razy w zbiorniki z zarazą w Nowym Agamandzie. Nie wracaj do niego do Twierdzy Zachodniej Straży, dopóki tego nie zrobisz.', '', 'Wróć do kapitana Adamsa w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', 'Trafienia w zbiorniki z zarazą', '', '', '', 0),
(11333, 'plPL', 'W świat duchów', 'Choć Liga Odkrywców może poznać strzępy przeszłości dzięki swoim znaleziskom archeologicznym, a wiceadmirał może wydobyć nieco wiedzy o teraźniejszości brutalną siłą, prawda leży w duchach.$B$BZ odpowiednimi składnikami potrafię zajrzeć do świata duchów. To tam spoczywa przeszłość, teraźniejszość i przyszłość Północnej Grani.$B$BJeśli chcesz dowiedzieć się więcej, potrzebuję mojej sakiewki na składniki. Przepadła na statku, który spoczywa teraz na dnie Zatoki Sztyletu, tuż na wschód stąd.', 'Thoralius Mądry z Valgardu chce, żebyś $godnalazł:odnalazła; jego sakiewkę na składniki.', '', 'Wróć do Thoraliusa Mądrego w Valgardzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11343, 'plPL', 'Echo Ymirona', 'Świat duchów znalazł się pod władzą Króla Lisza. Straszliwe stworzenia utkane z czystego koszmaru strzegą teraz królestwa żywiołów. Wyczuwam, że te val\'kyrie strzegą strasznej tajemnicy.$B$BJestem za stary i za słaby, by przetrwać kolejną podróż. Musisz pójść za mnie, $N.$B$BZanieś tę kadzielnicę do Wioski Czaszki Żmija i użyj jej, by wejść do świata duchów. Znajdź duże domostwo na północnym wschodzie! Za wszelką cenę unikaj val\'kyrii, bo inaczej na zawsze zostaniesz w ich świecie.', 'Thoralius Mądry chce, żebyś w świecie duchów $gprzeszukał:przeszukała; Wioskę Czaszki Żmija i $gznalazł:znalazła; informacje o Sekretach Czaszki Żmija.', 'Odkryte Sekrety Czaszki Żmija', 'Wróć do Thoraliusa Mądrego w Valgardzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11344, 'plPL', 'Męczarnia Nifflevaru', 'Wszystko, co wiemy o wrykulach, wskazuje, że pojawili się w Północnej Grani dopiero niedawno. Dlaczego więc widzimy wrykulów w wizjach sprzed 15 000 lat? Gdyby wrykule istnieli wcześniej w Północnej Grani, z pewnością byśmy o tym wiedzieli.$B$BMusisz ruszyć dalej, do Nifflevaru. Aby tam dotrzeć, idź na północny wschód przez Wioskę Czaszki Żmija i wejdź na ścieżkę prowadzącą w górę przez tamę. Nifflevar leży na urwiskach fiordu.$B$BGdy dotrzesz do Nifflevaru, użyj kadzielnicy i przeszukaj okolicę w poszukiwaniu wskazówek.', 'Thoralius Mądry chce, żebyś w świecie duchów $gprzeszukał:przeszukała; Nifflevar i $gznalazł:znalazła; informacje o Sekretach Nifflevaru.', 'Odkryte Sekrety Nifflevaru', 'Wróć do Thoraliusa Mądrego w Valgardzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11346, 'plPL', 'Księga run', 'Rozległy skalisty teren na południowym wschodzie, Szlak Olbrzymów, opanowały żelazne krasnoludy. Zwiadowcy donoszą, że widzieli, jak krasnoludy wywabiają kamienne olbrzymy z ziemi, a potem rzeźbią na nich runy.$B$BNie pojmuję ich motywów, ale podejrzewam, że w jakiś sposób próbują zrobić z olbrzymów broń. Przywoływacze kamienia i pętacze żelaznych run noszą przy sobie wielkie tomy, które muszą zawierać runy rzeźbione na olbrzymach.$B$BZdobądź fragmenty tej księgi, złóż je i przynieś mi, $N.', 'Poszukiwacz Belvar z Fortu Wildervar chce, żebyś $gprzyniósł:przyniosła; mu Księgę run.', '', 'Wróć do poszukiwacza Belvara w Forcie Wildervar w Wyjącym Fiordzie.', '', '', '', '', 0),
(11348, 'plPL', 'Runa rozkazu', 'Czujesz moc bijącą od run, które wyryłem na tej tablicy? To pomniejszone wersje run, których używają żelazne krasnoludy. Posłużymy się nią, żeby położyć kres ich przedsięwzięciu.$B$BZabierz ją na Szlak Olbrzymów i użyj jej na kamiennym olbrzymie, którego krasnoludy jeszcze nie odmieniły.$B$BOlbrzym powinien być ci posłuszny, ale tak dopasowałem runy, żeby po jakimś czasie przywróciły mu naturalny stan. Olbrzym może okazać się cennym sprzymierzeńcem w walce z Pętaczem Murdisem, przywódcą sił żelaznych krasnoludów na Szlaku Olbrzymów.', 'Poszukiwacz Belvar z Fortu Wildervar chce, żebyś $gwypróbował:wypróbowała; Runę rozkazu i $gpokonał:pokonała; Pętacza Murdisa.', '', 'Wróć do poszukiwacza Belvara w Forcie Wildervar w Wyjącym Fiordzie.', 'Wypróbuj Runę rozkazu', '', '', '', 0),
(11349, 'plPL', 'Opanowanie run', 'Mam przy sobie komplet kilofów, młotów i dłut, ale do rzeźbienia tych run się nie nadają. Narzędzia żelaznych krasnoludów nasyca się magią już podczas wykuwania.$B$BGdy ryje się nimi runy, znaki stają się czymś znacznie więcej niż zwykłymi słowami. Te runy mają moc wiązania, zniewalania i wypaczania.$B$BChyba wiem, jak to działa, ale bez kompletu tych narzędzi nie mogę być pewien. Poszukaj zestawów podobnych do mojego przy pawilonach żelaznych krasnoludów na Szlaku Olbrzymów i przynieś mi je.', 'Przynieś komplet Narzędzi do rzeźbienia żelaznych run Poszukiwaczowi Belvarowi w Forcie Wildervar.', '', 'Wróć do poszukiwacza Belvara w Forcie Wildervar w Wyjącym Fiordzie.', '', '', '', '', 0),
(11350, 'plPL', 'Księga run', 'Wódz Popielny Totem wysłał mnie na zwiad na Szlak Olbrzymów, szeroki, skalisty płaskowyż na południowym wschodzie, za Zamarzniętą Polaną.$B$BOkolicę zajęły żelazne krasnoludy, które najwyraźniej odmieniają olbrzymy, gdy tylko te wyłaniają się z ziemi.$B$BPrzywoływacze kamienia i pętacze żelaznych run noszą przy sobie wielkie tomy, w których muszą być zapisane runy ryte na olbrzymach.$B$BZdobądź fragmenty tej księgi, złóż je i przynieś mi. Tylko tak poznamy ich plany.', 'Goniec Pembe z Obozu Zimowego Kopyta chce, żebyś $gprzyniósł:przyniosła; mu Księgę run.', '', 'Wróć do Gońca Pembe w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', '', '', '', '', 0),
(11351, 'plPL', 'Opanowanie run', 'Chyba już wiem, co robią żelazne krasnoludy. Ich narzędzia nasyca się magią podczas wykuwania.$B$BGdy ryje się nimi runy, znaki stają się czymś znacznie więcej niż zwykłymi słowami. Te runy mają moc wiązania, zniewalania i wypaczania.$B$BGdybym miał komplet tych narzędzi, mógłbym odtworzyć runy z księgi. Zdobyłem jedną z tych skrzynek w pawilonie na Szlaku Olbrzymów, ale była pusta. Poszukaj podobnych skrzynek i wydobądź z nich komplet narzędzi.', 'Przynieś komplet Narzędzi do rzeźbienia żelaznych run Gońcowi Pembe w Obozie Zimowego Kopyta.', '', 'Wróć do Gońca Pembe w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', '', '', '', '', 0),
(11352, 'plPL', 'Runa rozkazu', 'Czujesz moc bijącą od run, które wyryłem na tej tablicy? To pomniejszone wersje run, których używają żelazne krasnoludy. Posłużymy się nią, żeby położyć kres ich przedsięwzięciu.$B$BZabierz ją na Szlak Olbrzymów i użyj jej na kamiennym olbrzymie, którego krasnoludy jeszcze nie odmieniły.$B$BOlbrzym powinien być ci posłuszny, ale tak dopasowałem runy, żeby po jakimś czasie przywróciły mu naturalny stan. Olbrzym może okazać się cennym sprzymierzeńcem w walce z Pętaczem Murdisem, przywódcą sił żelaznych krasnoludów na Szlaku Olbrzymów.', 'Goniec Pembe z Obozu Zimowego Kopyta chce, żebyś $gwypróbował:wypróbowała; Runę rozkazu i $gpokonał:pokonała; Pętacza Murdisa.', '', 'Wróć do Gońca Pembe w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', 'Wypróbuj Runę rozkazu', '', '', '', 0),
(11355, 'plPL', 'Pochód olbrzymów', 'Na wschodzie, na Szlaku Olbrzymów, pokryte runami kamienne olbrzymy zaczęły wędrować na północ, w stronę Szczytu Mroźnego Ostrza. Dokąd ostatecznie zmierzają, nie wiem.$B$BW tej wędrówce prowadzą je świecące runy wyryte w ich kamiennych ciałach.$B$BUżyj tego kilofa, żeby unieszkodliwić runy na zwłokach olbrzymów, i wróć z tym, czego się dowiesz.', 'Badacz Aderan z Fortu Wildervar chce, żebyś $gużył:użyła; Kilofa poszukiwacza run na zwłokach 4 runicznych kamiennych olbrzymów.', '', 'Wróć do Badacza Aderana w Forcie Wildervar w Wyjącym Fiordzie.', 'Zbadane zwłoki runicznego kamiennego olbrzyma', '', '', '', 0),
(11358, 'plPL', 'Magnes', 'Jeśli ustalimy, co wabi olbrzymy na północny zachód, może zdołamy je powstrzymać, zanim dotrą do celu.$B$BChoć odczytałem wiele run z próbek, które mi $gprzyniosłeś:przyniosłaś;, najbardziej niepokoją mnie te, których nie znam. Kiedy byłem na Szlaku Olbrzymów, zauważyłem wielką rozbitą tablicę sterczącą z ziemi tam, gdzie północno-wschodni skraj okolicy styka się ze śniegiem u stóp Szczytu Mroźnego Ostrza. Weź tę próbkę, porównaj runy z tablicą i zobacz, czego się dowiesz.', 'Badacz Aderan z Fortu Wildervar chce, żebyś $gporównał:porównała; Próbkę run z Rozbitą tablicą.', '', 'Wróć do Badacza Aderana w Forcie Wildervar w Wyjącym Fiordzie.', 'Porównaj runy z Rozbitą tablicą', '', '', '', 0),
(11359, 'plPL', 'Rozbicie Megalita', 'Pętacz Murdis stworzył Megalita jako najpotężniejszego z runicznych olbrzymów, by prowadził je w ich misji. Gdy Megalit padnie, zostaną zagubione i bez kierunku. Kiedy przybędą siły ekspedycyjne, nasi żołnierze zdołają odciąć i pokonać pozostałe olbrzymy, a ich panów, żelazne krasnoludy, wykurzyć z obozów.$B$BPrzeszukaj podnóże Szczytu Mroźnego Ostrza na północ od Szlaku Olbrzymów, znajdź Megalita i pokonaj go!', 'Pokonaj Megalita i wróć do Badacza Aderana w Forcie Wildervar.', '', 'Wróć do Badacza Aderana w Forcie Wildervar w Wyjącym Fiordzie.', '', '', '', '', 0),
(11365, 'plPL', 'Pochód olbrzymów', 'Na wschodzie, na Szlaku Olbrzymów, pokryte runami kamienne olbrzymy zaczęły wędrować na północ, w stronę Szczytu Mroźnego Ostrza. Nie wiem nic ani o ich celach, ani o tym, dokąd zmierzają.$B$BW tej wędrówce prowadzą je świecące runy wyryte w ich kamiennych ciałach. Powal kilka tych olbrzymów.$B$BWeź ze sobą ten kilof i użyj go na zwłokach runicznych kamiennych olbrzymów. Unieszkodliwi runy. Gdy zbadasz dość olbrzymów, wróć do mnie z tym, czego się dowiesz.', 'Mędrzec Edan z Obozu Zimowego Kopyta chce, żebyś $gużył:użyła; Kilofa poszukiwacza run na zwłokach 4 runicznych kamiennych olbrzymów.', '', 'Wróć do Mędrca Edana w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', 'Zbadane zwłoki runicznych kamiennych olbrzymów', '', '', '', 0),
(11366, 'plPL', 'Magnes', 'Musimy ustalić, co wabi olbrzymy na północny zachód, żeby je powstrzymać, zanim dotrą do celu.$B$BPróbki run dały nam pewne wskazówki, ale te nieznane runy mnie niepokoją.$B$BKiedy byłem na Szlaku Olbrzymów, zauważyłem wielką rozbitą tablicę sterczącą z ziemi tam, gdzie północno-wschodni skraj okolicy styka się ze śniegiem u stóp Szczytu Mroźnego Ostrza. Weź tę próbkę, porównaj runy z tablicą i zobacz, czego się dowiesz o tym, czym jest ten magnes.', 'Mędrzec Edan z Obozu Zimowego Kopyta chce, żebyś $gporównał:porównała; Próbkę run z Rozbitą tablicą.', '', 'Wróć do Mędrca Edana w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', 'Porównaj runy z Rozbitą tablicą', '', '', '', 0),
(11367, 'plPL', 'Rozbicie Megalita', 'Pętacz Murdis stworzył Megalita jako swego rodzaju zwornik dla runicznych olbrzymów, by prowadził je w ich misji. Gdy Megalit padnie, zostaną zagubione i bez kierunku. Poproszę Wodza Popielnego Totema, żeby w drodze na północ odesłał część naszych ludzi do wybicia ostatnich runicznych olbrzymów. Bez swoich olbrzymów żelazne krasnoludy nie zdołają nam się oprzeć.$B$BPrzeszukaj podnóże Szczytu Mroźnego Ostrza na północ od Szlaku Olbrzymów, znajdź Megalita i pokonaj go!', 'Pokonaj Megalita i wróć do Mędrca Edana w Obozie Zimowego Kopyta.', '', 'Wróć do Mędrca Edana w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', '', '', '', '', 0),
(11390, 'plPL', 'Mam fruwającą maszynę!', 'No, na co czekasz, robota czeka!$B$BTu masz kluczyki do naszej fruwającej maszyny. Złap trzy worki reliktów i wciągnij je na platformy dźwigów po północnej i południowej stronie Stalowej Bramy. Zaznaczę ci je.$B$BRuszaj się! Nie mamy całego dnia!', 'Główny archeolog Stalowej Bramy chce, żebyś $gprzetransportował:przetransportowała; 3 Worki reliktów z dna wykopaliska na platformę po północnej lub południowej stronie Stalowej Bramy.$B$BUżyj do tego haka z liną we fruwającej maszynie.$B$BPotem zamelduj się u niego.', '', 'Wróć do Głównego archeologa Stalowej Bramy w Stalowej Bramie w Wyjącym Fiordzie.', 'Dostarczone worki reliktów', '', '', '', 0),
(11391, 'plPL', 'Patrol nad Stalową Bramą', 'Hę? $GWróciłeś:Wróciłaś; na kolejny dzień roboty?$B$BNo dobra, tu masz kluczyki. Dziś nie trzeba niczego dźwigać, więc po prostu miej oko na wszystko, co podejrzane, dobra?$B$BPodczepiłem jej parę rakiet i karabin maszynowy, tak na wszelki wypadek.', 'Jesteś teraz asem pilotażu Stalowej Bramy, więc Główny archeolog Stalowej Bramy chce, żebyś $gpatrolował:patrolowała; okolice wykopaliska i $godpierał:odpierała; wszystko, co zaatakuje.$B$BPo patrolu zamelduj się u niego.', '', 'Wróć do Głównego archeologa Stalowej Bramy w Stalowej Bramie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11393, 'plPL', 'Gdzie jest Odkrywca Jaren?', '$N, mój narzeczony, Jaren, poszedł na zachód z małą grupą odkrywców, żeby sprawdzić pogłoski o artefaktach na Wybrzeżu Chłodnego Jeziora. Ale tam na dole są murloki i obawiam się, że spotkało ich najgorsze.$B$BZnajdziesz chyba chwilę, żeby sprawdzić, czy nic im nie jest? Na plażę można zejść tuż na południowy zachód stąd, tylko uważaj na worgi i inne stwory czające się w lesie.', 'Nadzorczyni Irena Kamienny Płaszcz poprosiła cię o odnalezienie jej narzeczonego, Odkrywcy Jarena.', '', '', '', '', '', '', 0),
(11394, 'plPL', 'A myślisz, że to murloki śmierdzą!', 'Przyszedłem tu pierwotnie, żeby sprawdzić pogłoski o artefaktach do wykopania. Wiedziałem, że na tym wybrzeżu są murloki, ale w życiu bym się nie spodziewał, że zobaczę coś takiego.$B$B<Odkrywca wychyla głowę zza drzewa i rozgląda się.>$B$BTam jest Plaga i zamienia murloki, i wszystko, co jej wpadnie w łapy, w chodzące trupy!$B$BMyślę, że naszym obowiązkiem jest coś z tym zrobić. $GDałbyś:Dałabyś; radę wybić sporą część tej Plagi?', 'Odkrywca Jaren poprosił cię o zabicie 15 dowolnych sług Plagi na Wybrzeżu Chłodnego Jeziora. Potem wróć do niego.', '', 'Wróć do Odkrywcy Jarena na Wybrzeżu Chłodnego Jeziora w Wyjącym Fiordzie.', 'Zabici słudzy Plagi z Wybrzeża Chłodnego Jeziora', '', '', '', 0),
(11395, 'plPL', 'To urządzenie Plagi', 'Stwór Plagi, którego właśnie $gzniszczyłeś:zniszczyłaś;, ściskał w szponach to urządzenie. Osadzono w nim klejnot podobny do tego, który wieńczy kryształy Plagi.$B$BOdkrywca Jaren na pewno chciałby mu się przyjrzeć.', 'Dostarcz Urządzenie Plagi Odkrywcy Jarenowi na Wybrzeżu Chłodnego Jeziora.', '', 'Wróć do Odkrywcy Jarena na Wybrzeżu Chłodnego Jeziora w Wyjącym Fiordzie.', '', '', '', '', 0),
(11396, 'plPL', 'Zbij te tarcze', 'Spójrz na przycisk z boku sterownika. Założę się, że jeśli podejdziesz dość blisko do któregoś z kryształów Plagi, zdołasz tym sterownikiem zbić jego tarczę. Wtedy wystarczy zniszczyć to coś, zanim tarcza wróci.$B$BCo ty na to, $N? Wchodzisz w to? Gwarantuję ci porządną nagrodę, jeśli zbijesz te tarcze i zniszczysz kryształy.$B$BTo najmniej, co możemy zrobić, żeby Plaga nie tworzyła kolejnych sobie podobnych.', 'Odkrywca Jaren z Wybrzeża Chłodnego Jeziora poprosił cię o zniszczenie 3 Kryształów Plagi.', '', 'Wróć do Odkrywcy Jarena na Wybrzeżu Chłodnego Jeziora w Wyjącym Fiordzie.', 'Zniszczone Kryształy Plagi', '', '', '', 0),
(11397, 'plPL', 'A myślisz, że to murloki śmierdzą!', 'Przybyłam tu, żeby sprawdzić pogłoski o obecności Plagi w pobliżu. Spodziewałam się murloków na wybrzeżu w dole, ale nigdy nie sądziłam, że zobaczę coś takiego!$B$BTam na dole jest Plaga i zamienia murloki, i wszystko, co jej wpadnie w łapy, w chodzące trupy!$B$B$N, nie pozwolimy im tworzyć kolejnych sobie podobnych, a już zwłaszcza z murloków! Tuż na północny zachód od obozu jest zejście na plażę. Dopilnuj, żeby szybko rozprawić się z Plagą!', 'Aptekarka Anastasia poprosiła cię o zniszczenie 15 dowolnych sług Plagi na Wybrzeżu Chłodnego Jeziora. Potem wróć do niej do Obozu Aptekarzy.', '', 'Wróć do Aptekarki Anastasii w Obozie Aptekarzy w Wyjącym Fiordzie.', 'Zabici słudzy Plagi z Wybrzeża Chłodnego Jeziora', '', '', '', 0),
(11398, 'plPL', 'To urządzenie Plagi', 'Stwór Plagi, którego właśnie $gzniszczyłeś:zniszczyłaś;, ściskał w szponach to urządzenie. Osadzono w nim klejnot podobny do tego, który wieńczy kryształy Plagi.$B$BAptekarka Anastasia na pewno chciałaby mu się przyjrzeć.', 'Dostarcz Urządzenie Plagi Aptekarce Anastasii w Obozie Aptekarzy.', '', 'Wróć do Aptekarki Anastasii w Obozie Aptekarzy w Wyjącym Fiordzie.', '', '', '', '', 0),
(11399, 'plPL', 'Zbij te tarcze', 'Spójrz na przycisk z boku sterownika. Założę się, że jeśli podejdziesz dość blisko do któregoś z kryształów Plagi, zdołasz tym sterownikiem zbić jego tarczę. Wtedy wystarczy zniszczyć to coś, zanim tarcza wróci.$B$BStarczy ci odwagi, żeby jeszcze raz zejść na dół, $N? Gwarantuję ci porządną nagrodę, jeśli zbijesz te tarcze i zniszczysz kryształy.$B$BJak możesz odmówić, skoro oznacza to mniej Plagi, zwłaszcza tej zrobionej z murloków?', 'Aptekarka Anastasia z Obozu Aptekarzy poprosiła cię o zniszczenie 3 Kryształów Plagi.', '', 'Wróć do Aptekarki Anastasii w Obozie Aptekarzy w Wyjącym Fiordzie.', 'Zniszczone Kryształy Plagi', '', '', '', 0),
(11406, 'plPL', 'Wszystko musi być gotowe', 'Kiedy siły ekspedycyjne ruszą na północ, kapitan Adams oczekuje, że w Forcie Wildervar wszystko będzie gotowe. Tamtejsi zwiadowcy i rzemieślnicy mają przygotować ekwipunek i racje dla naszych ludzi na wspinaczkę w góry.$B$BKapitan słynie ze swojego temperamentu, więc chcę wysłać kogoś przodem, żeby sprawdził przygotowania. Fort Wildervar leży daleko na północnym wschodzie, za Skorn, w zaśnieżonych okolicach przy granicy ze Wzgórzami Grizli. Znajdź tam Gila Griserta i upewnij się, że jest gotowy.', 'Porozmawiaj z Gilem Grisertem w Forcie Wildervar.', '', '', '', '', '', '', 0),
(11410, 'plPL', 'Ta, co się urwała', 'Kolczaste ryby, które $gprzyniosłeś:przyniosłaś;, powinny się dobrze sprawdzić jako przynęta na większość ryb, ale boję się, że zwabią potwora!$B$BKiedy tu przybyłem, nabiłem na haczyk trochę ulubionej przynęty Nata Pagle\'a i zarzuciłem ją do wody. Uczepił się jej ogromny potwór, z wielkimi zębiskami i soplami zwisającymi z płetw!$B$BWciągnąłby mnie do tej lodowatej wody, gdybym nie przeciął żyłki! Nie mogę użyć nowej przynęty, dopóki ktoś nie rozprawi się ze starą Mroźną Płetwą. Użyj tej przynęty przy zatopionej łodzi na środku jeziora. Nie zdoła się oprzeć!', 'Christopher Sloan z Fortu Wildervar chce, żebyś $gpokonał:pokonała; Mroźną Płetwę.', '', 'Wróć do Christophera Sloana w Forcie Wildervar w Wyjącym Fiordzie.', '', '', '', '', 0),
(11411, 'plPL', 'Obóz Zimowego Kopyta', 'W moich podróżach jako goniec spotkałem wielu dziwnych mieszkańców Wyjącego Fiordu, ale jedna grupa się wyróżnia. Z daleka wyglądają jak taureni, ale z bliska są zupełnie inni: krzepcy i bardziej kudłaci.$B$BJedną z ich osad znalazłem daleko na północy, za Halgrind, Skorn i północnymi lasami. Nazywa się Obóz Zimowego Kopyta i leży u podnóża Gjalerhorn, przy granicy ze Wzgórzami Grizli. Nawiąż z nimi kontakt i sprawdź, czy mogą się nam przydać.', 'Porozmawiaj z Wodzem Popielnym Totemem w Obozie Zimowego Kopyta.', '', '', '', '', '', '', 0),
(11414, 'plPL', 'Bracia zdrajcy', 'Wartowniczka Księżycowy Liść jest z moich snów! Jeśli jesteś jej $gprzyjacielem:przyjaciółką;, jesteś i moim.$B$BByłem samcem alfa do ostatniej pełni. Wtedy z północy przyszedł dziwny biały worg, Garwal, i z pomocą moich dawnych braci szybko został worgiem alfa. Jest w nim coś nienaturalnego.$B$BŻeby pomóc, musisz najpierw zabić tych, którzy mnie zdradzili.$B$BBjomolf poluje na północny zachód od miejsca zwanego Stalową Bramą. A Varga szukaj na południowym wschodzie, przy Wieży Zachodniej Włóczni.$B$BTwoja postać ich nie zwiedzie.', 'Ulfang poprosił cię o zabicie zdradzieckich worgów, Bjomolfa i Varga. Potem wróć do niego w przebraniu do Rozdartego Lasu.$B$BJeśli jakimś cudem zgubisz Przebranie worga, wróć po nowe do Wartowniczki Księżycowy Liść.', '', 'Wróć do Ulfanga w Rozdartym Lesie w Wyjącym Fiordzie. Musisz mieć na sobie przebranie worga.', '', '', '', '', 0),
(11415, 'plPL', 'Bracia zdrajcy', 'Mglisty Krok jest z moich snów! Jeśli jesteś jego $gprzyjacielem:przyjaciółką;, jesteś i moim.$B$BByłem samcem alfa do ostatniej pełni. Wtedy z północy przyszedł dziwny biały worg, Garwal, i z pomocą moich dawnych braci szybko został alfą. Jest w nim coś nienaturalnego.$B$BŻeby pomóc, musisz najpierw zabić tych, którzy mnie zdradzili.$B$BBjomolf poluje na północny zachód od miejsca, które dwunogi nazywają Stalową Bramą. A Varga szukaj na południowym wschodzie, przy Wieży Zachodniej Włóczni.$B$BTwoja postać ich nie zwiedzie.', 'Ulfang poprosił cię o zabicie zdradzieckich worgów, Bjomolfa i Varga. Potem wróć do niego w przebraniu do Rozdartego Lasu.$B$BJeśli jakimś cudem zgubisz Przebranie worga, wróć po nowe do Mędrca Mglisty Krok.', '', 'Wróć do Ulfanga w Rozdartym Lesie w Wyjącym Fiordzie. Musisz mieć na sobie przebranie worga.', '', '', '', '', 0),
(11416, 'plPL', 'Oczy orła', 'Garwal kryje się za nienaturalną magią. Nikt go nie zobaczy, jeśli on sam tego nie zechce. Może jednak mamy jedną szansę.$B$BMój wróg, wielki orzeł Szponodzierzba, podobno ma oczy, które widzą wszystko. Z jej oczami na pewno zobaczysz Garwala.$B$BSzponodzierzba ma gniazdo u stóp wodospadu, tuż na południowy zachód od miejsca wrykuli zwanego Skorn. Jeśli dotkniesz jaj w jej gnieździe, spadnie z nieba, żeby cię zabić.$B$BZdobądź jej oczy.', 'Ulfang poprosił cię o zdobycie Oczu orła. Potem wróć do niego w przebraniu do Rozdartego Lasu.$B$BJeśli jakimś cudem zgubisz Przebranie worga, wróć po nowe do Wartowniczki Księżycowy Liść.', '', 'Wróć do Ulfanga w Rozdartym Lesie w Wyjącym Fiordzie. Musisz mieć na sobie przebranie worga.', '', '', '', '', 0),
(11417, 'plPL', 'Oczy orła', 'Garwal kryje się za nienaturalną magią. Nikt go nie zobaczy, jeśli on sam tego nie zechce. Może jednak mamy jedną szansę.$B$BMój wróg, wielki orzeł Szponodzierzba, podobno ma oczy, które widzą wszystko. Z jej oczami na pewno zobaczysz Garwala.$B$BSzponodzierzba ma gniazdo u stóp wodospadu, tuż na południowy zachód od miejsca wrykuli zwanego Skorn. Jeśli dotkniesz jaj w jej gnieździe, spadnie z nieba, żeby cię zabić.$B$BZdobądź jej oczy.', 'Ulfang poprosił cię o zdobycie Oczu orła. Potem wróć do niego w przebraniu do Rozdartego Lasu.$B$BJeśli jakimś cudem zgubisz Przebranie worga, wróć po nowe do Mędrca Mglisty Krok.', '', 'Wróć do Ulfanga w Rozdartym Lesie w Wyjącym Fiordzie. Musisz mieć na sobie przebranie worga.', '', '', '', '', 0),
(11418, 'plPL', 'Nazywamy go Stalowe Pióro', 'Widujemy dzielnego hipogryfa, który krąży nad fortem, a potem pikuje i porywa zdobycz. Jethan kilka razy do niego strzelał, ale strzały po prostu się od niego odbiły!$B$BZaczęliśmy nazywać to niezwykłe stworzenie Stalowym Piórem, ale nie rozumiemy, czemu tak upodobał sobie okolice Fortu Wildervar. Większość hipogryfów unika ludzi.$B$BBadacz Aderan pomógł nam zrobić amulet z jednego z piór tego stworzenia. Twierdzi, że pozwoli on patrzeć oczami Stalowego Pióra.', 'Odszukaj Stalowe Pióro krążące nad Fortem Wildervar i użyj Pierzastego amuletu, żeby poznać jego sekret. Przekaż, czego się dowiesz, Gilowi Grisertowi.', '', 'Wróć do Gila Griserta w Forcie Wildervar w Wyjącym Fiordzie.', 'Poznaj sekret Stalowego Pióra', '', '', '', 0),
(11420, 'plPL', 'Droga do odwetu', 'Dwa tygodnie temu nasz główny inżynier dorwał wrykulską wyrzutnię harpunów, taką samą, jakiej wrykule używają do zatapiania naszych statków. Badając ją, zdołał opracować pełną instrukcję obsługi.$B$BNiestety porwano go i zabrano na północ stąd, do Wioski Czaszki Żmija. W końcu go znaleźliśmy, ale był bliski śmierci i nie miał instrukcji. Umierając, zdołał powiedzieć, że instrukcja przepadła w Katakumbach Utgard, na północno-zachodnim krańcu Czaszki Żmija. Zdobądź mi tę instrukcję!', 'Kapitan straży Zorek z Valgardu w Wyjącym Fiordzie chce, żebyś $godzyskał:odzyskała; Instrukcję obsługi harpuna.', '', 'Wróć do Kapitana straży Zorka w Valgardzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11421, 'plPL', 'Podkręcone na 11...', 'Musimy uderzyć, póki siły wrykuli są w rozsypce! Zabierz mechanizm sterujący harpunem do Nifflevar i znajdź najdalej na północ wysunięty budynek z harpunami po stronie urwiska.$B$BNa miejscu przejmij jedną z wrykulskich wyrzutni harpunów ustawionych na pomoście budynku. Użyj jej, żeby zgotować piekło Wiosce Czaszki Żmija! Zniszcz długi dom, dom przy przystani, magazyn i wszystkich obrońców, których wrykule na ciebie poślą!$B$BZrób to, a Zatoka Sztyletu stanie się dużo bezpieczniejszym portem!', 'Porucznik Lodowy Młot w Wyjącym Fiordzie chce, żebyś $gzniszczył:zniszczyła; Długi dom Smokołupców, Dom przy przystani Smokołupców, Magazyn Smokołupców i 8 Obrońców Smokołupców.$B$BPo wykonaniu zadania zwróć mu Mechanizm sterujący harpunem.', '', 'Wróć do Porucznika Lodowego Młota w Wyjącym Fiordzie.', '', 'Zniszczony Długi dom Smokołupców', 'Zniszczony Dom przy przystani Smokołupców', 'Zniszczony Magazyn Smokołupców', 0),
(11422, 'plPL', 'Trójząb syna', '<Z rys, które wydrapuje na skale, odczytujesz kilka symboli: trójząb, mur\'ghula, słońce, wrak statku i nieporadny patyczakowy ludzik, który chyba przedstawia ciebie.>$B$B<Rozszyfrowanie, co murlok chce ci przekazać, zajmuje trochę czasu. Oczywiście chodzi mu o to, żebyś $gprzyniósł:przyniosła; trójząb z Wybrzeża Chłodnego Jeziora, ale obrazek słońca cię zastanawia. Dopiero po chwili rozumiesz, że ten mały okrągły kształt to nie słońce, tylko jego syn.>$B$B<Jego syn został przemieniony w mur\'ghula! Chce, żebyś $godnalazł:odnalazła; go na południu, przy wraku statku, i $gwrócił:wróciła; z jego trójzębem.>', 'Stara Lodowa Płetwa chce, żebyś $gzdobył:zdobyła; Trójząb Zgniłoskrzela. Zanieś mu go na małą wyspę przy Wybrzeżu Chłodnego Jeziora.', '', 'Wróć do Starej Lodowej Płetwy na Wybrzeżu Chłodnego Jeziora w Wyjącym Fiordzie.', '', '', '', '', 0),
(11423, 'plPL', 'Dziedzictwo wroga', 'Gdy nasze armie maszerują przez Północną Grań, wrogów nie spotka zwykła porażka. Ich domy spłoną, ich trupy pożrą nasze zarazy, zatrze się wszelki ślad ich istnienia.$B$BJako poszukiwacza wiedzy martwi mnie to. Wschodnie miasto Nifflevar zostanie wkrótce zrównane z ziemią przez nasze siły z Przystani Zemsty. Mieszkał tam wrykulski bard Helgus, który napisał trzy sagi: Sagę o bliźniętach, Sagę o zimowej klątwie i Sagę o val\'kyriach. Zdobądź je, zanim Nifflevar zostanie zniszczone.', 'Udaj się do Nifflevar, na północ od Posterunku Widmowego Ostrza, i odszukaj Sagę o zimowej klątwie, Sagę o val\'kyriach i Sagę o bliźniętach.', '', 'Wróć do Skryby Seguine\'a w Posterunku Widmowego Ostrza w Wyjącym Fiordzie.', '', '', '', '', 0),
(11424, 'plPL', 'Wzgórze Tarczy', 'W czasie wojny moja robota powinna być dziecinnie prosta. Wszędzie powinno być pełno nadających się do czegoś części ciał.$B$BAle to nie takie proste. Te jajogłowe tworzą najróżniejsze zabójcze zarazy i posyłają je do wrogich miast, więc większość materiału jest skażona.$B$BJest jednak miejsce, gdzie da się znaleźć przydatne próbki. Wzgórze Tarczy, na południe stąd, to pradawne wrykulskie cmentarzysko, gdzie umarli chodzą, ale nie trawi ich żadna zaraza, ani nasza, ani Króla Lisza. Przynieś mi trochę kości, dobrze ci zapłacę.', 'Jenny „Piła” chce, żebyś $gprzyniósł:przyniosła; jej 5 Pradawnych kości wrykula z ożywionych wrykuli na Wzgórzu Tarczy, na południe od Nowego Agamandu.', '', 'Wróć do Jenny „Piła” w Nowym Agamandzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11426, 'plPL', 'Odnalezienie mechanizmu', 'Nie martw się, $N, to wszystko doprowadzi do czegoś wielkiego! OGROMNEGO! Na razie musisz mi po prostu zaufać i robić, o co proszę.$B$BDo następnego etapu planu potrzebny nam mechanizm opisany w instrukcji. Mocno podejrzewam, że znajdziesz go przy którymś z wrykuli obsługujących wyrzutnie harpunów w Wiosce Czaszki Żmija. Znajdziesz ich we wschodniej części wioski, na pomostach przy długich domach.', 'Kapitan straży Zorek z Valgardu w Wyjącym Fiordzie chce, żebyś $gprzyniósł:przyniosła; mu Mechanizm sterujący harpunem.', '', 'Wróć do Kapitana straży Zorka w Valgardzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11427, 'plPL', 'Spotkaj się z Porucznikiem Lodowym Młotem...', 'Widzisz te wrykulskie budynki na urwiskach na północnym wschodzie? Wrykule nazywają to miejsce Nifflevar. Stamtąd wychodzi większość ich ataków harpunami na nasze fregaty.$B$BI wiesz co? Nadszedł czas odwetu, $N. Weź ten mechanizm sterujący harpunem i spotkaj się z Porucznikiem Lodowym Młotem, który ukrywa się w wrykulskim budynku na północny zachód od Nifflevar.$B$BGdy będziesz $ggotów:gotowa;, posadzę cię na grzbiecie jednego z naszych gryfów i w mig cię do niego przerzucę!$B', 'Kapitan straży Zorek chce, żebyś $gzaniósł:zaniosła; Mechanizm sterujący harpunem Porucznikowi Lodowemu Młotowi, który stacjonuje pod Nifflevar.', '', 'Wróć do Porucznika Lodowego Młota na Wyspie Cauldros w Wyjącym Fiordzie.', '', '', '', '', 0),
(11428, 'plPL', 'Opiekun Zwiędły Liść', '$GByłeś dla nas wielkim przyjacielem i sojusznikiem:Byłaś dla nas wielką przyjaciółką i sojuszniczką;, $N. Muszę cię prosić jeszcze o jedno.$B$B$GWidziałeś:Widziałaś; zepsucie Pokręconej Polany i bestie, które tam żyją. Opiekunowie o czarnych duszach będą dalej wywoływać te plugastwa z wód i ziemi naszej polany, jeśli nie wystąpimy przeciw nim.$B$BNajpotężniejszy z opiekunów o czarnych duszach to Opiekun Zwiędły Liść. Zabij go, $N, i otwórz drogę do odkupienia polany, tak jak niegdyś $godkupiłeś:odkupiłaś; moje siostry.', 'Lurielle z Zamarzniętej Polany chce, żebyś $gzabił:zabiła; Opiekuna Zwiędłego Liścia.', '', 'Wróć do Lurielle na Zamarzniętej Polanie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11429, 'plPL', 'Wbij i daj czadu!', 'Nie zamierzam oddawać losów tej misji w ręce jakiegoś niesprawdzonego żółtodzioba.$B$BJeśli chcesz mi udowodnić, że masz to, czego trzeba, żeby wykonać tę misję, zrobisz, co ci każę.$B$BWeź ten sztandar bojowy i ruszaj do Baleheimu, prosto na północ stąd. W Baleheimie znajdź środek miasta i wbij tam naszą flagę. Odeprzyj wszystkie wrykulskie szumowiny, które spróbują zerwać naszą ukochaną flagę, i wróć do mnie, gdy już ustanowisz tam panowanie Przymierza!', 'Porucznik Lodowy Młot w Wyjącym Fiordzie chce, żebyś $gzatknął:zatknęła; Sztandar Przymierza w Baleheimie, a potem $gbronił:broniła; go przed napastnikami.$B$BJeśli przeżyjesz, wróć ze Sztandarem Przymierza do Porucznika Lodowego Młota.', 'Obroniony Sztandar Przymierza', 'Wróć do Porucznika Lodowego Młota w Wyjącym Fiordzie.', 'Zatknięty Sztandar Przymierza', '', '', '', 0),
(11430, 'plPL', 'Mistrz harpuna Yavus', 'Całkiem nieźle ci poszło w Baleheimie, $N. Zanim zaczniesz poklepywać się po plecach, czeka cię robota w Nifflevar.$B$BNamierzyliśmy wrykula odpowiedzialnego za większość ataków harpunami na nasze fregaty. Nazywa się Yavus. Znajdziesz go w głównej budowli z harpunami na urwiskach Nifflevar, na południowy wschód stąd.$B$BWytrop go i stracić za zbrodnie przeciw Przymierzu!$B$BNie przynieś mi wstydu, $N!$B', 'Porucznik Lodowy Młot w Wyjącym Fiordzie chce, żebyś $gzabił:zabiła; Mistrza harpuna Yavusa w Nifflevar.', '', 'Wróć do Porucznika Lodowego Młota w Wyjącym Fiordzie.', '', '', '', '', 0),
(11432, 'plPL', 'Śpiące olbrzymy', 'Słyszałem twoją rozmowę z Ojcem Levariolem. Pozwól, że zasugeruję, iż on nie każe ci iść dość daleko.$B$BMusisz się też rozprawić z wrykulami, którzy leżą uśpieni w Salach Przebudzenia pod Gjalerbron!$B$BNie mam wątpliwości, że rytuały ich budzenia są kluczem do ich upadku. Najpewniej nekrowładcy mają jakieś urządzenie, którym można przedwcześnie wybudzić wrykuli z uśpienia.$B$BTakie zakłócenie z pewnością okaże się dla wrykuli zabójcze.', 'Mag-porucznik Malister zlecił ci zabicie 5 Uśpionych wrykuli. Potem wróć do niego do Twierdzy Zachodniej Straży.', '', 'Wróć do maga-porucznika Malistera w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', '', '', '', '', 0),
(11433, 'plPL', 'Śpiące olbrzymy', 'Słyszałem twoją rozmowę ze Wszechmatką Ankhą. Z całym szacunkiem, ona nie każe ci iść dość daleko.$B$BMusisz się też rozprawić z wrykulami, którzy leżą uśpieni w Salach Przebudzenia pod Gjalerbron!$B$BNie mam wątpliwości, że rytuały ich budzenia są kluczem do ich upadku. Najpewniej nekrowładcy mają jakieś urządzenie, którym można przedwcześnie wybudzić wrykuli z uśpienia.$B$BTakie zakłócenie z pewnością okaże się dla wrykuli zabójcze.', 'Ahota Biały Szron zlecił ci zabicie 5 Uśpionych wrykuli. Potem wróć do niego do Obozu Zimowego Kopyta.', '', 'Wróć do Ahoty Białego Szronu w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', '', '', '', '', 0),
(11434, 'plPL', 'Zapomniany skarb', 'Dorobiłem się fortuny na skarbach, których zwykli piraci nie doceniają: sztuce, starożytnościach, przedmiotach kolekcjonerskich.$B$BFlota Czarnego Conrada zatonęła na południe stąd przed laty. Nurkowie wyzbierali całe złoto i biżuterię, ale zostały tam dwa pradawne relikty. Jeden to waza Amanów godna muzeum, drugi to figurka orła.$B$BWyłow je dla mnie, a poręczę za ciebie przed innymi piratami. Dorzucę nawet coś, co ułatwi ci podwodną przygodę.', 'Przystojny Terry z Cypla Łajdaków chce, żebyś $gprzyniósł:przyniosła; mu z wraku na południu 1 Wazę Amanów i 1 Figurkę orła.', '', 'Wróć do Przystojnego Terry\'ego na Cyplu Łajdaków w Wyjącym Fiordzie.', '', '', '', '', 0),
(11436, 'plPL', 'Idziemy surfować!', 'Poruszanie się po stromych urwiskach Wyjącego Fiordu potrafi zszargać nerwy! Wymyśliłem, jak sobie ulżyć, łącząc wrykulską technikę z krasnoludzką pomysłowością. Kilka przeróbek, trochę dostrajania i oto Sterownik harpuna Lodowego Młota! Oczywiście nikt go jeszcze nie testował, ale od tego właśnie jesteś ty!$B$BZanieś sterownik do wielkiej wyrzutni w Nifflevar i użyj go, żeby wystrzelić się prosto do Valgardu. Zamelduj Zorekowi o zwycięstwie. A, i sterownik możesz zatrzymać.', 'Użyj dużej Wrykulskiej wyrzutni harpunów w Nifflevar, żeby wystrzelić się do Valgardu. Zamelduj Kapitanowi straży Zorekowi o zwycięstwie nad wrykulami.', 'Posurfuj na harpunie', 'Wróć do Kapitana straży Zorka w Valgardzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11443, 'plPL', 'Nurkowanie w Zatoce Sztyletu', 'Hej... eee... co słychać? Co ty tu robisz na dole?$B$BJa? Aa... No bo widzisz... ja... eee... sprzątam tu! Rozkaz samego Kellera! Mówi do mnie: „Harry, załóż dzwon nurkowy i przeszukaj wraki w Zatoce Sztyletu w poszukiwaniu NASZYCH rzeczy...”$B$BSłuchaj, może pomożesz mi, skoro już tu jesteś. W całej zatoce pełno jest różnych smakołyków, eee, to znaczy zapasów. Idź i przynieś mi wszystko, co znajdziesz. Załóż ten hełm nurka, żeby ci nie zabrakło powietrza i żebyś nie $gumarł:umarła;.', 'Harold Lagras z dna Zatoki Sztyletu chce, żebyś $godzyskał:odzyskała; 10 Skrzyń z zapasami Valgardu.', '', 'Wróć do Harolda Lagrasa w Zatoce Sztyletu w Wyjącym Fiordzie.', '', '', '', '', 0),
(11448, 'plPL', 'Posterunek Ligi Odkrywców', 'Jakiś zaszyfrowany bełkot! Nawet z tym szyfrem nie mogę się połapać w tych tablicach. Przyznaję, kryptografia to nie moja mocna strona.$B$BMusisz zanieść szyfr i tablice naszemu kryptografowi, Stanwadowi. Niestety od dwóch tygodni nie mam od niego wieści. Zabrał zespół dwudziestu uczonych na wykopaliska na południowo-wschodnich urwiskach fiordu i od tamtej pory słuch o nim zaginął. Najwięcej, co mogę zrobić, to poprosić McGoyvera, żeby cię tam podrzucił swoją fruwającą maszyną.', 'Dostarcz Tobołek McSorfa Stanwadowi w Posterunku Ligi Odkrywców w Wyjącym Fiordzie.', '', 'Wróć do Stanwada w Wyjącym Fiordzie.', '', '', '', '', 0),
(11452, 'plPL', 'Uśpiony król', 'Z nieruchomej dłoni zwierzchnika wypada plik pergaminów. Rozpoznajesz na nich zarys rytuałów odprawianych w katakumbach w dole.$B$BWygląda jednak na to, że królowa wrykuli, Angerboda, ma kłopot z przebudzeniem Króla Ymirona. Rytuał odbywa się w wielkiej komnacie zwanej Tarasem Zimy, na północnym krańcu Gjalerbron.$B$BJeśli się pospieszysz, może zdołasz ją powstrzymać, zanim będzie za późno.', 'Pokonaj Królową Angerbodę i przerwij rytuał przebudzenia Króla Ymirona. Jeśli ci się uda, wróć do Twierdzy Zachodniej Straży i zamelduj o sukcesie Kapitanowi Adamsowi.', '', 'Wróć do kapitana Adamsa w Twierdzy Zachodniej Straży w Wyjącym Fiordzie.', '', '', '', '', 0),
(11453, 'plPL', 'Uśpiony król', 'Z nieruchomej dłoni zwierzchnika wypada plik pergaminów. Rozpoznajesz na nich zarys rytuałów odprawianych w katakumbach w dole.$B$BWygląda jednak na to, że królowa wrykuli, Angerboda, ma kłopot z przebudzeniem Króla Ymirona. Rytuał odbywa się w wielkiej komnacie zwanej Tarasem Zimy, na północnym krańcu Gjalerbron.$B$BJeśli się pospieszysz, może zdołasz ją powstrzymać, zanim będzie za późno.', 'Pokonaj Królową Angerbodę i przerwij rytuał przebudzenia Króla Ymirona. Jeśli ci się uda, wróć do Obozu Zimowego Kopyta i zamelduj o sukcesie Wodzowi Popielnemu Totemowi.', '', 'Wróć do wodza Popielnego Totema w Obozie Zimowego Kopyta w Wyjącym Fiordzie.', '', '', '', '', 0),
(11455, 'plPL', 'Zapach pieniędzy', 'My, piraci, słyniemy z wielu rzeczy, ale higiena do nich nie należy. Na większości pirackich statków jest pięć, sześć razy więcej szczurów niż ludzi.$B$BNic dziwnego, że wszystkie niedźwiedzie na tej wyspie złapały wściekliznę zaraz po tym, jak się tu wprowadziliśmy. Krótko mówiąc, szef chce je wszystkie martwe.$B$BTak się składa, że znam przepis na perfumy z piżma niedźwiedzia, modne wśród szlachty z Wichrogrodu. Zabijemy niedźwiedzie i sprzedamy piżmo. Widzę tu dla nas świetny interes. Co ty na to?', 'Przystojny Terry z Cypla Łajdaków w Wyjącym Fiordzie chce, żebyś $gzdobył:zdobyła; 4 porcje Piżma niedźwiedzia od Wściekłych niedźwiedzi brunatnych z okolicy.', '', 'Wróć do Przystojnego Terry\'ego na Cyplu Łajdaków w Wyjącym Fiordzie.', '', '', '', '', 0),
(11456, 'plPL', 'Żywność dla ocalałych', 'My, kiełzarowie, żywimy się głównie złowionymi rybami. W czasach wielkiej potrzeby polujemy jednak czasem na zwierzęta lądowe.$B$BPobliską wioskę Iskaal niedawno napadli piraci, a ocalali wciąż do nas napływają.$B$BW tym tygodniu połów był skromny, ale na wyspie żyje wiele łopatokłów, a mięsa mają pod dostatkiem.$B$BPomóż mojemu ludowi, polując na te wielkie zwierzęta i zdobywając ich mięso.', 'Starszy Atuik z Kamagua w Wyjącym Fiordzie chce, żebyś $gzdobył:zdobyła; 6 porcji Mięsa wyspowego łopatokła od Wyspowych łopatokłów na Wyspie Włóczni.', '', 'Wróć do Starszego Atuika w Kamagua w Wyjącym Fiordzie.', '', '', '', '', 0),
(11457, 'plPL', 'Uzbrojenie Kamagua', 'Mój lud przedstawia Issliruka, ducha wojny, jako srebrnego orła. Nasze opowieści mówią, jak Issliruk walczył ze stu worgami, by ocalić swoje młode.$B$BNa nas też przyszła pora, by walczyć z wrogami i ocalić naszych braci. Będziemy potrzebować nowej broni. Rogi mroźnoskrzydłych chimer, które żyją w zaśnieżonych częściach wyspy, są ostre i łatwo zrobić z nich groty włóczni. Przynieś mi najlepsze rogi, jakie znajdziesz.', 'Starszy Atuik chce, żebyś $gzdobył:zdobyła; 3 Rogi chimery.', '', 'Wróć do Starszego Atuika w Kamagua w Wyjącym Fiordzie.', '', '', '', '', 0),
(11458, 'plPL', 'Pomścij Iskaal', 'Totem Issliruka jest gotowy, $N, i dziękuję ci za to. Musimy na razie porzucić nasze pokojowe obyczaje i uderzyć na tych, którzy zaatakowali naszą ziemię i naszych krewnych.$B$BPiraccy handlarze niewolników, którzy napadli na Iskaal, postradali zmysły i wyrżnęli wszystkich jeńców. Idź do Iskaal, na wschód stąd, i zrób, co trzeba. Weź ten róg i wezwij moich braci, jeśli będziesz potrzebować pomocy.', 'Starszy Atuik chce, żebyś $gposzedł:poszła; do Iskaal i $gzabił:zabiła; 8 Handlarzy niewolników z Morza Północnego. Jeśli będziesz potrzebować pomocy, użyj Rogu Kamagua.', '', 'Wróć do Starszego Atuika w Kamagua w Wyjącym Fiordzie.', '', '', '', '', 0),
(11459, 'plPL', 'Zeh\'gehn gada', 'Tak to je, mon. Ty chcieć, coby moja pomóc wyniuchać jakiego tchórzliwego kapusia, co kantuje załogę?$B$BMusisz mi przytargać rechotka, kamracie. Potem ja i ja pokazać tobie, kto ta łajza, mon. Nie, nie, rechotek pokazać. Zobaczysz na własne ślepia, tuta.$B$BPrzytargaj nam też kozika, tuta, raz-dwa. Zmykaj, bratku.', 'Wróć do Przystojnego Terry\'ego, żeby rozszyfrował, o co prosił cię Zeh\'gehn.', '', '', '', '', '', '', 0),
(11460, 'plPL', 'Zaufanie trzeba zdobyć', 'Pierwszą i najważniejszą rzeczą w sokolnictwie jest więź między $gsokolnikiem:sokolniczką; a ptakiem. Pan musi zdobyć zaufanie!$B$B<Hidalgo wskazuje sokoły w klatce u swoich stóp.>$B$BJeśli masz zdobyć ich zaufanie, najpierw musisz napełnić im brzuchy.$B$BFiordowe skalne sokoły, bo tak się te ptaki nazywa, jedzą głównie czerwie. W całym fiordzie znajdziesz luźne kamienie, pod którymi te czerwie się lęgną. Znajdź czerwia i wróć tu nakarmić sokoły w klatce.', 'Hidalgo z Posterunku Ligi Odkrywców w Wyjącym Fiordzie chce, żebyś $gznalazł:znalazła; Czerwia fiordowego i $gnakarmił:nakarmiła; nim jednego z sokołów w klatce u jego stóp.', 'Nakarmiony fiordowy skalny sokół', 'Wróć do Hidalga, mistrza sokolnictwa, w Posterunku Ligi Odkrywców w Wyjącym Fiordzie.', '', '', '', '', 0),
(11462, 'plPL', 'Przystojny Terry', 'Twoi ludzie dobrze mi zapłacili, żebym przeniknął do Korsarzy z Morza Północnego i wprowadził cię w ich szeregi.$B$BNagadałem o tobie facetowi na Cyplu Łajdaków, który nazywa się Przystojny Terry. Powiedziałem mu, że masz świetne rekomendacje.$B$BZałóż przebranie i idź się z nim zobaczyć. O, właśnie ktoś idzie, żeby cię tam zaprowadzić.$B$BZanim przedstawią cię swoim szefom, będziesz $gmusiał:musiała; się trochę wykazać. Ale to już zależy od ciebie. Pamiętaj, $N, gdy już będziesz w środku, $gzdany:zdana; będziesz tylko na siebie!', 'Załóż Przebranie pirata i porozmawiaj z Przystojnym Terrym na Cyplu Łajdaków.', '', '', '', '', '', '', 0),
(11463, 'plPL', 'Piraci z Mórz Północnych', 'W ostatnich tygodniach nasiliły się ataki piratów na nasze statki z zaopatrzeniem. Wynajęliśmy goblińskiego szpiega, żeby utorował drogę jednemu z naszych agentów, który przeniknie do podejrzanych piratów.$B$BTa banda Korsarzy z Morza Północnego działa z Cypla Łajdaków na Rafie Garvana. Niewiele o nich wiemy, ale wiemy, że Sylwana chce głowy ich przywódcy.$B$BMasz bardzo dobre rekomendacje, $N. Jeśli podejmiesz się tego zadania, nasze wojsko będzie mogło skupić się na siłach Arthasa. Dasz radę?', 'Odszukaj Grezzixa Spindlesnapa na północnym krańcu Rafy Garvana, u południowo-zachodnich wybrzeży Wyjącego Fiordu.', '', '', '', '', '', '', 0),
(11464, 'plPL', 'Dług karciany', 'Słyszałem, że $gpopracowałeś:popracowałaś; trochę dla Terry\'ego. Liczyłem, że w tych stronach pojawi się ktoś solidny.$B$BWidzisz, piraci uwielbiają hazard. Za to nie uwielbiają spłacać długów karcianych.$B$BJeśli chcesz ściągnąć trochę grosza w moim imieniu, chętnie dam ci działkę.$B$BZacznijmy od czegoś łatwego. Harry „Srebrna Luna” to trochę dziwak, trzyma w namiocie mnóstwo drogich krwawoelfich bibelotów, a kiedy go spotykam, zawsze udaje, że jest spłukany. Odbierz moje złoto.', 'Taruk z Cypla Łajdaków chce, żebyś $gściągnął:ściągnęła; Dług Harry\'ego „Srebrna Luna”.', '', 'Wróć do Taruka na Cyplu Łajdaków w Wyjącym Fiordzie.', '', '', '', '', 0),
(11465, 'plPL', 'Splądrowana karawana', 'Prowadziłem tu karawanę z Valgardu, którą napadli Smokołupcy. Jako jedyny przeżyłem tę zasadzkę. Niestety nie zdołałem dowieźć tu ładunku fiordowych indyków. To idealna okazja, żebyś $gzaczął:zaczęła; stawiać pierwsze kroki ze swoim skalnym sokołem.$B$B<Hidalgo podaje ci klatkę.>$B$BWeź tę klatkę z sokołem i idź na zachód drogą wychodzącą z obozu. Użyj sokoła, żeby łapać zbiegłe indyki, i wróć tu, gdy zbierzesz ich dość.$B$BPamiętaj, żeby karmić sokoła!', 'Hidalgo z Posterunku Ligi Odkrywców w Wyjącym Fiordzie chce, żebyś za pomocą Wytresowanego skalnego sokoła $godzyskał:odzyskała; 5 Indyków fiordowych.$B$BPo wykonaniu zadania wróć z klatką do Hidalga.', '', 'Wróć do Hidalga, mistrza sokolnictwa, w Posterunku Ligi Odkrywców w Wyjącym Fiordzie.', '', '', '', '', 0),
(11466, 'plPL', 'Jack lubi wypić', 'Nasz następny klient, Jack Adams, nie da się tak łatwo załatwić jak Harry. Cały dzień pije z kumplami, a każdy z nich to twardy pirat. Tym razem nie używajmy siły, mogłoby się zrobić paskudnie.$B$BSpróbuj obrócić jego pijaństwo na swoją korzyść. Każdy może wypić tylko tyle, zanim straci przytomność.$B$BMoże pomoże ci któraś z dziewek z baru. Kiedy padnie, spróbuj wsunąć mu rękę do kieszeni i zabrać, co moje.', 'Taruk z Cypla Łajdaków w Wyjącym Fiordzie chce, żebyś $gściągnął:ściągnęła; Dług Jacka Adamsa.', '', 'Wróć do Taruka na Cyplu Łajdaków w Wyjącym Fiordzie.', '', '', '', '', 0),
(11467, 'plPL', 'Dług nieboszczyka', 'Może $gsłyszałeś:słyszałaś; o Czarnym Conradzie, to słynny pirat w tych stronach.$B$BOtóż lubił obstawiać moje walki. Lubił też nie płacić.$B$BChętnie bym ściągnął dług, ale kłopot w tym, że... on nie żyje.$B$BJuż miałem spisać to wszystko na straty, kiedy natknąłem się na to...$B$B<Taruk rozkłada mapę Wyspy Włóczni z krzyżykiem na płaskowyżu w północno-wschodniej części.>$B$BUkrył swój skarb na ziemi kiełzarów. Chcę, żebyś go $gzdobył:zdobyła;. Niech mnie diabli, jeśli pozwolę temu zęzowemu szczurowi wymigać się od zapłaty.', 'Taruk z Cypla Łajdaków chce, żebyś $godszukał:odszukała; Skarb Czarnego Conrada na płaskowyżu w północno-wschodniej części Wyspy Włóczni, tuż na północ od Iskaal.', '', 'Wróć do Taruka na Cyplu Łajdaków w Wyjącym Fiordzie.', '', '', '', '', 0),
(11468, 'plPL', 'Sokół kontra jastrząb', 'Czujesz tę bliskość, $N? Na pewno czujesz, jak między tobą a twoim sokołem rodzi się prawdziwa więź. Uwierzysz mi, jeśli powiem, że gdy nadejdzie pora, będziesz $gmógł:mogła; patrzeć oczami swojego ptaka? Tak, to najwyższy stopień sokolnictwa.$B$BAle najpierw musisz więcej polować! Ptak musi wyostrzyć i przyspieszyć swoje odruchy. Poślij go na groźniejszego przeciwnika! Fiordowe jastrzębie z tej okolicy mieszkają w koronach drzew wokół nas. One będą twoim następnym celem!', 'Hidalgo z Posterunku Ligi Odkrywców w Wyjącym Fiordzie chce, żebyś za pomocą Wytresowanego skalnego sokoła $gschwytał:schwytała; 10 Jastrzębi fiordowych.$B$BPo wykonaniu zadania wróć z klatką do Hidalga.$B', '', 'Wróć do Hidalga, mistrza sokolnictwa, w Posterunku Ligi Odkrywców w Wyjącym Fiordzie.', '', '', '', '', 0),
(11469, 'plPL', 'Mydło do szorowania', 'No, muszę wyszorować pokład na błysk, zanim przylezie Szalony Jonah. A na kolanach tego robić nie będę!$B$BKłopot w tym, że skończyło się nam mydło. Ale to bardziej twój kłopot niż mój, kamracie. Skoro jesteś tu $gnowy:nowa;, mam dla ciebie specjalną wycieczkę.$B$BNa północno-zachodnim wybrzeżu tej wyspy jest cała masa lwów morskich. Wśród pobliskiej kry znajdziesz przewodnika stada, Wielkiego Roya. Przynieś mi jego tłuszcz, a wyczaruję najlepsze mydło, jakie w życiu $gwidziałeś:widziałaś;!', 'Scuttle Mroźny Dziób chce, żebyś $gzdobył:zdobyła; Tłuszcz Wielkiego Roya, główny składnik jej magicznego mydła do szorowania. Gdy go zdobędziesz, wróć do niej na wschodni statek piracki na Cyplu Łajdaków.', '', 'Wróć do Scuttle Mroźny Dziób na Cyplu Łajdaków w Wyjącym Fiordzie.', '', '', '', '', 0),
(11470, 'plPL', 'Wśród ptaków nie ma honoru', 'Zdecydowanie jesteś $ggotów:gotowa; na kolejny etap sokolnictwa, $N.$B$BZabierz swojego wytresowanego sokoła na wschód stąd, do grzędy jastrzębi wrykulów przy Windzie Kamiennego Muru. Z grzędy wyślesz sokoła, żeby wykradał jaja jastrzębi. Ich gniazda znajdują się w trudno dostępnych miejscach na skalnych ścianach wokół grzędy. Odszukaj te gniazda i użyj sokoła, żeby wyzbierał jaja!$B$BStrzeż się matron jastrzębi fiordowych, $N. Jeśli cię zaatakują, użyj umiejętności ucieczki i wzlotu swojego sokoła, żeby uciec!', 'Hidalgo z Posterunku Ligi Odkrywców w Wyjącym Fiordzie chce, żebyś za pomocą Wytresowanego skalnego sokoła $gzdobył:zdobyła; 8 Jaj jastrzębia fiordowego.$B$BPo wykonaniu zadania wróć z klatką do Hidalga.', '', 'Wróć do Hidalga, mistrza sokolnictwa, w Posterunku Ligi Odkrywców w Wyjącym Fiordzie.', '', '', '', '', 0),
(11471, 'plPL', 'Koniec zabawy', 'Wiem, po co tu jesteś, $N. Przysłano cię, żebyś $gzabił:zabiła; naszego przywódcę, Jonaha Sterlinga.$B$BChcę ci zaoferować pomoc. Przywództwo Jonaha zagraża naszym interesom.$B$BAtakować jednocześnie floty Hordy i Przymierza? Samobójstwo. Próbować sprzedawać kiełzarów w niewolę, skoro umierają kilka dni po opuszczeniu tego klimatu? Katastrofa.$B$BKryjówka Jonaha jest w jaskini na zachód stąd. Przynieś mi jego lunetę jako dowód, a moim pierwszym rozkazem jako przywódczyni będzie wstrzymanie wszystkich ataków na twoich sojuszników.', 'Annie Bonn z Cypla Łajdaków chce, żebyś $gprzyniósł:przyniosła; jej Lunetę Jonaha Sterlinga.', '', 'Wróć do Annie Bonn na Cyplu Łajdaków w Wyjącym Fiordzie.', '', '', '', '', 0),
(11472, 'plPL', 'Przez żołądek do serca...', 'Piraci z Morza Północnego zarżnęli przewodnika stada lwów morskich z tych wysp, Wielkiego Roya. Zrobili z niego mydło do szorowania pokładów swoich statków!$B$B<Anuniaq wzdycha.>$B$BTeraz lwy morskie nie chcą się parzyć. Pomóż mi odbudować ich liczebność.$B$BRafowe byki znajdziesz na Bliźniaczych Brzegach na południowym wschodzie. Przepadają za smacznymi rybami rafowymi, które żyją po wschodniej i zachodniej stronie wysp.$B$BWeź tę sieć i nałów dość ryb, co najmniej tuzin, a może więcej, żeby zwabić byka przez cieśninę do rafowej krowy.', 'Rzucaj Smaczne ryby rafowe Rafowemu bykowi, żeby zaprowadzić go do Rafowej krowy. Gdy pomożesz tej dwójce odnaleźć prawdziwą miłość, wróć do Anuniaqa w Kamagua.', 'Rafowy byk doprowadzony do Rafowej krowy', 'Wróć do Anuniaqa w Kamagua w Wyjącym Fiordzie.', '', '', '', '', 0),
(11474, 'plPL', 'Kłopoty na Wysokim Urwisku', 'Jak zwykle cała prawdziwa robota spada na mnie i moją ekipę. Na szczęście ludzie McSorfa nie zginęli na darmo. Szyfr, który zdobyli, pomoże nam złamać to, co tu znaleźliśmy... o ile w ogóle uda nam się do tego wrócić! Przeklęte żelazne krasnoludy wyrosły wszędzie jak przecieki w kadłubie i teraz próbują zasypać wykopaliska! Wyobrażasz sobie? Dranie chcą zakopać nasze znaleziska!$B$BW każdym razie pogadaj z Waltem, o tam. On ci powie, od czego zacząć.', 'Porozmawiaj z Waltem.', '', '', '', '', '', '', 0),
(11475, 'plPL', 'Narzędzia do roboty', 'Od wielu dni badam tego unieruchomionego konstrukta, $N. Myślę, że zdołam zbudować całkiem wierną podróbkę tego golema, w której zmieści się jeden pasażer. Chodzi o to, żeby oszukać te żelazne krasnoludy i dostać się do Wykopalisk Baelguna.$B$BTylko że młotkiem i pogrzebaczem nic nie zbuduję. Potrzebuję moich narzędzi! Niestety zostawiłem je w Ruinie Ivalda, kiedy żelazne krasnoludy pierwszy raz zaatakowały. Przynieś mi moje narzędzia!$B$BRuina Ivalda leży daleko na północnym wschodzie.', 'Walt z Posterunku Ligi Odkrywców w Wyjącym Fiordzie chce, żebyś $godzyskał:odzyskała; jego Narzędzia budowlane.', '', 'Wróć do Walta w Posterunku Ligi Odkrywców w Wyjącym Fiordzie.', '', '', '', '', 0),
(11476, 'plPL', 'Kozik i rechotek', 'Niektórzy z tutejszych piratów... mamy swój szczególny sposób mówienia. Zeh\'gehn ma... wiele różnych szczególnych sposobów mówienia... wszystkie wymieszane.$B$BO ile dobrze rozumiem, chce żaby i noża.$B$BHarry „Srebrna Luna” może mieć tani nóż. Żab jest pełno w całym mieście, po prostu złap jedną i zanieś mu ją razem z nożem.$B$BNie chciałbym być na miejscu tego biednego stworzenia, jeśli wiesz, co mam na myśli.', 'Zdobądź Błyszczący nóż od Harry\'ego „Srebrna Luna” i złap Łajdacką żabę. Zanieś je Zeh\'gehnowi na Cyplu Łajdaków.', '', 'Wróć do Zeh\'gehna na Cyplu Łajdaków w Wyjącym Fiordzie.', '', '', '', '', 0),
(11477, 'plPL', 'Nie w moim żywiole?', 'Ciszej. Te żelazne krasnoludy łatwo pociągają za spust. I nie daj się zwieść temu, co się dzieje na dole w wykopie. Te stalowoskóre plugastwa niczego nie odkopują! O nie, wręcz przeciwnie: zakopują wykopalisko! Z jakiegoś pokręconego powodu nie chcą, żeby ktokolwiek znalazł to miejsce.$B$BJaki krasnolud zakopuje pradawne relikty i wykopaliska? Powiem ci jaki: taki, którego się zabija bez litości! Wchodź tam i wykończ ich!', 'Donny z Ruiny Ivalda w Wyjącym Fiordzie chce, żebyś $gzabił:zabiła; 10 Niszczycieli żelaznych run, 5 Wyrobników żelaznych run i 2 Mędrców żelaznych run.', '', 'Wróć do Donny\'ego w Ruinie Ivalda w Wyjącym Fiordzie.', '', '', '', '', 0),
(11478, 'plPL', 'Posterunek tam, o...', 'Widzę, że jeszcze nie $godwiedziłeś:odwiedziłaś; moich braci w Posterunku Ligi Odkrywców na południe stąd. Może zrobisz Donny\'emu przysługę i zaniesiesz tę wiadomość Stanwadowi? Zainteresują go wieści o tym, co tu wyprawiają żelazne krasnoludy.$B$BJak mówiłem, dosiądź wierzchowca i ruszaj na południe. Zobaczysz posterunek tuż przed Wykopaliskami Baelguna.', 'Dostarcz List Donny\'ego Stanwadowi w Posterunku Ligi Odkrywców.', '', 'Wróć do Stanwada w Wyjącym Fiordzie.', '', '', '', '', 0),
(11479, 'plPL', 'Dan „Krucza Noga”', 'Rechotek przemówić, kamracie. Dan „Krucza Noga” być na tamtym statku.$B$BLepiej wytropić tę łajzę, mon. Pokazać mu, że z tą bandą się nie zadziera. Wracać do Terry\'ego, jak mu przetrzepać zadek pod kilem.', 'Rozpraw się z Danem „Krucza Noga”, który jest na jednym ze statków na Cyplu Łajdaków. Potem porozmawiaj z Przystojnym Terrym.', '', 'Wróć do Przystojnego Terry\'ego na Cyplu Łajdaków w Wyjącym Fiordzie.', '', '', '', '', 0),
(11480, 'plPL', 'Spotkanie z Numerem Dwa', 'Twoja dobra robota dla nas nie przeszła niezauważona, $N. Nasza zastępczyni, urocza Annie Bonn, jest pod ogromnym wrażeniem tego, czego do tej pory $gdokonałeś:dokonałaś;, i chce cię poznać.', 'Porozmawiaj z Annie Bonn na Cyplu Łajdaków.', '', '', '', '', '', '', 0),
(11483, 'plPL', 'Możemy to odbudować', 'Narzędzia? Są. Materiały? Brak.$B$BJeśli mamy to zbudować, musisz mi zdobyć materiały.$B$BPo kolei, $N. Na szkielet potrzebuję dużej beczki z Nifflevar, sztabek czarnorytu z Valgardu i liny przemysłowej wytrzymałości z Baleheimu.$B$BNifflevar i Baleheim to wrykulskie osady na północny zachód stąd. Valgard leży w Zatoce Sztyletu, też na północnym zachodzie. Porozmawiaj z McGoyverem, żeby dostać sztabki. Gdy skończysz, przywiezie cię tu z powrotem.', 'Walt z Posterunku Ligi Odkrywców w Wyjącym Fiordzie chce, żebyś $gprzyniósł:przyniosła; mu Dużą beczkę, Linę przemysłowej wytrzymałości i Sztabki czarnorytu.', '', 'Wróć do Walta w Posterunku Ligi Odkrywców w Wyjącym Fiordzie.', '', '', '', '', 0),
(11484, 'plPL', 'Mamy technologię', 'Konstrukcja takiej maszyny jest ważna, ale nie możemy lekceważyć wyglądu konstruktu. Jeśli mamy oszukać żelazne krasnoludy, kopia musi być dokładna!$B$BDam radę to zrobić.$B$BPrzynieś mi nieskazitelną skórę łopatokła z tutejszych łopatokłów i stalowe żebrowanie od wrykuli z Nifflevar albo Baleheimu na północnym zachodzie.', 'Walt z Posterunku Ligi Odkrywców w Wyjącym Fiordzie chce, żebyś $gprzyniósł:przyniosła; mu Nieskazitelną skórę łopatokła i Stalowe żebrowanie.', '', 'Wróć do Walta w Posterunku Ligi Odkrywców w Wyjącym Fiordzie.', '', '', '', '', 0),
(11485, 'plPL', 'Konstrukty żelaznych run i ty: skoki rakietowe', 'No dobrze, $N, pora, żebyś $gwszedł:weszła; do tego czegoś i $gnauczył:nauczyła; się podstawowych umiejętności. Kiedy będziesz $ggotów:gotowa;, wejdź na stół warsztatowy, a ja umieszczę cię w konstrukcie.$B$BPierwsza lekcja to korzystanie z układu przemieszczania konstruktu. Zauważysz, że żelazne krasnoludy rozmieściły wokół wykopaliska specjalne runiczne ryty. Ich konstrukty ładują się przy nich energią i przelatują od punktu do punktu. Wypróbuj to na rycie, który tu zbudowałem.$B', 'Walt z Posterunku Ligi Odkrywców w Wyjącym Fiordzie chce, żebyś $gużył:użyła; umiejętności Skok rakietowy Konstruktu żelaznych run przy Rzeźbie żelaznych run Walta.$B$BPo wykonaniu zadania odwołaj konstrukt w oknie zwierzaka.', 'Opanowany skok rakietowy', 'Wróć do Walta w Posterunku Ligi Odkrywców w Wyjącym Fiordzie.', '', '', '', '', 0),
(11489, 'plPL', 'Konstrukty żelaznych run i ty: zbieranie danych', 'Najważniejszą częścią twojej pracy przy sterowaniu konstruktem jest zbieranie danych. Umieściłem relikt żelaznych krasnoludów w wózku, o tam. To ten unoszący się kryształ nasycony błyskawicami.$B$BWejdź na stół warsztatowy, a znów umieszczę cię w konstrukcie. Gdy znów zasiądziesz za sterami, użyj umiejętności zbierania danych, żeby zebrać dane testowe.', 'Walt z Posterunku Ligi Odkrywców w Wyjącym Fiordzie chce, żebyś $gużył:użyła; umiejętności Zbieranie danych Konstruktu żelaznych run, stojąc przy Relikcie żelaznych krasnoludów.$B$BPo wykonaniu zadania odwołaj konstrukt w oknie zwierzaka.', '', 'Wróć do Walta w Posterunku Ligi Odkrywców w Wyjącym Fiordzie.', 'Zebrane dane testowe', '', '', '', 0),
(11491, 'plPL', 'Konstrukty żelaznych run i ty: blef', 'Zawsze trzeba mieć plan awaryjny na wypadek, gdyby główny plan zawiódł! Dlatego wbudowałem w konstrukt kilka systemów przeciwwywiadowczych.$B$BTwoja błyszcząca nowa bryka może wzbudzić podejrzenia na Wykopaliskach Baelguna. Od tego jest twoja umiejętność blefu! Użyj jej, ilekroć ktoś cię zaczepi, a nic ci się nie stanie.$B$BWypróbuj ją na Lebronskim, chodząc po jego dywanie. Kiedy zacznie sapać i prychać, użyj blefu!$B$BGdy będziesz $ggotów:gotowa; zacząć, wejdź na stół warsztatowy.', 'Walt z Posterunku Ligi Odkrywców w Wyjącym Fiordzie chce, żebyś $gużył:użyła; umiejętności Blef Konstruktu żelaznych run na Lebronskim, gdy już przejdziesz się po jego dywanie.$B$BPo wykonaniu zadania odwołaj konstrukt w oknie zwierzaka.$B', 'Lebronski oszukany', 'Wróć do Walta w Posterunku Ligi Odkrywców w Wyjącym Fiordzie.', '', '', '', '', 0),
(11494, 'plPL', 'Relikty nasycone błyskawicami', 'Twój konstrukt jest gotowy. Przejrzałem wszystkie umiejętności i zaprogramowałem maszynę tak, żeby rozumiała język tytanów i nim mówiła.$B$BZabierz konstrukt na Wykopaliska Baelguna, prosto na południe stąd, i zbierz dane z nasyconych błyskawicami reliktów porozrzucanych po całym terenie. Pamiętaj, żeby blefować przed każdym żelaznym krasnoludem, który podejrzewa, że twój konstrukt to podróbka. I nie zapomnij o skokach rakietowych od runy do runy, żeby się tam przemieszczać!$B$BWejdź na stół, gdy będziesz $ggotów:gotowa;!', 'Walt z Posterunku Ligi Odkrywców w Wyjącym Fiordzie chce, żebyś za pomocą umiejętności Zbieranie danych Konstruktu żelaznych run $gzebrał:zebrała; 15 zestawów Danych żelaznych run.$B$BPo wykonaniu zadania odwołaj konstrukt w oknie zwierzaka.', '', 'Wróć do Walta w Posterunku Ligi Odkrywców w Wyjącym Fiordzie.', 'Zebrane dane żelaznych run', '', '', '', 0),
(11495, 'plPL', 'Delikatny odgłos gromu', 'Jaskinia, którą otworzyliśmy na Wykopaliskach Baelguna, była jedynym miejscem, którego większość unikała... Nie dziwię się im. Z tej jaskini dobiegał grzmot, $N! Głośny, dudniący grzmot!$B$BChyba pod koniec wszyscy ją porzucili. Tych, którzy weszli ją zbadać, spotykały złe, bardzo złe rzeczy. Większość nigdy nie wróciła.$B$BChcę, żebyś $gsprawdził:sprawdziła; tę jaskinię, kiedy będziesz na Wykopaliskach Baelguna. Zbadaj okolice posągu tytana w środku i wróć z tym, czego się dowiesz.', 'Walt z Posterunku Ligi Odkrywców w Wyjącym Fiordzie chce, żebyś za pomocą Konstruktu żelaznych run $gzbadał:zbadała; grzmiącą jaskinię na Wykopaliskach Baelguna.$B$BPo wykonaniu zadania odwołaj konstrukt w oknie zwierzaka.', 'Zbadana grzmiąca jaskinia', 'Wróć do Walta w Posterunku Ligi Odkrywców w Wyjącym Fiordzie.', '', '', '', '', 0),
(11501, 'plPL', 'Wieści ze wschodu', 'Zachodnia Straż musi wiedzieć, co się tu dzieje, $N. Chcę, żebyś osobiście $gprzekazał:przekazała; wieści Kapitanowi Adamsowi.$B$BGdy będziesz $ggotów:gotowa;, daj znać, a jeszcze raz umieszczę cię w konstrukcie na ostatni lot. Zabierze cię do Twierdzy Zachodniej Straży, choć najpewniej przy okazji wybuchnie.$B$BTo była przyjemność...', 'Porozmawiaj z Kapitanem Adamsem w Twierdzy Zachodniej Straży.', '', '', '', '', '', '', 0),
(11504, 'plPL', 'Umarli powstają!', 'Ścieżka na wschód stąd to główny szlak łowiecki kiełzarów. A przynajmniej była...$B$BOstatnio nasi łowcy wracają do Kamagua i twierdzą, że umarli powstali i łakną krwi! Właśnie dlatego przybyliśmy tu z synem. Starszy Atuik prosi, żebyśmy rozwiązali sprawę na urwiskach.$B$BPomożesz nam w potrzebie? Szukam bohaterów, którzy odważą się stawić czoła niebezpieczeństwom Wzgórza Tarczy na południowy wschód stąd. Przeszukaj zbezczeszczone groby w poszukiwaniu wskazówek i przynieś mi to, co znajdziesz.', 'Orfus z Kamagua przy Pradawnej Windzie w Wyjącym Fiordzie chce, żebyś $godnalazł:odnalazła; Wskazówkę Fengira, Wskazówkę Rodina, Wskazówkę Isuldofa i Wskazówkę Windana.', '', 'Wróć do Orfusa z Kamagua przy Pradawnej Windzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11507, 'plPL', 'Starszy Atuik i Kamagua', '<Orfus zawija wskazówki, które mu $gprzyniosłeś:przyniosłaś;.>$B$BMój lud toczy zaciętą wojnę z Korsarzami z Morza Północnego. Jeśli któryś kiełzar może nam pomóc naprawić krzywdy wyrządzone przez piratów, to tylko Starszy Atuik z Kamagua. Musisz natychmiast zanieść mu te wskazówki.$B$BŻeby dotrzeć do Kamagua, musisz zjechać Pradawną Windą, która jest za mną. Zjedź windą prosto do Kamagua i odszukaj Starszego Atuika.', 'Orfus z Kamagua w Wyjącym Fiordzie chce, żebyś $gdostarczył:dostarczyła; Tobołek Orfusa Starszemu Atuikowi w Kamagua.', '', 'Wróć do Starszego Atuika w Kamagua w Wyjącym Fiordzie.', '', '', '', '', 0),
(11508, 'plPL', 'Grezzix Spindlesnap', 'Pirackie złodziejaszki założyły port na Cyplu Łajdaków, daleko na południu. Niestety umocniły swój obóz wieloma śmiercionośnymi zabezpieczeniami.$B$BJest ktoś, kto może pomóc nam przeniknąć na Cypel Łajdaków.$B$BPiracki najemnik imieniem Grezzix Spindlesnap przybył niedawno do naszej wioski w poszukiwaniu jedzenia i schronienia. W zamian przekazuje nam informacje o naszych wrogach, a im podsuwa fałszywe wieści o naszych planach ataku. Odszukaj go na jego statku tuż przy brzegu, na południowym zachodzie.', 'Porozmawiaj z Grezzixem Spindlesnapem.', '', '', '', '', '', '', 0),
(11509, 'plPL', 'Uliczny „szacun”', 'Wszyscy Korsarze z Morza Północnego boją się Grezzixa i go szanują. Myślę, że doceniają moje wyjątkowe talenty i zazdroszczą mi niesamowitego statku. Wystarczy, że pójdziesz z moim chłopcem okrętowym, Lou, i wejdziesz jak w masło... Jak w cynę. Piraci kochają cynę.$B$BPo prostu pogadaj z Lou, kiedy będziesz $ggotów:gotowa;, a zabierze cię na Cypel Łajdaków.$B$BA, najpierw zagadaj do Harry\'ego „Srebrna Luna”. Będzie wiedział więcej o rzeczach, które zwinęli. Tylko uważaj, co przy nim mówisz. To dziwak... ma bzika na punkcie krwawych elfów.', 'Porozmawiaj z Harrym „Srebrna Luna” na Cyplu Łajdaków o zaginionych wrykulskich artefaktach.', '', '', '', '', '', '', 0),
(11510, 'plPL', '„Scoodles”', 'Jedną z pierwszych rzeczy, jakie zrobił Jonah Sterling, kiedy mu odbiło, było zabranie mojego bezcennego kryształu jasnowidzenia sin\'dorei i nakarmienie nim zmory mojego życia, orki „Scoodles”.$B$BNie, to nie ja nadałem tej przeklętej bestii imię. Wiem tylko, że pływa za statkami prosto na południowy wschód od Cypla Łajdaków. Zabij tę przerośniętą złotą rybkę i wyrwij z jej brzucha mój piękny kryształ sin\'dorei.$B$BZrób to, a przejdziemy do interesów.', 'Harry „Srebrna Luna” z Cypla Łajdaków chce, żebyś $godzyskał:odzyskała; jego Kryształ jasnowidzenia sin\'dorei z orki „Scoodles”.', '', 'Wróć do Harry\'ego „Srebrna Luna” na Cyplu Łajdaków w Wyjącym Fiordzie.', '', '', '', '', 0),
(11511, 'plPL', 'Kostur furii burzy', 'Te artefakty są przeklęte i trzeba być szaleńcem, żeby ich szukać. Wiem na pewno, że każdy, kto miał bezpośrednią styczność z którymś z tych przedmiotów, albo oszalał, albo zginął.$B$BWeź na przykład ten kostur. Ostatnio słyszałem, że statek, który go wiózł, porzucono i zostawiono, żeby zbutwiał na wybrzeżu Wyspy Włóczni, na północ stąd.$B$BJeśli chcesz to coś, sprawdź ładownię statku.$B$BCokolwiek zrobisz, nie przynoś tu tego kostura! I trzymaj się z dala od Abdula! Wyrwie ci serce.', 'Odzyskaj Kostur furii burzy i dostarcz go Orfusowi z Kamagua w Wyjącym Fiordzie.$B', '', 'Wróć do Orfusa z Kamagua przy Pradawnej Windzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11512, 'plPL', 'Zamarznięte serce Isuldofa', 'Niektórzy mówią, że Jonah nigdy nie był całkiem po kolei w głowie, ale ja znam prawdę. To przez serce. To przeklęte zamarznięte serce! Widziałem, jak się zmienił w chwili, gdy wyciągnął je z grobu. Widziałem, jak krew zamarza mu w żyłach... Właśnie wtedy szaleństwo naprawdę nim zawładnęło.$B$BZostawił nas i zaszył się w swojej jaskini po północnej stronie tej wyspy. Ostatnio słyszałem, że wrzucił serce w głąb swojej niedźwiedziej nory. Za mało, za późno...$B$BZabiję cię osobiście, jeśli choćby pomyślisz o przyniesieniu tu tego serca!', 'Odzyskaj Zamarznięte serce Isuldofa i dostarcz je Orfusowi z Kamagua w Wyjącym Fiordzie.', '', 'Wróć do Orfusa z Kamagua przy Pradawnej Windzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11519, 'plPL', 'Zaginiona Tarcza Aesirytów', 'Jak się dobrze wsłuchasz, usłyszysz ogień armat od północnego wschodu. To statek kapitana Ellisa, Siostra Miłosierdzie. Rzecz w tym, że Ellis i cała jego załoga zginęli jakiś miesiąc temu.$B$B<Harry kiwa głową.>$B$BStatek widmo...$B$BJeśli chcesz się czegoś dowiedzieć o tarczy, Ellis to właściwy człowiek.$B$BSiostra Miłosierdzie przybija do małej wysepki między tym miejscem a Wybrzeżem Sorlofa, żeby zabrać kolejne dusze do załogi, mniej więcej co pięć minut. W tych stronach dusz nie brakuje...', 'Porozmawiaj z Kapitanem Ellisem na pokładzie Siostry Miłosierdzie.', '', '', '', '', '', '', 0),
(11527, 'plPL', 'Bunt na Miłosierdziu', 'Aj, mamy kłopoty, kamracie. Moi kanonierzy się zbuntowali! Ja i załoga na górze próbujemy skopać Sorlofowi rzyć, a przy tym użeramy się z buntownikami pod pokładem.$B$BMusisz zejść pod pokład, rozprawić się z tymi zbuntowanymi wilkami morskimi i zabrać im proch do wielkiego działa na rufówce.$B$BJak ty obsadzisz wielkie działo, Sorlof na pewno zginie i odda łup!', 'Kapitan Ellis z pokładu Siostry Miłosierdzie w Wyjącym Fiordzie poprosił cię o odzyskanie 5 Beczek prochu wybuchowego z ładowni statku.$B', '', 'Wróć do Kapitana Ellisa na pokład Siostry Miłosierdzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11529, 'plPL', 'Łup Sorlofa', 'Moja załoga przygotuje ci wielkie działo i nabije je jak trza, kamracie. Spoczywa sobie wygodnie na dziobie, po drugiej stronie statku. Idź, obsadź je i bądź w gotowości, by strzelić, gdy tylko Sorlof znajdzie się na celowniku!$B$BJak już załatwimy tego szczura lądowego, musisz odzyskać dla nas łup, bo przecież nie możemy opuścić tego przeklętego statku! Przynieś mi łup, a dostaniesz swoją działkę: tarczę...', 'Zabij Sorlofa z Wielkiego działa i odzyskaj Łup Sorlofa. Zanieś Łup Sorlofa Kapitanowi Ellisowi na pokład Siostry Miłosierdzie.', '', 'Wróć do Kapitana Ellisa na pokład Siostry Miłosierdzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11530, 'plPL', 'Tarcza Aesirytów', 'Oto twoja tarcza. Oby nie przeklęła cię tak jak mnie i mojej załogi. Nie musisz wracać do domu, ale tu zostać nie możesz... Na pewno są tacy, którzy chętnie by ją odzyskali.$B$BA teraz zabieraj to coś z mojego statku!', 'Zanieś Tarczę Aesirytów Orfusowi z Kamagua przy Pradawnej Windzie w Wyjącym Fiordzie.', '', 'Wróć do Orfusa z Kamagua przy Pradawnej Windzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11567, 'plPL', 'Pradawna zbroja kvaldirów', 'Byłem na statku, który wiózł tę zbroję. Ledwie ją załadowaliśmy i płynęliśmy z powrotem tutaj, kiedy zaatakował nas niszczyciel Porzuconych.$B$BWeszli na nasz statek, zagarnęli cały łup, a potem go zatopili.$B$BWtedy ostatni raz widziałem tę zbroję. Jeśli chcesz, możesz wziąć mój bombowiec z Cypla Łajdaków i polecieć na przeklętą wyspę, przy której cumuje ten niszczyciel. Pogadaj z moją kobietą, Alanyą, na zewnątrz. Wsadzi cię do bombowca.$B$BJeśli uda ci się znaleźć te rzeczy, nie waż się ich tu przynosić!', 'Odzyskaj Pradawną zbroję kvaldirów i dostarcz ją Orfusowi z Kamagua w Wyjącym Fiordzie.', '', 'Wróć do Orfusa z Kamagua przy Pradawnej Windzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(11568, 'plPL', 'Powrót do spoczynku', '<Orfus podaje ci torbę.>$B$BW tej torbie są artefakty, które $godzyskałeś:odzyskałaś;. Odszukaj kurhany na Wzgórzu Tarczy, daleko na południowym wschodzie, skąd pierwotnie skradziono te przedmioty, i zwróć artefakty. Mam nadzieję, że ten gest ukoi duchy, które teraz nawiedzają nasze tereny łowieckie.$B$BBądź $gsilny:silna;, $N...', 'Użyj Tobołka wrykulskich artefaktów przy splądrowanych kurhanach na Wzgórzu Tarczy, żeby zwrócić Zamarznięte serce Isuldofa, Tarczę Aesirytów, Kostur furii burzy i Pradawną zbroję kvaldirów.$B$BJeśli ci się uda, wróć do Orfusa z Kamagua przy Pradawnej Windzie.', '', 'Wróć do Orfusa z Kamagua przy Pradawnej Windzie w Wyjącym Fiordzie.', 'Zwrócona Tarcza Aesirytów', 'Zwrócony Kostur furii burzy', 'Zwrócone Zamarznięte serce Isuldofa', 'Zwrócona Pradawna zbroja kvaldirów', 0),
(11572, 'plPL', 'Powrót do Atuika', 'Wróć do Starszego Atuika w Kamagua. Trzeba ostrzec jego i resztę mojego ludu przed zagładą, która nadciąga od morza.$B$B<Orfus drży.>$B$BDotrzesz do niego Pradawną Windą. Proszę, pospiesz się!', 'Przekaż złe wieści Starszemu Atuikowi w Kamagua.', '', '', '', '', '', '', 0),
(11573, 'plPL', 'Orfus z Kamagua', 'Witaj, wędrowcze. Jestem Tępokieł z Kalu\'ak. Twój lud nazywa nas kiełzarami. Niedawno wysłano mnie z towarzyszem, żebyśmy zbadali dziwne wydarzenia na jednym z naszych szlaków łowieckich. Gdy zbliżyliśmy się do cmentarzyska zwanego Wzgórzem Tarczy, zaatakowali nas nieumarli. Miałem szczęście, że dotarłem do tego obozu, ale nie wiem, co się stało z Orfusem.$B$BRozdzieliliśmy się przy Pradawnej Windzie, na południowy wschód stąd, wzdłuż krawędzi urwiska. Sprawdzisz, czy nic mu nie jest?', 'Odszukaj Orfusa z Kamagua przy Pradawnej Windzie w Wyjącym Fiordzie.', '', '', '', '', '', '', 0),
(12181, 'plPL', 'Nadaj temu nazwę', 'No, no, ile to już trwało? Jak długo pracowaliśmy nad tą przeklętą zarazą? W końcu, po całej wieczności porażek, dostąpiliśmy doskonałości. To... to nawet nie ma jeszcze porządnej nazwy! Ta plaga... Nie, to jest to: ZARAZA! Ta zaraza rozedrze samą tkankę życia!$B$B<Harris podaje ci fiolkę.>$B$BA teraz znajdź opiekuna nietoperzy, Tobiasa, i pokaż mu próbkę. Wyśle cię w drogę do Jadozłości.$B', 'Pokaż Próbkę zarazy Tobiasowi Sarkhoffowi w Nowym Agamandzie.$B', '', 'Wróć do Tobiasa Sarkhoffa w Nowym Agamandzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(12182, 'plPL', 'Do Jadozłości!', 'Mam dla ciebie specjalnego nietoperza, $gkolego:koleżanko;. Najszybszy i najwygodniejszy, jakiego mam. Zabierze cię prosto do Jadozłości, i to w dobrym stylu.$B$BPo wylądowaniu po prostu przekaż fiolkę Głównemu siewcy zarazy Middletonowi.', 'Dostarcz Próbkę zarazy Głównemu siewcy zarazy Middletonowi w Jadozłości we wschodniej części Smoczych Pustkowi.', '', 'Wróć do Głównego siewcy zarazy Middletona na Smoczych Pustkowiach.', '', '', '', '', 0),
(12297, 'plPL', 'O zdrajcach i zdradzie', 'Listę, którą trzymam, trzeba dostarczyć Wielkiemu komendantowi Halfordowi Zmorze Żmijów. Dowodzi 7. Legionem stacjonującym w Twierdzy Zimowej Straży na wschodnich rubieżach Smoczych Pustkowi.$B$BJeśli któryś ze zdrajców z tej listy stacjonuje w Zimowej Straży... skutki mogą być katastrofalne.$B$BPospiesz się, $N. Pokaż dokument Greerowi Orehammerowi tu, w Twierdzy Zachodniej Straży, i wyjaśnij, na czym polega twoja misja. Wsadzi cię na swojego najszybszego gryfa do Zimowej Straży!', 'Kapitan Adams poprosił cię, żebyś $gpokazał:pokazała; Wiadomość Przymierza Greerowi Orehammerowi w Twierdzy Zachodniej Straży.', '', 'Wróć do Greera Orehammera w Wyjącym Fiordzie.', '', '', '', '', 0),
(12298, 'plPL', 'Wielki komendant Halford Zmora Żmijów', '<Greer oddaje ci wiadomość.>$B$BNiebiańska Pieśń zabierze cię do Zimowej Straży, $N. Gwarantuję ci, że to będzie najszybszy lot w twoim życiu. Ruszaj!$B', 'Dostarcz Wiadomość Przymierza Wielkiemu komendantowi Halfordowi Zmorze Żmijów w Twierdzy Zimowej Straży we wschodniej części Smoczych Pustkowi.$B', '', 'Wróć do Wielkiego komendanta Halforda Zmory Żmijów w Twierdzy Zimowej Straży na Smoczych Pustkowiach.', '', '', '', '', 0),
(12481, 'plPL', 'Do obelgi dorzuć cios', 'Wrykule są w tym sprytni. Na szczęście mam asa w rękawie.$B$BTen ich przywódca, Bjorn, to prawdziwy zapaleniec. Poskładaliśmy dość ich języka, żeby sklecić coś, co naszym zdaniem jest porządną obelgą. Coś o jego matce i wielkich zwierzętach z obory... nie jesteśmy do końca pewni.$B$BWeź tę kartkę i przeczytaj mu ją. Gdy zacznie cię gonić, zwab go tutaj. Dopilnujemy, żeby nie wyszedł z tego żywy.', 'Przeczytaj Wrykulską obelgę Bjornowi Halgurdssonowi w Baleheimie, a potem zwab go do Zasadzki Lydella i pomóż go zabić.', '', 'Wróć do Lydella przy Zasadzce Lydella w Wyjącym Fiordzie.', 'Znieważony Bjorn Halgurdsson', 'Pokonany Bjorn Halgurdsson', '', '', 0),
(12482, 'plPL', 'Przeciw Nifflevar', 'Czekamy na posiłki z Przystani Zemsty, żeby ruszyć na Nifflevar. Gdybyśmy jednak zdobyli je wcześniej, dałoby nam to sporą przewagę nad Przymierzem.$B$BIdź do miasta i spróbuj przetrzebić ich szeregi.', 'Kapitan tropicieli Areiel chce, żebyś $gposzedł:poszła; do Nifflevar i $gzabił:zabiła; 5 Wojowników Smokołupców, 4 Wieszczów run Smokołupców i 4 Ogary łowieckie Smokołupców.', '', 'Wróć do Kapitan tropicieli Areiel w Posterunku Widmowego Ostrza w Wyjącym Fiordzie.', '', '', '', '', 0),
(12566, 'plPL', 'Pomoc dla Obozu Zimowego Kopyta', 'Jestem Goniec Nanik z ludu taunka, wysłany przez wodza Obozu Zimowego Kopyta, by szukać sojuszników w walce z wrykulami. Gromadzą się na zachód i na południe od naszej wioski i choć na każdego naszego poległego zabijamy dziesięciu z nich, nie zdołamy się utrzymać.$B$BAptekarz Scyllis obiecał wysłać nam na pomoc na północny zachód dzielnych śmiałków. Pomożesz mojemu ludowi odeprzeć ataki wrykuli?$B$BIdź drogą daleko na północny zachód, przez rzekę, aż do podnóża gór, żeby dotrzeć do Obozu Zimowego Kopyta.', 'Porozmawiaj z Wodzem Popielnym Totemem w Obozie Zimowego Kopyta.', '', '', '', '', '', '', 0),
(13205, 'plPL', 'Rozbrojenie', 'Posłuchaj mnie, $gchłopcze:dziewczyno;, te wrykulskie bronie to paskudztwo!$b$bSam poczułem ich ostrze i jest w nich coś nienaturalnego. Zwodniczo dobrze wyważone, piekielnie ostre, po prostu zabójcze.$b$bDostań się do ich warowni i jak nic innego, to przynajmniej zwędź trochę tej broni! Może czegoś się o niej dowiemy, a może nie.$b$bKrótko mówiąc: im mniej toporów będą wymachiwać, tym lepiej.', 'Obrońca Mordun chce, żebyś $gwszedł:weszła; do Twierdzy Utgard i $gukradł:ukradła; 5 sztuk Wrykulskiej broni', '', 'Wróć do Obrońcy Morduna w Valgardzie w Wyjącym Fiordzie.', '', '', '', '', 0),
(13206, 'plPL', 'Rozbrojenie', 'Musimy odkryć sekret broni tych dzikusów!$b$bGdybyś $gwidział:widziała;, jak łatwo przecinali moich towarzyszy, $gzrozumiałbyś:zrozumiałabyś;, czemu tak mi pilno. Jeśli wątpisz w moje słowa, zajrzyj tylko do ich kuźni.$b$bPrzeszukaj to miejsce. Zbierz tyle ich broni, ile zdołasz unieść, i zanieś ją Anselmowi do obejrzenia.$b$bNie zawiedź nas, $N. Każda broń, którą stamtąd wyniesiesz, to o jedną mniej na polu bitwy.', 'Mroczna tropicielka Marrah chce, żebyś $gukradł:ukradła; 5 sztuk Wrykulskiej broni z Twierdzy Utgard i $gzaniósł:zaniosła; je Najwyższemu egzekutorowi Anselmowi w Przystani Zemsty.', '', 'Wróć do najwyższego egzekutora Anselma w Przystani Zemsty w Wyjącym Fiordzie.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(11153, 'plPL', 'To chciałem usłyszeć! Masz w sobie to coś, $N, co do tego nie ma wątpliwości!$B$BMoże wrócisz jutro, kiedy zrobimy więcej bomb kasetowych? Posłałbym cię tam od razu, ale mój pomocnik, Feknut, jeszcze nie wrócił z kolejną porcją nietoperzego guana do bomb.$B$BCiekawe, czemu tak długo mu to schodzi?', 0),
(11154, 'plPL', 'Fuj, co tak śmierdzi? Ach, to ty! No cóż, chyba faktycznie wysłałem cię do śmierdzącej roboty!$B$BDziękuję, $N. Nie martw się, dostarczę to Petrovowi, jak tylko się stąd wyniesiemy.$B$B<Feknut woła głośno do odkrywców.>$B$BSłyszeliście, chłopaki? Zmywamy się stąd, do diabła!!!', 0),
(11155, 'plPL', 'Będzie z tego porządny posiłek dla chłopaków.$B$B<Kuchmistrzyni nachyla się, by szepnąć ci do ucha.>$B$BMasz, $gchłopcze:kochaniutka;, weź trochę dla siebie. Wyglądasz, jakby przydało ci się więcej mięsa na kościach!', 0),
(11157, 'plPL', 'Dobra robota! Przy odrobinie szczęścia zniszczenie ich lęgów i piskląt przepędzi te ogniste bestie i powstrzyma rozprzestrzenianie się tego magicznego pożaru.$B$BChwila... co to za dźwięk? Brzmi jak łopot skrzydeł.', 0),
(11167, 'plPL', 'Dobrze, że wracasz w jednym kawałku. Ryzyko zakażenia przy przenoszeniu tych pojemników nie jest zerowe. Chyba powinienem był cię wcześniej ostrzec.', 0),
(11168, 'plPL', 'Wciąż dowodzisz swoich umiejętności, $N. Oby ta toksyna wystarczyła, żeby podnieść siłę naszej zarazy do potrzebnego poziomu.$b$bW najgorszym razie powinna osłabić ofiarę i uczynić ją bardziej podatną na zakażenie.', 0),
(11170, 'plPL', 'Hmmm... raporty z terenu są... niezbyt zachęcające!', 0),
(11175, 'plPL', 'Grrr. Wiedziałam! On jest taaaki nadopiekuńczy! To po prostu żenujące.$B$BNie żebym się nie cieszyła, że cię widzę... cieszę się! Wszyscy się cieszymy. Przyda nam się twoja pomoc!', 0),
(11176, 'plPL', 'Irena cię przysłała, tak? Świetnie, w takim razie mamy dla ciebie robotę!', 0),
(11182, 'plPL', 'Szkoda, że jeden drapieżnik musi posłużyć do zgładzenia drugiego, ale taki jest naturalny porządek rzeczy.$B$BByć może teraz protosmokowce i ich pisklęta wrócą do spokojnego życia. Jakoś w to wątpię, skoro wrykule znów się przebudzili.', 0),
(11187, 'plPL', '<Malister przywołuje cię gestem bliżej i mówi szeptem.>$B$BObawiałem się, że coś takiego może się stać. Próbowałem odwieść kapitana od tego planu, ale to krasnolud czynu, z bardzo wyrobionym zdaniem na temat tego, jak sprawy powinny się toczyć.$B$BPomówmy o możliwościach, jakie nam zostały.', 0),
(11188, 'plPL', '<Mag-porucznik wzdycha.>$B$BPrzykra sprawa, bez wątpienia. Cóż, co się stało, to się nie odstanie. Przy odrobinie szczęścia nowe pisklęta, które wyrosną na smoki w Żarzącym Lęgu, nie zapamiętają naszych haniebnych czynów.$B$BA przy odrobinie większego szczęścia granice tego magicznego lasu przestaną się rozszerzać.$B$BProszę, $N, przyjmij z naszego skarbca ten skromny datek za wszystkie twoje trudy. To najmniej, co możemy zrobić.', 0),
(11190, 'plPL', 'Och, niech cię, $N, niech cię Światłość błogosławi!$B$BPołóż je tam, gdzie stoisz. Zaraz przyślę któregoś z chłopaków, żeby je załadował, i przestaniem się martwić, że nam zabraknie kul do walenia w Skorn.', 0),
(11199, 'plPL', 'O, świetnie, pomoc, i to w samą porę!', 0),
(11202, 'plPL', 'Świetnie!$B$BAle co to za rzeczy, które $gznalazłeś:znalazłaś; w tych zbiornikach? Chcesz powiedzieć, że Porzuceni rozpylają zarazę na tamtejszych wrykulów?', 0),
(11218, 'plPL', 'Ruda dała ci dziwne uczucie? Może jednak nie będziemy jej używać.$B$B<Stalowy Pierścień patrzy na rudę, cofa się o krok i zmienia temat.>$B$BTe klejnoty wyglądają naprawdę ładnie! Ciekawe, ile za nie dostanę? Choć oczywiście zawsze są jakieś naprawy i nowe rzeczy do zrobienia.$B$BWiesz, praca z tobą okazała się naprawdę opłacalna. Weź to... to najmniej, co mogę zrobić!', 0),
(11221, 'plPL', 'Działa nas powstrzymują? Ja im pokażę działa.', 0),
(11224, 'plPL', 'Mam u ciebie dług, $N. Skoro odzyskaliśmy większość mułów i sprzętu, możemy mieć nadzieję, że wkrótce odbudujemy nasze siły.$B$BProszę, weź to.', 0),
(11227, 'plPL', '$GUpolowałeś:Upolowałaś; trochę wron, $gchłopcze:dziewczyno;? $GDobry chłopiec:Dobra dziewczynka;, $gdobry chłopiec:dobra dziewczynka;!$b$bAch, te ogary przypominają mi czasy, kiedy hodowałem rasowe psy w Tirisfal... to były piękne czasy!', 0),
(11228, 'plPL', 'Krasnolud mówi prawdę. Nie możemy sobie pozwolić na utratę tego portu. To jedna z dwóch bezpiecznych przystani, jakie Przymierze ma w tym kawałku zamarzniętego piekła – druga leży kilkaset mil na zachód stąd, na wybrzeżu Boreańskiej Tundry.', 0),
(11229, 'plPL', 'Mam nadzieję, że jesteś $ggotów:gotowa; do walki, $N. Flota Królowej cię potrzebuje!', 0),
(11230, 'plPL', 'Nieźle $gprzetrzebiłeś:przetrzebiłaś; te kundle. Moi ludzie uprzątną resztę.', 0),
(11231, 'plPL', 'Niech cię Światłość błogosławi, dziecko! Dzięki twojej pomocy Światłość świeci nawet w najciemniejszych miejscach.$B$BProszę, przyjmij to jako słuszną zapłatę za dobre uczynki. Zatroszczę się o zbawienie tych, których $guwolniłeś:uwolniłaś; – przynajmniej tych, którzy prawdziwie trwają w Światłości i w Przymierzu i wrócili tu, do twierdzy.', 0),
(11232, 'plPL', 'Doskonale. Dam sygnał naszym wojskom lądowym, żeby ruszały.', 0),
(11233, 'plPL', 'To oznacza bezsporne zwycięstwo naszych sił. Anselm bardzo się ucieszy, gdy o tym usłyszy.', 0),
(11234, 'plPL', 'Najwyższy czas. Przymierze od dawna było dla nas cierniem w boku.$b$bNie ma jednak czasu na świętowanie. Spójrz na zachód, wygląda na to, że mamy gości.', 0),
(11235, 'plPL', 'Dobra robota, $N, i dobrze, że się ich pozbyliśmy.$B$BAle to, co mówisz o tamtym miejscu, wciąż mnie niepokoi. Coś mi mówi, że jeszcze nie skończyliśmy przerzedzać ich szeregów!', 0),
(11236, 'plPL', '<Kapitan oddycha z ulgą.>$B$BCóż, to powinno trochę nas odciążyć.$B$B$N, raz za razem $gdowodziłeś:dowodziłaś;, jak wiele znaczysz dla Twierdzy Zachodniej Straży i całego Przymierza. Wybierz coś ze skarbca, $gchłopcze:dziewczyno;! To najmniej, co możemy zrobić!', 0),
(11237, 'plPL', '$N, nie możemy do tego dopuścić!', 0),
(11238, 'plPL', 'Ale ten róg jest zimny!$B$BPo raz kolejny $gocaliłeś:ocaliłaś; Twierdzę Zachodniej Straży przed pewną zgubą. Ciekawa z ciebie postać, $N. Gdyby tylko było więcej takich jak ty.$B$BCóż, to z pewnością zasługuje na nagrodę. Co wolisz?', 0),
(11239, 'plPL', '<Kapłan bezgłośnie odmawia nad tobą błogosławieństwo.>$B$BNiech cię Światłość błogosławi, $N, $gwysłuchałeś:wysłuchałaś; moich modlitw. Stań dumnie w Światłości, z wysoko uniesioną głową, wiedząc, że twoje czyny były najświętsze!$B$BJestem pewien, że w skarbcu kościoła znajdzie się coś, co ci się przyda.', 0),
(11240, 'plPL', '<Saper burczy, jakby wolał, żeby ci się nie udało.>$B$BKapitan ucieszy się, gdy usłyszy o twoim sukcesie.$B$BWiesz co, skoro tak dzielnie $gpodszedłeś:podeszłaś; do tej całej sprawy z Wąwozem Szeptów, może wybierzesz sobie coś z tego?', 0),
(11241, 'plPL', 'Aptekarz Hanes żyje? $GSpaliłeś:Spaliłaś; zapasy Przymierza do gołej ziemi? Musiał mieć z tego niezłą frajdę.$b$bTak czy inaczej, Królewskie Zakłady Chemiczne mają u ciebie dług, $N. Dziękujemy ci z głębi naszych czarnych, czarnych serc.', 0),
(11243, 'plPL', '$GZapewniłeś:Zapewniłaś; naszym obrońcom wsparcie, którego potrzebowali, $N. Dzięki tobie morale jest wyższe niż kiedykolwiek. Myślę, że z resztą natarcia poradzą sobie sami. Mam wobec ciebie większe plany...', 0),
(11244, 'plPL', 'To, co wrykule zrobili naszym zwiadowcom, było makabrycznym pokazem dzikości. Taktyka zastraszania, która miała osłabić naszą determinację... sprawić, byśmy uciekali w strachu o życie.$B$BNie udało się.$B$BPokażemy tym potworom, co znaczy toczyć wojnę z Przymierzem!', 0),
(11245, 'plPL', 'Świetne celowanie, $gpanie:pani;! Muszę pamiętać, żeby postawić kolejkę artylerzystom w twierdzy.', 0),
(11246, 'plPL', 'Cóż, $gpanie:pani;, muszę przyznać, że $gpodszedłeś:podeszłaś; do tej konkretnej roboty z pewną... gorliwością.$B$B<Sierżant przygląda ci się podejrzliwie.>$B$BTak czy inaczej, jeśli pozwolisz, zabiorę już swoją maczetę. Wygląda na stępioną, a nie chcielibyśmy, żeby ci się przypadkiem omsknęła i żebyś mnie też $gposiekał:posiekała;.', 0),
(11247, 'plPL', 'Bardzo dobrze, $gpanie:pani;. Bez twojej pomocy nie dałoby się tego zrobić.$B$BJestem pewien, że kapitan będzie zadowolony z mojego raportu w tej sprawie, kiedy już tu skończymy.', 0),
(11248, 'plPL', 'Miło mi cię poznać, $gpanie:pani;! Cieszę się na wspólną pracę.$B$BSkoro o tym mowa, mamy mnóstwo do zrobienia.', 0),
(11249, 'plPL', 'Tak, $gmój synu:moja córko;, to wygląda złowieszczo i najwyraźniej $gmiałeś:miałaś; rację.$B$BDziękuję, że $gprzyniosłeś:przyniosłaś; mi ten zwój. Bardzo chcę zbadać, co z niego wynika. Gdybym miał zgadywać, powiedziałbym, że ci wrykule znają sposób, by przekroczyć granicę śmierci – przynajmniej ci, którzy są tego godni.$B$BPokonując thana Zimowego Skornu, $gdowiodłeś:dowiodłaś;, że był niegodny. Tylko Światłość wie, czym by się stał i jaki terror mógłby na nas sprowadzić, gdybyś go nie $gzabił:zabiła;.', 0),
(11250, 'plPL', 'To niewiarygodnie dobre wieści! Wiedziałem, że dasz radę, $N!$B$BPrzynajmniej ktoś tutaj potrafi przynieść wyniki!$B$BCóż, to zasługuje na nagrodę. Śmiało, wybieraj; skarbiec stoi przed tobą otworem.', 0),
(11251, 'plPL', 'Choć przychodzisz późno, dobrze widzieć przyjazną twarz.$b$bA teraz przestań tak stać i dłubać w nosie. Jest robota do zrobienia!', 0),
(11252, 'plPL', 'Znakomicie!$b$bTo może być ten łut szczęścia, na który wszyscy czekaliśmy.$b$bDobra robota, $N!', 0),
(11253, 'plPL', 'Ten łuskowaty zwój pokrywają surowe, malowane obrazy. Masz przeczucie, że o coś takiego chodziło psiarzowi, kiedy prosił cię o szukanie wskazówek.', 0),
(11254, 'plPL', '<Najwyższy egzekutor uważnie przygląda się mapie, co jakiś czas spoglądając na charakterystyczne punkty w fiordzie.>$b$bTu jest wschodnie wybrzeże. Wioski Smokołupców i Zimowego Skornu są tu i tu... a to tutaj to na pewno my, naznaczeni na śmierć.', 0),
(11255, 'plPL', 'Żołnierze, których $guratowałeś:uratowałaś;, mieli dla nas sporo informacji. Te potwory nazywają siebie „wrykulami”. Plemieniem, które zajęło Wioskę Czaszki Żmija, przewodzi mistyk imieniem Yanis, który sam podlega innemu wrykulowi, znanemu jako Ingvar Łupieżca.', 0),
(11256, 'plPL', 'Ciekawie będzie poznać twój lud, $N, walcząc u twego boku.$b$bRuszamy?', 0),
(11257, 'plPL', 'Robisz to nie pierwszy raz? Władasz moją maczetą, jakbyś $gmiał:miała; wprawę.$b$b<Wojownik przygląda ci się podejrzliwie.>$b$bTeraz ją od ciebie odbiorę, $N.', 0),
(11258, 'plPL', '<Wojownik kiwa głową z wyraźnym uznaniem dla tego, jak posługujesz się pochodnią.>$b$bNiech ci wrykule poczują żar tej ziemi. Niech poznają strach, który sami chcieli siać!', 0),
(11259, 'plPL', 'Masz mocne ramię, $N.$b$bWygląda na to, że ci jeźdźcy wiwern w końcu na coś się przydali, zamiast tylko stać i pić cały dzień.', 0),
(11260, 'plPL', 'Tak, to wygląda złowieszczo i najwyraźniej $gmiałeś:miałaś; rację.$b$bDziękuję, że $gprzyniosłeś:przyniosłaś; mi ten zwój. Zbadam, co z niego wynika. Gdybym miała zgadywać, powiedziałabym, że ci wrykule znają sposób, by przekroczyć granicę śmierci – przynajmniej ci, którzy są tego godni.$b$bPokonując thana Zimowego Skornu, $gdowiodłeś:dowiodłaś;, że był niegodny. Kto wie, czym by się stał i jaki terror mógłby na nas sprowadzić, gdybyś go nie $gzabił:zabiła;?', 0),
(11261, 'plPL', 'To naprawdę dobre wieści! $GDałeś:Dałaś; nam trochę wytchnienia, byśmy mogli dalej przygotowywać się do odejścia.$b$bProszę, weź jedno z tych w dowód naszego uznania.', 0),
(11262, 'plPL', 'Znakomita robota, $N. Bez przywódcy wrykule będą łatwiejszym celem dla naszych działań.$b$bTaka służba nie może pozostać bez nagrody!', 0),
(11263, 'plPL', 'Dziękuję ci, $N. Wiem, że nie masz żadnych zobowiązań wobec mnie ani mojego ludu.$b$bTo, co mówisz o tamtym miejscu, wciąż mnie niepokoi i przeczuwam, że jeszcze nie skończyliśmy przerzedzać ich szeregów.', 0),
(11264, 'plPL', '<Wódz Popielny Totem oddycha z ulgą.>$b$bTo powinno trochę nas odciążyć.$b$b$N, raz za razem $gdowodziłeś:dowodziłaś; swojej wartości ludowi taunka z Obozu Zimowego Kopyta. Proszę, wybierz coś z naszych zasobów. Nalegam.', 0),
(11265, 'plPL', 'Wieść o twoim sukcesie zdejmuje mi z barków wielki kamień. I cieszę się, że wśród uwolnionych byli także ludzie z mojego ludu.$b$bProszę, przyjmij to jako dar za to, czego $gdokonałeś:dokonałaś;. Zatroszczę się o zdrowie tych, których $guwolniłeś:uwolniłaś;.', 0),
(11266, 'plPL', '$N, nie możemy do tego dopuścić!', 0),
(11267, 'plPL', 'Ten róg jest zimny jak ta ziemia... a może nawet zimniejszy!$b$b$GOcaliłeś:Ocaliłaś; Obóz Zimowego Kopyta przed pewną zgubą, choć i tak nie zostaniemy tu już długo. Ciekawa z ciebie postać, $N. Może wy, przybysze zza oceanu, nie jesteście jednak tacy źli.$b$bTo zasługuje na nagrodę. Co wolisz?', 0),
(11268, 'plPL', '<Wszechmatka kiwa głową z uznaniem dla twoich czynów.>$b$bDziękuję, $N, $gpostąpiłeś:postąpiłaś; słusznie i $gdałeś:dałaś; nam trochę więcej czasu na dokończenie przygotowań do odejścia. Wkrótce wyruszymy w drogę na północ.$b$bJestem za stara; kiedy odejdziemy, nie zdołam zabrać wszystkiego ze sobą. Może weźmiesz sobie jedną z tych rzeczy?', 0),
(11269, 'plPL', 'Dzięki Światłości! To powinno wystarczyć, żeby skończyć zamówienie na czas. Oczywiście nie zmrużę oka, dopóki nie przybędą wojska, ale to i tak lepsze, niż ryzykować gniew kapitana Adamsa.$B$BSłyszałem, co o nim opowiadają!', 0),
(11270, 'plPL', 'Cieszę się, że $gudowodniłeś:udowodniłaś;, że potrafisz wykonywać rozkazy. Gdybym dostawał miedziaka za każdego aroganckiego głupca w lśniącej zbroi, który przychodzi tu i myśli, że stoi ponad hierarchią dowodzenia... cóż, miałbym kilka sztuk złota.$b$bSkoro $gwykazałeś:wykazałaś; się odrobiną dyscypliny, mam inne zadania, bardziej odpowiednie dla kogoś twojego kalibru.', 0),
(11271, 'plPL', 'Dzięki twojemu wkładowi będziemy dobrze przygotowani do podróży. Niewiele mam do zaoferowania w zamian za pomoc, ale pozwolę ci wybrać coś z mojego zapasowego ekwipunku bojowego.', 0),
(11272, 'plPL', 'Zemsta smakuje dobrze. Pomyśleć, że to tylko przedsmak tego, co nadejdzie.$b$bArthas wkrótce dostanie to, na co zasłużył. Wtedy i tylko wtedy umrę szczęśliwy.', 0),
(11273, 'plPL', '$GZnalazłeś:Znalazłaś; Pulroya. Chyba trochę za późno.$B$BOglądając zwłoki, dostrzegasz dziennik kurczowo ściśnięty w martwej dłoni Pulroya. Przeglądając go, czytasz coś, co wygląda na bazgroły umierającego krasnoluda.', 0),
(11274, 'plPL', '$GZnalazłeś:Znalazłaś; Zedda. Nie jesteś lekarzem, ale rokowania dla Zedda są z całą pewnością złe.$B$BWygląda na to, że szykowali się, by rzucić go worgom na pożarcie. Makabra...', 0),
(11275, 'plPL', 'Wszystkie te rogi są piękne, $N. Pozwól, że je obejrzę i wybiorę ten, którego użyję na polowaniu.$b$bResztę oddam rzemieślnikom do rzeźbienia.', 0),
(11276, 'plPL', 'No najwyższy czas, do licha! Pulroy i Zedd nie żyją.$B$BA Daegarn...$B$B<Glorenfeld kręci głową.>$B$BZabrał go wódz Smokołupców w głąb tych katakumb. Podsłuchałem, jak ten przerośnięty kundel mówił coś o ofierze dla „Straszliwego Króla”.$B$BSzyfr jest ukryty w brudnej brodzie Daegarna.$B$BCo? Krasnoludy cały czas chowają rzeczy w brodach!', 0),
(11277, 'plPL', 'Dobra robota, kamracie. Teraz, gdy zabezpieczyliśmy tablice, możemy spróbować ocalić Daegarnowi życie i odzyskać szyfr, który pomoże nam odczytać znaczenie tych starożytnych reliktów!$B$BJa przypilnuję tablic, a ty uratuj Daegarna.\n\n', 0),
(11278, 'plPL', 'Uporządkowanie tych tablic zajmie trochę czasu. Z pobieżnych badań mogę tylko wywnioskować, że to, co tu kiedyś żyło, było przodkiem ludzi. Te wrykule pewnie wszystkich ich wybiły. Tak czy inaczej, będziemy wiedzieć więcej, kiedy przygotuję te relikty do badań.', 0),
(11279, 'plPL', 'Co?! Nie, to niemożliwe.$b$bNIECH TO SZLAG!$b$bTa partia zarazy nie wywarła na protopisklęta żadnego realnego wpływu, poza tym, że świecą na zielono!$b$bMoje marzenie o użyciu zarazy na wszystkim, z czym się zetkniemy, chyba poszło z dymem!', 0),
(11280, 'plPL', 'NIEEEEEEEEEEEEEEE!!!$b$b<Siewca zarazy zaczyna płakać.>$b$bWszystkie moje nadzieje... wszystkie marzenia, zniweczone!$b$bZostaw mnie, $N. Zostaw mnie z moją rozpaczą. Jestem nikim.$b$bMasz, równie dobrze możesz wziąć cały mój doczesny dobytek. Kiedy reszta aptekarzy usłyszy o mojej porażce, będzie po mnie i tak czy siak nie będzie mi potrzebny.', 0),
(11281, 'plPL', '<Nokoma słucha twojego sprawozdania z próby.>$b$bUlżyło mi, że róg zadziałał tak dobrze... może nawet zbyt dobrze, jeśli to, co mówisz, jest prawdą. Na pewno ta bestia mówiła? Nie wiem, czy mogę brać udział w łowach, jeśli to prawda. Będę musiała porozmawiać o tym z wodzem Popielnym Totemem.$b$bTen róg może skończyć jako zwykła ozdoba, ale to nie umniejszy jego wartości. Dziękuję za całą twoją pomoc, $N.', 0),
(11282, 'plPL', 'Ty dobrze zabijać tam. Gorth widzi, jak wrykule padać i dostawać dźgnięcie flagą Sylwany. Nasza strona dobrze idzie!', 0),
(11283, 'plPL', 'Ty chyba dużo ćwiczyć zabijanie. Ty prawie tak $gdobry:dobra; jak Gorth!', 0),
(11284, 'plPL', 'Udało ci się? Na Światłość, jesteś chodzącym cudem! Już myślałem, że będę musiał osobiście tłumaczyć kapitanowi Adamsowi, czemu broń jego ludzi nie jest gotowa na czas!', 0),
(11285, 'plPL', 'Chyba ty spalić wszystko. Gorth widzi kilka miejsc, co się nie palą... ale dla Gortha wystarczy.', 0),
(11286, 'plPL', '<Mędrzec pomrukuje z aprobatą dla tego, co dla niego $gzrobiłeś:zrobiłaś;.>$b$bMoże niedługo znajdę czas, by zbadać te artefakty i zrozumieć ich znaczenie.$b$bAle teraz są pilniejsze sprawy.', 0),
(11287, 'plPL', 'Moja matka nie powinna się martwić o moje bezpieczeństwo. Ale dziękuję ci za przybycie, $gnieznajomy:nieznajoma;.$b$bSkoro już tu jesteś, może pomożesz mi w kilku sprawach?', 0),
(11288, 'plPL', 'Czujesz wewnętrzny przymus, by położyć święte ostrze obok ciała Aresa.$B$BGdy to robisz, znów oślepia cię światło.', 0),
(11289, 'plPL', 'Wielu mężczyzn i kobiet zginęło, by odzyskać to ostrze. Niestety obawiam się, że dzielny Ares nie będzie ostatni.$B$BAle wykonujesz dzieło Światłości, $gbohaterze:bohaterko;. Tym świętym ostrzem będzie władał sam lord Tirion Fordring. Nawet teraz Krucjata Argentu posuwa się ku Lodowej Koronie. Lord Fordring poprzysiągł, że własnoręcznie zburzy mury tego przeklętego miejsca! A z tym ostrzem może mieć szansę w starciu z Królem Liszem.$B$BLord Fordring pozostaje naszą największą nadzieją.', 0),
(11290, 'plPL', '<Wiceadmirał Keller przegląda plany.>$B$BZnakomicie! Wygląda na to, że w fiordzie jest znacznie więcej wiosek wrykulów. Inne plemię wrykulów szykuje szturm na Twierdzę Zachodniej Straży. Do diabła, może już być za późno. Od kilku dni nie mamy wieści z Zachodniej Straży. Tak czy inaczej, musimy ostrzec Zachodnią Straż!', 0),
(11291, 'plPL', '<Kapitan Adams bierze od ciebie plany.>$B$BCieszę się, że $gzdecydowałeś:zdecydowałaś; się przybyć. Moi doradcy i ja będziemy potrzebować trochę czasu na przestudiowanie tych planów. Tymczasem przyda nam się każda pomoc!', 0),
(11292, 'plPL', '<Traper Jethan ogląda przyniesione przez ciebie stworzenia.>$B$BŁadnie. Za niektóre dostanę lepszą cenę niż za inne, ale powinienem mieć mnóstwo towaru na wymianę z miejscowymi.', 0),
(11295, 'plPL', 'Ty przyjść pomóc? Dobrze... dobrze...$b$bGorth już zmęczony zabijać wrykule cały dzień. Pomoc mile widziana!', 0),
(11296, 'plPL', 'To był bardzo odważny czyn, $N. Nie wiedziałem, że twój lud stać na taką bezinteresowność.$b$bNastępnym razem posłucham ostrzeżeń starszych i będę omijał Rozdarty Las. Radzę ci zrobić to samo.', 0),
(11297, 'plPL', 'Ach tak, skryci ludzie-bizony z północy. Widziałem, jak się tu czają, przekonani, że nikt ich nie widzi. Pewnie uważają tę ziemię za swoją? Cóż, to tylko jedna z wielu rzeczy, które wkrótce się zmienią.$b$bNie spodziewałem się towarzystwa, ale skoro już tu jesteś z tą głupią misją, równie dobrze możesz się na coś przydać.', 0),
(11298, 'plPL', '<Aptekarz nalewa sobie kufel trunku.>$b$bNo to jazda!', 0),
(11299, 'plPL', 'Tak. $GZnalazłeś:Znalazłaś; mnie. Hurra!$b$bI nie, nie mam szyfru. Moja broda to pierwsza rzecz, jaką te bestie przeszukały! Teraz ma go Oluf. To wódz gladiatorów.', 0),
(11300, 'plPL', 'Fascynująca historia! Coś naprawdę osądza te stwory? W jakim celu?! Po co?$b$bA zresztą, nieważne te bzdury. Niech ktoś inny to rozgryzie. Odzyskaliśmy szyfr i tablice – i tylko dwie ofiary śmiertelne w całej tej przeprawie.', 0),
(11301, 'plPL', 'Te mózgi są piękne! Wręcz przepiękne! Dokładnie tego mi trzeba.$b$bDziękuję za pomoc, $N. Teraz pokażę Malthusowi prawdę, której nie dostrzegł przez piwne okulary.', 0),
(11302, 'plPL', '<Lurielle słucha, jak się przedstawiasz.>$B$BDobrze w końcu cię poznać, $N. Od dawna miałyśmy nadzieję, że ty i inni przybysze przyślecie swoich przedstawicieli. Rzadko zapuszczamy się poza granice naszych polan, zwłaszcza teraz, gdy ziemia przechodzi takie zmiany.', 0),
(11303, 'plPL', 'Wszyscy przyszliśmy na przyjęcie, ale gość honorowy został w domu.', 0),
(11304, 'plPL', 'Ten szczep wcale nie jest bezwartościowy, $gprzyjacielu:przyjaciółko;! Ci głupcy z Przystani Zemsty mieli wszystkie odpowiedzi pod samym nosem!', 0),
(11305, 'plPL', 'To wystarczy. Czas na prawdziwą pracę aptekarską, $N!', 0),
(11306, 'plPL', 'Doskonale! $GPojętny z ciebie uczeń:Pojętna z ciebie uczennica;, $N.$b$bA teraz najlepsza część. Wdrożenie!', 0),
(11307, 'plPL', 'Zaraza nie rozłożyła naszych obiektów? Na pewno, $N??!$b$bMusi istnieć jakiś czynnik zewnętrzny, którego nie uwzględniamy... może niskie temperatury tego klimatu? A może... mutacja w szczepie!', 0),
(11308, 'plPL', 'Czego chcesz? Nie widzisz, że jestem w trakcie roboty?', 0),
(11309, 'plPL', 'Doskonale! Tak, tak, te się świetnie nadadzą!', 0),
(11310, 'plPL', 'Świetna robota, $N. Powiedz, nie szukasz przypadkiem czegoś bardziej... stałego? Przydałaby mi się pomoc w tych stronach!', 0),
(11311, 'plPL', 'Wpływ duchów żywiołów osłabł, ale powróci. Zyskaliśmy czas potrzebny, by dokończyć tu nasze sprawy i odejść.', 0),
(11312, 'plPL', '<Lurielle słucha, jak się przedstawiasz.>$b$bDobrze cię poznać, $N. Moje siostry często obserwowały, jak lud taunka przeszukuje lasy w poszukiwaniu nas, ale nasza królowa zabrania nam kontaktów z obcymi. Widzisz nas teraz tylko dlatego, że ziemia stała się niespokojna, a wiele moich sióstr jest w niebezpieczeństwie.', 0),
(11313, 'plPL', '<Lurielle w milczeniu przyjmuje od ciebie rdzenie.>$B$BDziękuję, $N.$B$B<Lurielle ze smutkiem spogląda na lodowe rdzenie.>$B$BObiecuję, przyjaciele, zrobię wszystko, co w mojej mocy, by was przywrócić.', 0),
(11314, 'plPL', 'Więc jest nadzieja dla moich sióstr?$B$B<Lurielle odwraca od ciebie wzrok i spogląda w ziemię.>$B$BCzuję się winna, że wcześniej nie pomyślałam o wisiorze. Mogłyśmy ocalić jeszcze więcej sióstr.', 0),
(11315, 'plPL', 'Dziękuję za pomoc, $N. Tętniąca Polana była kiedyś pięknym miejscem, a gdy do niej wrócimy, znów taka będzie.', 0),
(11316, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, $N. Gdybyśmy miały takich sojuszników jak ty, kiedy ziemia zaczęła się zmieniać, może zdołałybyśmy ocalić choć część tego, co utraciłyśmy.', 0),
(11317, 'plPL', 'Już wyczuwam w tobie zmianę.$b$bCzy jesteś $ggotów:gotowa; na to, co nadejdzie?', 0),
(11319, 'plPL', 'Lodowy rdzeń dobrze ci się sprawdził? Muszę to zapamiętać. Jestem pewna, że opiekunowie nie przestaną tylko dlatego, że raz zniweczono ich dzieło.', 0),
(11322, 'plPL', 'Już wyczuwam w tobie zmianę.$B$BCzy jesteś $ggotów:gotowa; na to, co nadejdzie?', 0),
(11323, 'plPL', 'Wyglądasz i pachniesz inaczej... nie należysz do mojej watahy. Opowiedz mi swoją historię; póki jestem tu uwięziony, czasu mam aż nadto.', 0),
(11324, 'plPL', 'Garwal wcale nie był worgiem! Znam te stworzenia... nazywają się worgenami.$b$bAle Ulfang wspomniał, że przybył na południe ze Wzgórz Grizli? Dziwne. Tam nie ma worgenów.$b$bDziękuję, że $gpomogłeś:pomogłaś; przywrócić Ulfangowi należne mu miejsce w watasze. Teraz obaj będziemy mogli spokojnie spać.$b$bProszę, przyjmij to w dowód wdzięczności.', 0),
(11325, 'plPL', 'Wyglądasz i pachniesz inaczej... nie należysz do mojej watahy. Opowiedz mi swoją historię; póki jestem tu uwięziony, czasu mam aż nadto.', 0),
(11326, 'plPL', 'Garwal wcale nie był worgiem! To, w co według twojego opisu się przemienił, bardzo przypomina worgena!$B$BAle Ulfang mówił, że przybył na południe ze Wzgórz Grizli? Dziwne. Tam nie ma worgenów.$B$BDziękuję, że $gpomogłeś:pomogłaś; przywrócić Ulfangowi należne mu miejsce w watasze. Teraz oboje będziemy mogli spokojnie spać.$B$BProszę, przyjmij to w dowód wdzięczności.', 0),
(11327, 'plPL', 'O rany... co do diabła?! Spójrz na to!$B$BMusimy to jak najszybciej dostarczyć do twierdzy!', 0),
(11328, 'plPL', 'Och... hej, to coś inszego!$B$BDobra, dej no zobaczyć te szutki. Szwyczajnie uwielbiam dłubać w alchemii!$B$BCiekawe, ciekawe... o, chyba wiem, co zrobić. Troszkę tego wymieszać z akurat odpowiednią ilością tego tu.$B$BWieszsz, chyba kapka tego bimbru też pomoże ...hik!', 0),
(11329, 'plPL', 'Cóż, są wystarczająco brzydkie, ale chyba nie obchodzi mnie, czy naprawdę zadziałają. Ulży mi, kiedy wyprawa już tędy przejdzie i znów będę mógł łowić ryby po prostu na obiad.', 0),
(11330, 'plPL', 'Hę? No to klapa! Kurczę, pogorszyłam szprawę. Właściwie to chyba udoszkonaliłam im ich zarazę ...hik!$B$B<Peppy krzywi się i pociąga ogromny łyk jakiegoś paskudnego trunku, który pije.>$B$BNo, miałam nadzieję, że do tego nie dojdzie, ale wygląda na to, że nie ma innego wyjszcia ...hik.', 0),
(11331, 'plPL', 'Tak, $N, co tym razem?$B$BCO?!! Superzaraza Porzuconych, która w mgnieniu oka rozpuszcza?$B$B$GRozpuściłeś:Rozpuściłaś; mi mojego wrykulskiego więźnia?$B$B<Kapitan wygląda niemal na zasmuconego i spluwa z obrzydzeniem.>$B$BDobra, wiem, co musimy zrobić. A raczej, co TY musisz zrobić!', 0),
(11332, 'plPL', 'Świetna robota, $N, świetna robota!$B$B<Kapitan wydaje się nie posiadać z radości.>$B$BTo oduczy tych nicponi Porzuconych zadzierania z nami!$B$BPowiedziałbym, że $gzasłużyłeś:zasłużyłaś; na coś ze skarbca!', 0),
(11333, 'plPL', 'Nieco zniszczona, ale wciąż się nada.$B$B<Thoralius sięga do sakiewki i wyjmuje jakieś dziwnie wyglądające korzenie.>$B$BTeraz wrzucić je do ognia i wdychać!$B$B<Thoralius wrzuca korzenie do tlącej się kadzielnicy.>$B$B<Thoralius wciąga głęboko powietrze. Jego ciało zaczyna drżeć.>$B$BCo... Co... To niemożliwe... Nie mogę...', 0),
(11343, 'plPL', 'Nie rozumiem. Stworzenia, które $gwidziałeś:widziałaś;, wyglądały jak wrykule, którzy atakują Valgard?', 0),
(11344, 'plPL', 'Ludzkie dzieci zrodzone z wrykulów? I Ymiron kazał zabić całe potomstwo urodzone jako ludzie?$B$B<Thoralius na chwilę milknie.>$B$BJakkolwiek bardzo chciałbym zaprzeczyć temu, co tak wyraźnie mi ukazano, nie potrafię. Nie istnieje żadne wymarłe „brakujące ogniwo” ludzkości, jak sugerowała Liga Odkrywców. To wrykule są brakującym ogniwem. To oni są przodkami ludzkości.', 0),
(11346, 'plPL', '<Poszukiwacz Belvar przegląda księgę run.>$B$BHmm... tyle tu tego. Będę potrzebował trochę czasu, żeby ją przestudiować, a jeśli chcemy zrozumieć te runy, będziemy musieli spróbować zrobić własne.', 0),
(11348, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, pokonując Pętacza Murdisa, ale żelazne krasnoludy tak łatwo się nie poddadzą.$B$BSporo się dowiedzieliśmy o tym, jak posługują się runami. Może przy następnym starciu ta wiedza da nam przewagę.', 0),
(11349, 'plPL', '<Belvar ostrożnie obraca narzędzia w dłoniach.>$B$BZaraz je wypróbuję. Jeśli mamy zrozumieć zamiary żelaznych krasnoludów i ich pokonać, muszę dokładnie wiedzieć, jak działają te runy.', 0),
(11350, 'plPL', '<Goniec przegląda księgę run.>$b$bNie jestem mistrzem wiedzy, ale trochę znam język żelaznych krasnoludów. Myślę, że runy ryte na olbrzymach wywodzą się z ich mowy, choć są pewne różnice.', 0),
(11351, 'plPL', '<Pembe ogląda narzędzia.>$b$bSą delikatniejsze, niż sądziłem. Daj mi chwilę, wypróbuję je.', 0),
(11352, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, pokonując Pętacza Murdisa, ale żelazne krasnoludy tak łatwo się nie poddadzą.$b$bSkoro mój lud wędruje na północ, na pewno znów natkniemy się na żelazne krasnoludy. Następnym razem będziemy gotowi pokrzyżować im szyki, zanim zdążą się okopać.', 0),
(11355, 'plPL', '<Badacz Aderan słucha twojej relacji.>$B$BRuny „północ” i „zachód” powtarzały się wiele razy? To mocno utrwalony rozkaz, by iść w tym kierunku, ale te runy to coś więcej niż napęd. Coś je przyciąga, tylko co?', 0),
(11358, 'plPL', '<Aderan słucha, jak opisujesz swoje odkrycia.>$B$BOczywiście! Ten Megalit musi być kluczem do planów żelaznych krasnoludów. Musimy go zniszczyć, zanim ich plan się ziści!', 0),
(11359, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, powalając Megalita, ale zastanawiają mnie jego ostatnie słowa.$B$BJesteś $gpewien:pewna;, że mówił o Kamiennej Kuźni?$B$BNie znam miejsca o tej nazwie, ale brzmi jak słowo wywodzące się od tytanów. Co żelazne krasnoludy zamierzają z czymś takim zrobić? Trzeba to mieć na oku, $N, bo musimy to znaleźć, zanim plan żelaznych krasnoludów się ziści.', 0),
(11365, 'plPL', '<Mędrzec słucha twojej relacji.>$b$bRuny „północ” i „zachód” powtarzały się raz za razem? Nie znam się dobrze na tych runach, ale takie powtórzenia sugerują silny rozkaz.$b$bTe ryty to jednak coś więcej niż zwykłe wskazówki kierunku. Zdają się ciągnąć olbrzymy ku czemuś, tylko ku czemu?', 0),
(11366, 'plPL', '<Edan słucha, jak opisujesz swoje odkrycia.>$b$bMegalit? Dosłowny zapis z tablicy! Ten Megalit musi być sercem tajemniczych planów żelaznych.', 0),
(11367, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, powalając Megalita, ale zastanawiają mnie jego ostatnie słowa.$b$bJesteś $gpewien:pewna;, że mówił o Kamiennej Kuźni?$b$bNasz lud nie zna tej nazwy, ale brzmi, jakby mogło to być dzieło „tytanów”, o których mówią przybysze. Żelazne krasnoludy zawsze były przebiegłym i groźnym wrogiem, $N. Musimy obserwować te olbrzymy i znaleźć tę Kamienną Kuźnię, zanim zdążą urzeczywistnić swoje plany.', 0),
(11390, 'plPL', 'Dobra robota, choć chyba przydałby ci się kurs przypominający z podstaw pilotażu.$B$BA zresztą, nieważne, każda para rąk się liczy. Masz tu swoją dniówkę.', 0),
(11391, 'plPL', 'Niezłe strzelanie, asie.$B$BTu masz zapłatę. Wracaj jutro na następną rundę, słyszysz?', 0),
(11393, 'plPL', '<Odkrywca rozpromienia się, gdy mówisz mu, kto cię przysyła. Dalej mówi ściszonym głosem.>$B$BIrena się o mnie martwiła? Wiesz, to ma po ojcu.', 0),
(11394, 'plPL', '<Jaren wydaje się bardzo przejęty twoim sukcesem, ale daje ci znak, żeby rozmawiać szeptem.>$b$bŚwietna robota, $N! Tylko masz sporo mazi Plagi na całym ekwipunku. Może pomyśl o szybkiej kąpieli w cieśninie. Woda jest zimna, ale w mig cię doczyści.', 0),
(11395, 'plPL', 'Wiem, co to jest! $N, to urządzenie sterujące tymi kryształami Plagi!$b$bGłowę dam, że da się nim wyłączyć ich pola siłowe. Hmm.$b$b<Odkrywca w zamyśleniu rozważa, co może oznaczać to, że masz to urządzenie.>', 0),
(11396, 'plPL', 'Super!$b$b<Jaren szybko się rozgląda, czy nikt nie zauważył jego okrzyku.>$b$bNo dobra, na pewno $gzasłużyłeś:zasłużyłaś; na wybór jednej z rzeczy, które tu znalazłem.$b$bI, $N, jeśli trafisz z powrotem do Stalowej Bramy, pozdrów ode mnie czule Irenę i powiedz jej, że nic mi nie jest.', 0),
(11397, 'plPL', '<Anastasia przez chwilę rozważa twój sukces.>$b$bRobota bez wątpienia zadowalająca, a jednak coś mi mówi, że powinniśmy zrobić coś jeszcze, żeby pokrzyżować zamiary Plagi na tej plaży.', 0),
(11398, 'plPL', 'Mogę ci powiedzieć, co to jest, $N. To urządzenie sterujące tymi kryształami Plagi tam w dole!$b$bGłowę dam, że da się nim wyłączyć ich pola siłowe. Hmm.$b$b<Aptekarka w zamyśleniu rozważa, co może oznaczać to, że masz to urządzenie.>', 0),
(11399, 'plPL', '<Anastasia odwraca się i uśmiecha do swojego sukkuba.>$b$bNo dobrze, $N, przyznaję, że bez wątpienia $gzasłużyłeś:zasłużyłaś; na wybór jednej z tych rzeczy.', 0),
(11406, 'plPL', 'Więc to kwatermistrz cię przysłał?$B$B<Gil wygląda na uspokojonego.>$B$BSzczerze mówiąc, jesteśmy trochę do tyłu i będziemy potrzebować pomocy, żeby zdążyć ze wszystkim.$B$B<Gil wzdryga się.>$B$BŻaden z ludzi nie chce narazić się na gniew kapitana Adamsa.', 0),
(11410, 'plPL', 'Nareszcie możemy łowić w spokoju! Choć zanim cokolwiek złowimy, przybędzie ekspedycja i wszystko zagarnie dla siebie.$B$BDziękujemy ci, $N. Zaglądaj tu czasem.', 0),
(11411, 'plPL', '<Wódz słucha, jak się przedstawiasz.>$b$bJestem Wódz Popielny Totem, a mój lud to taunka. Powiem ci szczerze, obcy przybyszu: u nas zaufanie się zdobywa, a nie dostaje. Masz moje pozwolenie, by chodzić między nimi i oferować pomoc. Czasu jest coraz mniej i niektórzy mogą przyjąć w przygotowaniach nawet pomoc obcego.', 0),
(11414, 'plPL', 'Zapach ich krwi na twoim pysku mnie cieszy. Bracia nie powinni obracać się przeciw sobie.', 0),
(11415, 'plPL', 'Zapach ich krwi na twoim pysku mnie cieszy. Bracia nie powinni obracać się przeciw sobie.', 0),
(11416, 'plPL', '<Ulfang głośno wyje, gdy dowiaduje się, że $gpokonałeś:pokonałaś; jego wielkiego wroga, orła.>$B$BZaszczyt tego zabicia należy do ciebie. Wolałbym, żeby to moja paszcza w końcu zacisnęła się na jej szyi.$B$BNie zmarnujmy ofiary, którą dla nas złożyła. Masz, zjedz je!', 0),
(11417, 'plPL', '<Ulfang głośno wyje, gdy dowiaduje się, że $gpokonałeś:pokonałaś; jego wielkiego wroga, orła.>$b$bZaszczyt tego zabicia należy do ciebie. Wolałbym, żeby to moja paszcza w końcu zacisnęła się na jej szyi.$b$bNie zmarnujmy ofiary, którą dla nas złożyła. Masz, zjedz je!', 0),
(11418, 'plPL', '$GWidziałeś:Widziałaś; gniazdo z pisklętami? Hmm... czyli nasz „on” to tak naprawdę „ona”, co?$b$bTo chyba wszystko wyjaśnia. Ja też nie chciałbym przenosić gniazda pełnego piskląt tylko dlatego, że pojawił się nowy sąsiad.$b$b<Gil posyła Traperowi Jethanowi udawane gniewne spojrzenie.>$b$bNa pewno świetnie byśmy się dogadywali, gdyby stary Jethan przestał próbować zrobić z niej trofeum.', 0),
(11420, 'plPL', '<Zorek kartkuje instrukcję.>$B$BHmm, ciekawe...$B$BWedług instrukcji wrykule mają specjalne narzędzie, dzięki któremu sterują wyrzutniami harpunów z zabójczą precyzją. Wygląda trochę jak koło sterowe naszych statków. Co więcej, jest przenośne i wkłada się je do wyrzutni jak klucz. Musimy dorwać coś takiego!', 0),
(11421, 'plPL', 'Świetna robota, $N! $GWybiłeś:Wybiłaś; sporą część ich smoczych jeźdźców i porządnie $gwkurzyłeś:wkurzyłaś; ich wodzów.$B$BJesteś $ggotów:gotowa; wrócić do Valgardu i przekazać Zorekowi dobre wieści? Jeśli tak, mam szalony pomysł!', 0),
(11422, 'plPL', '<Gdy Stara Lodowa Płetwa sięga po trójząb syna, jego dłoń lekko drży. Czyżby stary murlok był pogrążony w żałobie?>$b$b<Czy to tylko nadmiar wilgoci zbiera mu się w kąciku oka?>', 0),
(11423, 'plPL', 'To ma ogromną wartość, $N. Muszę ze zdwojoną siłą ratować i tłumaczyć wrykulskie teksty.$b$bNie zrozum mnie źle. Naszych wrogów trzeba zniszczyć... ich pradawnej wiedzy już nie.', 0),
(11424, 'plPL', 'Hmmmmf... na razie wystarczą. Jest w nich coś dziwnego.$b$bMówię ci, od lat mam do czynienia z częściami ciał i jeszcze nigdy nie miałam tak dziwnego uczucia w żołądku. W każdym razie umowa to umowa. Oto twoja zapłata.', 0),
(11426, 'plPL', 'Znakomicie! Te przerośnięte małpy wkrótce się przekonają, co znaczy zadzierać z Przymierzem!', 0),
(11427, 'plPL', '<Porucznik Lodowy Młot odbiera od ciebie mechanizm sterujący harpunem.>$B$BA, przychodzisz z prezentami!', 0),
(11428, 'plPL', 'Serce mi pękło, gdy się dowiedziałam, że opiekunowie obrócili się przeciw nam. Kiedyś uważałyśmy ich za braci i najbliższych przyjaciół.$B$BOpłakuję braci i siostry, których straciliśmy, ale bez twojej pomocy nie byłoby dla nas żadnej nadziei. Zawsze będziesz u nas mile $gwidziany:widziana;, $N.', 0),
(11429, 'plPL', 'Za Przymierze! $GTwardy z ciebie gość:Twarda z ciebie babka;, $N. Dość $gtwardy:twarda;, żeby rozłupać parę wrykulskich czaszek w Nifflevar.', 0),
(11430, 'plPL', 'Trochę potrwa, zanim znajdą następcę Yavusa. To idealna chwila, żeby wprowadzić w życie plan Zoreka! Kiedy oni będą się miotać, żeby odzyskać kontrolę nad Nifflevar, ty użyjesz przeciwko nim ich własnych wyrzutni harpunów!', 0),
(11432, 'plPL', '$GZrobiłeś:Zrobiłaś;, co trzeba było zrobić. Choć niektórzy mogą uznać za niehonorowe zabijanie bezbronnych, w tym przypadku $gbyłbyś głupcem:byłabyś głupia;, postępując inaczej.$B$BA przecież nie mogliśmy ich tak po prostu zostawić, żeby ktoś ich rytualnie obudził, prawda?$B$BTo, co $gzrobiłeś:zrobiłaś; dla nas wszystkich w tych katakumbach, wymagało odwagi, $N.', 0),
(11433, 'plPL', '$GZrobiłeś:Zrobiłaś;, co trzeba było zrobić. Niemądrzy mogą uznać za niehonorowe zabijanie bezbronnych w chwili przebudzenia, ale w tym przypadku $gbyłbyś głupcem:byłabyś głupia;, postępując inaczej.$b$bA przecież nie mogliśmy ich tak po prostu zostawić, żeby ktoś ich rytualnie obudził, prawda?$b$bTo, co $gzrobiłeś:zrobiłaś; dla nas wszystkich w tych katakumbach, wymagało odwagi.', 0),
(11434, 'plPL', 'Daleko razem zajdziemy, $N. Z moją urodą i twoim... zapałem do roboty na pewno zbijemy fortunę.', 0),
(11436, 'plPL', 'Jesteś $gszalony:szalona;, $N! Jaki wariat wystrzeliwuje się z wyrzutni harpunów, żeby się przemieścić?$B$BAle chyba trzeba być trochę $gstukniętym:stukniętą;, żeby dokonać tego, co ty tam na urwiskach! Fantastyczna robota! Doszły nas słuchy, że przywódca Smokołupców, Ingvar, jest wściekły! Może pewnego dnia będziesz $ggotów:gotowa; wdeptać mu twarz w ziemię w imię naszego ukochanego Przymierza.', 0),
(11443, 'plPL', 'Rany! Ale z ciebie $gsprawny gość:sprawna babka;. Tak, no, po prostu daj mi te skrzynie. Muszę je opisać, zinwentaryzować i zrobić jeszcze parę innych rzeczy, których nie nauczono cię robić ani rozumieć. Nie martw się, na pewno powiem Kellerowi, jak świetnie się tu $gspisałeś:spisałaś;! Tak. No, możesz już iść. Zmykaj!', 0),
(11448, 'plPL', '<Stanwad bierze od ciebie tobołek i zaczyna przeglądać dane.>$b$bRany. Ile osób, mówisz, zginęło, żeby zdobyć te informacje?$b$b<Stanwad kręci głową.>$b$bUcieszy cię wiadomość, że McSorf i jego banda niezdarnych głupków odkryli starożytny przepis na gulasz z tundry. Nie zauważył ikon zwykłych warzyw i piktogramu człekokształtnych ust wcinających te warzywa? Do złamania tego kodu nie trzeba żadnego cholernego szyfru!', 0),
(11452, 'plPL', 'Wcale mi się to nie podoba! To, że Król Lisz wykradł Ymirona, oznacza same kłopoty. Szkoda, że nie udało ci się zabić jego razem z królową.$B$BMimo to poważnie $gpokrzyżowałeś:pokrzyżowałaś; im plany i $gkupiłeś:kupiłaś; nam cenny czas, którego potrzebujemy.$B$BA kto wie, skoro tyle podróżujesz, pewnie jeszcze natkniesz się na Króla Ymirona. Jestem pewien, że przy następnym spotkaniu nie wyjdzie na tym tak dobrze.', 0),
(11453, 'plPL', 'Wcale mi się to nie podoba! To, że Król Lisz wykradł Ymirona, oznacza same kłopoty. Szkoda, że nie udało ci się zabić jego razem z królową.$b$bMimo to poważnie $gpokrzyżowałeś:pokrzyżowałaś; im plany i $gkupiłeś:kupiłaś; nam cenny czas, którego potrzebujemy.$b$bA kto wie, skoro tyle podróżujesz, pewnie jeszcze natkniesz się na Króla Ymirona. Jestem pewien, że przy następnym spotkaniu nie wyjdzie na tym tak dobrze.', 0),
(11455, 'plPL', 'Świetna robota! Może to nie tak śmiałe jak łupienie na pełnym morzu, ale niech mnie kaczka kopnie, jeśli przepuszczę taką okazję.', 0),
(11456, 'plPL', 'Dziękuję ci, $N. Mój lud przeżywa czas wielkiej potrzeby.', 0),
(11457, 'plPL', 'Wciąż udowadniasz, że jesteś $gcennym sojusznikiem:cenną sojuszniczką;, $N. Twoje czyny nie zostaną zapomniane.', 0),
(11458, 'plPL', 'Jesteś $ggroźnym sojusznikiem:groźną sojuszniczką;, $N. Mój lud na zawsze pozostanie twoim dłużnikiem.', 0),
(11459, 'plPL', 'Nic nie $gzrozumiałeś:zrozumiałaś; z tego, co mówił Zeh\'gehn? No jasne, że nie.$B$BNo to zobaczmy.', 0),
(11460, 'plPL', 'Tak, $N. Widzę, jak rodzi się więź. Uznała cię za $gswojego pana:swoją panią;.', 0),
(11464, 'plPL', 'Dobra robota. Oto twoja działka, $N. Będzie jeszcze więcej.$B$BNa tej wyspie nie brakuje piratów, którzy nie płacą długów.', 0),
(11465, 'plPL', 'Sprytne bestie. I cierpliwe! Musimy przestać lekceważyć wroga. Ci wrykule to zabójczy łowcy!$b$bTak czy inaczej, misja wykonana. Może czas, żebyś $gzapolował:zapolowała; na coś bardziej nieuchwytnego niż tłusty indyk, co?', 0),
(11466, 'plPL', 'Jestem pod wrażeniem, $N. A niełatwo mi zaimponować.', 0),
(11467, 'plPL', 'Wezmę złoto, bo tyle był mi winien Conrad. Resztę możesz zatrzymać.$B$BJeśli kiedyś będziesz potrzebować czegoś na stałe, na pewno coś załatwię. A tymczasem niech ci wiatr mocno dmie w żagle, $gprzyjacielu:przyjaciółko;.', 0),
(11468, 'plPL', 'Tak, jastrzębie bardzo bronią swojego terytorium i często latają stadami. Chyba mogłem ci to powiedzieć, zanim cię wysłałem w teren.', 0),
(11469, 'plPL', 'Fuj, jak to cuchnie, jeszcze czegoś takiego nie wąchałam!$B$BNo dalej, połóż to tutaj. Rzucę zaklęcie i będzie z tego mydło do szorowania jak nic!', 0),
(11470, 'plPL', 'Brawo, $N! Brawo! Więź między tobą a twoim sokołem jest silna! Może w niedalekiej przyszłości dasz radę przeprowadzić kilka misji zwiadowczych przeciw wrykulom?', 0),
(11471, 'plPL', 'Dni Jonaha Sterlinga wreszcie dobiegły końca! Nigdy nie sądził, że ta „dziewka” da radę.$B$BGdy wieść o śmierci Jonaha rozejdzie się wśród piratów, umocnię swoją władzę. Moja załoga nie będzie już sprawiać kłopotów twoim sojusznikom, $N.', 0),
(11472, 'plPL', 'To dobre wieści! Teraz więcej byków przepłynie przez cieśninę, żeby parzyć się z krowami. Wkrótce na wyspach będzie mnóstwo nowych rafowych szczeniąt.$B$BDziękuję ci. Cokolwiek $gzrobiłeś:zrobiłaś; w przeszłości, wiedz, że $gpomogłeś:pomogłaś; zapewnić przyszłość Kamagua!$B$BMusimy dalej robić swoje, jeśli ich liczebność ma się odbudować. Wróć, proszę, jutro, żebyśmy mogli pomóc kolejnej parze się odnaleźć.', 0),
(11473, 'plPL', 'Patrzaj tu, kamracie. Ty przyjść zobaczyć ja i ja, aj?', 0),
(11474, 'plPL', 'Ponad połowa naszego zespołu nie żyje albo zaginęła, $gmłody:młoda;. To nasza ostatnia reduta, tu na wysokich urwiskach. Te przeklęte żelazne krasnoludy wyparły nas zarówno z Ruiny Ivalda, jak i z Wykopalisk Baelguna. Mam plan, jak wrócić do środka, zanim zakopią wszystkie nasze skarby i stracimy te dane na zawsze.', 0),
(11475, 'plPL', 'Skoro mam już narzędzia, można zaczynać budowę. No, jak tylko będę mieć trochę materiałów. To właśnie mi teraz zdobędziesz.', 0),
(11476, 'plPL', 'Wielkie dzięki, bratku. Rechotek wyglądać fest!', 0),
(11477, 'plPL', 'Dobra robota, $N. To trochę spowolni zasypywanie.', 0),
(11478, 'plPL', 'No, nic, czego byśmy już nie wiedzieli. Przynajmniej Donny jeszcze żyje.', 0),
(11479, 'plPL', 'Smutne wieści. Dan był moim starym kumplem... I był mi winien kasę. Tak czy owak, jeśli współpracował z tymi kundlami z Południowych Mórz, dostał, na co zasłużył.$B$BA co do ciebie, $gprzyjacielu:przyjaciółko;, idziesz w górę. Dosłownie.', 0),
(11480, 'plPL', 'No proszę, proszę. Czyżby to $N? Zjawiasz się na Cyplu Łajdaków, nikt o tobie nie słyszał poza jakimś goblińskim kumplem tego półgłówka Terry\'ego.$B$BPowiedzmy, że jestem nieco... sceptyczna... co do twoich zamiarów.', 0),
(11483, 'plPL', 'Świetnie. Razem z poszyciem zrobi się z tego bezbłędna kopia konstruktów, których używają żelazne krasnoludy.', 0),
(11484, 'plPL', 'Konstrukt będzie gotowy, gdy tylko skończę szkielet.', 0),
(11485, 'plPL', 'Już prawie możesz zabrać to dzieło sztuki w teren, $N!', 0),
(11489, 'plPL', 'Doskonale! Działa jak z nut!', 0),
(11491, 'plPL', '$GPokazałeś:Pokazałaś; mu! Teraz pora wysłać cię w teren.$B$BMam nadzieję, że czujesz się pewnie...', 0),
(11494, 'plPL', 'I znowu Walt dowodzi, że jest najlepszym krasnoludem! I co teraz powiesz o moim konstrukcie, Lebronski?!$B$BDziękuję, $N. Te dane bez wątpienia okażą się bezcenne... jak tylko wymyślę, jak je wyciągnąć z konstruktu.', 0),
(11495, 'plPL', 'Niesamowite! Co knują te żelazne zakały? Co robią na Burzowych Szczytach? I czym jest ten Loken?! Przekażę te informacje do naszej głównej bazy operacyjnej na Smoczych Pustkowiach, $N. Dam im też znać, że twoja pomoc w zdobyciu tych informacji była bezcenna.', 0),
(11501, 'plPL', 'Wspaniale... Jakby nie wystarczyło, że Plaga siedzi nam na wiadomo czym, to teraz musimy się jeszcze użerać z jakimś rozzłoszczonym pradawnym konstruktem tytanów!$B$BMuszę to wszystko przetrawić. Tymczasem jest tu mnóstwo roboty do zrobienia.', 0),
(11504, 'plPL', '<Wąsy Orfusa się jeżą.>$B$BPiraci... Czy ich zepsucie nie zna granic?$B$BMusimy odzyskać skradzione artefakty i zwrócić je do tego przeklętego miejsca, żeby mój lud znów zaznał spokoju.', 0),
(11507, 'plPL', 'Orfus to dobry kiełzar, jeden z naszych najsilniejszych wojowników. Wiedziałem, że nas nie zawiedzie.$B$BPozwól, że zobaczę, co $gprzyniosłeś:przyniosłaś;.', 0),
(11508, 'plPL', 'Arr, kamracie. Grezzix nigdy nie lubił brudzić sobie rąk! Pirackie życie jest dla Grezzixa dobre, byle tylko Grezzix nie musiał nic robić.$B$BWidziałem te artefakty. Właśnie dlatego jestem tutaj, a nie sam na Cyplu Łajdaków! Złe, bardzo złe to rzeczy...$B$BAle hej, to twoje życie, nie? Chcesz się dostać na Cypel Łajdaków, a Grezzix może pomóc.', 0),
(11509, 'plPL', '<Harry unosi brew, patrząc na ciebie.>$B$BCzyli jesteś jak ja, co? Trochę $gekscentryczny:ekscentryczna;.$B$B<Harry szepcze.>$B$BNikt się tu tak nie ubiera.$B$BCo do tych artefaktów... Każdy, kto miał z tym do czynienia, skończył martwy, zaginiony albo jedno i drugie.$B$BJeśli nadal chcesz się czegoś dowiedzieć, mogę pomóc, ale to będzie kosztować.$B$B<Harry puszcza oko.>$B$BTy podrapiesz mnie po plecach, a ja postaram się nie wbić ci w nie sztyletu.', 0),
(11510, 'plPL', '<Harry bierze od ciebie kryształ i delikatnie go głaszcze.>$B$BMój skarbie! Czy ten wielki, zły wieloryb zrobił ci krzywdę? Już dobrze. Już nigdy nie spuszczę cię z oczu!$B$B<Harry podnosi na ciebie wzrok.>$B$BTo na czym stanęliśmy?', 0),
(11511, 'plPL', 'Musimy zwrócić wszystkie artefakty, $N. Gdy zbierzemy wszystkie cztery, złożysz je z powrotem w ich grobach.', 0),
(11512, 'plPL', 'Musimy zwrócić wszystkie artefakty, $N. Gdy zbierzemy wszystkie cztery, złożysz je z powrotem w ich grobach.', 0),
(11519, 'plPL', 'Arrr, ja i moja załoga zwinęliśmy tę tarczę! Próbujem ją odzyskać od tego nicponia, szczura lądowego, Sorlofa! $GPrzyszedłeś:Przyszłaś; pomóc, arrr?$B$BJak widzisz, załogę mamy w szkieletowym składzie!$B$B<Kapitan Ellis wybucha śmiechem.>$B$BSiostrze Miłosierdzie potrzeba jeszcze kogoś od prochu do obsługi wielkich dział na rufówce. Myślisz, że dasz radę, kamracie?$B$BPomóż mojej załodze wykończyć Sorlofa, a podzielimy się łupem! Ty weźmiesz tarczę, a ja i załoga resztę!', 0),
(11527, 'plPL', 'Oby te zdradzieckie szczury zęzowe dostały nauczkę! A teraz pora obsadzić wielkie działo, kamracie!', 0),
(11529, 'plPL', 'Umowa to umowa, kamracie!', 0),
(11530, 'plPL', 'Musimy zwrócić wszystkie artefakty, $N. Gdy zbierzemy wszystkie cztery, złożysz je z powrotem w ich grobach.', 0),
(11567, 'plPL', 'Musimy zwrócić wszystkie artefakty, $N. Gdy zbierzemy wszystkie cztery, złożysz je z powrotem w ich grobach.', 0),
(11568, 'plPL', 'Ponure wieści, $N. Mój lud jest w niebezpieczeństwie i trzeba go ostrzec. Te morskie wynaturzenia nie okażą Kalu\'ak litości.', 0),
(11572, 'plPL', 'Kalu\'ak dziękują ci za wszystko, co $gzrobiłeś:zrobiłaś;, $N. Teraz musimy przygotować się do bitwy i ostrzec naszych braci i siostry za morzem przed tym, co nadchodzi.$B$BOby nie było za późno...', 0),
(11573, 'plPL', 'Tępokieł żyje? Przynajmniej jakaś dobra wiadomość tego dnia...', 0),
(12118, 'plPL', 'Co mówisz? Przysyła cię Anuniaq?$B$BDobrze, dobrze... jest mnóstwo roboty. Przyda się każda pomoc!', 0),
(12181, 'plPL', 'Eee, no, możesz sobie zatrzymać tę fiolkę, $gprzyjacielu:przyjaciółko;. Ufam ci.', 0),
(12182, 'plPL', 'Och, cóż za radosny dzień! I patrz, tuż za górą na północnym wschodzie pełznie całe pole Plagi, które możemy unicestwić!', 0),
(12297, 'plPL', '<Greer podnosi okulary na czubek głowy i czyta wiadomość, a gdy kończy, spogląda na ciebie z zaciekawieniem.>$B$BDostaniesz mojego najszybszego gryfa! Te informacje trzeba natychmiast dostarczyć Wielkiemu komendantowi Zmorze Żmijów!', 0),
(12298, 'plPL', '<Wielki komendant czyta wiadomość, po czym ją zgniata.>$B$BWiesz, gdzie teraz są ludzie z tej listy? Wyjrzyj na zewnątrz, przy głównej bramie. To ci, którzy wiszą na łukach.$B$BPrzynęta na ghule...', 0),
(12481, 'plPL', 'Dobra robota. Biedny frajer w ogóle się tego nie spodziewał.', 0),
(12482, 'plPL', 'Świetna robota, $N. Gdy przybędą nasze siły z Przystani Zemsty, rozprawimy się z pozostałymi wrykulami.', 0),
(12566, 'plPL', 'Czyli Nanik jednak znalazł pomoc? Powiedz mi, $N, jak to się stało, że $gdotarłeś:dotarłaś; tu bez niego? Nikt nie zna tej ziemi lepiej niż taunka.', 0),
(12918, 'plPL', 'Idealnie nadają się do uzupełnienia moich zapasów. Nie tylko nauczę cię sztuki doskonałego szlifowania klejnotów, ale też oszlifowałem jeden z nich do doskonałej postaci i możesz go wziąć w nagrodę.', 0),
(12952, 'plPL', 'Muszą wystarczyć. Mogę nauczyć cię sztuki doskonałego szlifowania klejnotów i dać ci dowód moich umiejętności.', 0),
(13087, 'plPL', 'Masz moje mięso! Tu jest twój przepis, a ja mam co gotować!', 0),
(13089, 'plPL', 'Szybko przerobimy to mięso na gulasz.', 0),
(13205, 'plPL', '<Mordun gwiżdże.>$b$bNo popatrz tylko na nie! Niesamowite.$b$bSpodziewałem się po trosze, że te neandertalczyki machają maczugami i rzucają kamieniami.$b$bNic z tego...', 0),
(13206, 'plPL', 'Marrah powiadomiła nas o wyższości wrykulskiego oręża. Przyjrzymy się tej broni i zobaczymy, czy czegoś się z niej nauczymy.$b$bWeź to za fatygę, $N.', 0),
(13268, 'plPL', 'Wróć, gdy będziesz mieć odpowiednią umiejętność, a zapewnię ci całe szkolenie krawieckie.', 0),
(13444, 'plPL', 'Zbezcześć wielkie ognisko Przymierza w Wyjącym Fiordzie!', 0),
(13453, 'plPL', 'Zbezcześć wielkie ognisko Hordy w Wyjącym Fiordzie!', 0),
(13488, 'plPL', 'Uczcij płomień Wyjącego Fiordu!', 0),
(13496, 'plPL', 'Uczcij płomień Wyjącego Fiordu!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(11153, 'plPL', 'Znowu rozmawiamy, co? To znaczy, że ci się udało! $GPokazałeś:Pokazałaś; tym zgniłym piratom z Morza Północnego, gdzie raki zimują!$b$bPrawda?', 0),
(11154, 'plPL', 'Proszę, powiedz, że masz guano ciemnoszponych nietoperzy?!', 0),
(11155, 'plPL', 'Nie ma nic wyśmienitszego niż delikatne mięso wycięte z boku łopatokła!', 0),
(11157, 'plPL', 'Jak idą twoje starania?', 0),
(11167, 'plPL', '$GZdobyłeś:Zdobyłaś; pojemniki, $n?', 0),
(11168, 'plPL', '$GZdobyłeś:Zdobyłaś; gruczoły toksyn, których szukam, $n?', 0),
(11170, 'plPL', '$GWróciłeś:Wróciłaś;!', 0),
(11182, 'plPL', 'Jak idą twoje zmagania z tymi wścibskimi treserami, maleństwo?', 0),
(11188, 'plPL', 'Szkoda, że kapitan kazał ci rozjuszyć protosmokowce. Choć zdają się nie dorównywać inteligencją niektórym znanym nam smokom, wciąż wydają się szlachetnymi stworzeniami. Nie wspominając już o położeniu, w jakim nas to stawia.$B$BCzy śmiem zapytać, czy $guporałeś:uporałaś; się z tą sytuacją?', 0),
(11190, 'plPL', 'Niebezpiecznie kończą nam się pociski, $N. Naszym wrogom trza przyłożyć, zwłaszcza w Skorn!$B$BMasz dla nas więcej kul?', 0),
(11202, 'plPL', 'Stąd trudno dokładnie zobaczyć, co się tam dzieje. $GZdołałeś:Zdołałaś; podpalić te zbiorniki z zarazą?', 0),
(11218, 'plPL', 'Budowa tego miejsca to chyba niekończąca się historia. Mam tylko nadzieję, że zdołasz zdobyć to, czego potrzebujemy, żeby ją kontynuować.', 0),
(11221, 'plPL', '$GWróciłeś:Wróciłaś; z meldunkiem, $n?', 0),
(11224, 'plPL', 'To dla nas poważny cios. Nawet nie chcę wiedzieć, co tam odkryli.$B$BSamo wyobrażanie sobie, co to mogło być, nie daje mi spać po nocach.', 0),
(11227, 'plPL', '$GNakarmiłeś:Nakarmiłaś; już tego małego łobuza?', 0),
(11231, 'plPL', 'Gdy więźniowie z Gjalerbron zostaną uwolnieni, wrykule nie będą mogli dalej odprawiać swoich bezbożnych obrzędów.$B$BJesteś naszą jedyną nadzieją, by ich powstrzymać.', 0),
(11232, 'plPL', 'Działa, $n. Czy ktoś w końcu się nimi zajmie?', 0),
(11233, 'plPL', 'Czy przywódcy Przymierza nie żyją, $N? Nie wracaj, dopóki nie zginą.', 0),
(11236, 'plPL', 'Na pewno $gzabiłeś:zabiłaś; Mezhena i jego nekrowładców, $N?', 0),
(11237, 'plPL', 'Co?! Plany ataku na twierdzę?$B$BŻMIJ MROZU?!!!', 0),
(11238, 'plPL', 'Czy atak został udaremniony? Czy żmij mrozu i jego pan zostali zniszczeni?$B$B$GOdzyskałeś:Odzyskałaś; róg?', 0),
(11239, 'plPL', 'Święta Światłość działa przez twoje czyny i we wszystkim.$B$BŻadne stworzenie, żadne miejsce, nieważne jak nikczemne, nie ujdzie jej gniewowi!', 0),
(11243, 'plPL', 'Losy świata mogą spoczywać w naszych rękach.', 0),
(11244, 'plPL', 'Znajdź tych zwiadowców!', 0),
(11245, 'plPL', 'Podejście zbyt blisko do tych wież to pewna śmierć, dopóki są tam na górze ci rzucający zaklęcia.', 0),
(11246, 'plPL', 'Jednego jestem pewien: nie chcę widzieć, jak któryś z tych olbrzymów wstaje, kiedy już go powalimy!', 0),
(11247, 'plPL', 'Czy mogę zasugerować, żebyśmy po podpaleniu budynków nie marudzili w nich zbyt długo?', 0),
(11249, 'plPL', 'Tak? W czym mogę ci pomóc, moje dziecko?', 0),
(11250, 'plPL', 'Skoro tu jesteś, rozumiem, że Skorn już nie ma?', 0),
(11252, 'plPL', 'Dobrze widzieć cię w dobrym zdrowiu, $n.$b$bMamy już tylu rannych i zabitych, ile jesteśmy w stanie znieść.', 0),
(11254, 'plPL', 'Masz mi coś do pokazania, $N?', 0),
(11255, 'plPL', 'Przyłóż się do tego, $n! Tu chodzi o życie ludzi!', 0),
(11257, 'plPL', 'Ci wrykule mają dziwne zwyczaje, nie sądzisz, $n?', 0),
(11258, 'plPL', 'Proponuję, żebyśmy po podpaleniu budynków nie zostawali w środku. Duch ognia nie oszczędzi nas w swoim pragnieniu niszczenia.', 0),
(11259, 'plPL', 'Podejście zbyt blisko do tych wież to pewna śmierć, dopóki są tam na górze ci rzucający zaklęcia.', 0),
(11260, 'plPL', 'Tak? W czym mogę ci pomóc, dziecko?', 0),
(11261, 'plPL', 'Jakie wieści przynosisz ze Skorn, $n?', 0),
(11262, 'plPL', 'Szykuj się.$b$bJest mnóstwo roboty. To dopiero, że tak powiem, wierzchołek góry lodowej.', 0),
(11263, 'plPL', 'Jak idzie walka w Gjalerbron?', 0),
(11265, 'plPL', 'Gdy więźniowie z Gjalerbron zostaną uwolnieni, wrykule nie będą mogli dalej odprawiać swoich rytuałów.', 0),
(11266, 'plPL', 'Co?! Plany ataku na nasz obóz?$b$bPRZEZ WIELKIEGO ŻMIJA Z NIEBA?!!!', 0),
(11267, 'plPL', 'Czy atak został udaremniony? Czy wielki żmij śmierci i jego pan zostali zniszczeni?$b$b$GOdzyskałeś:Odzyskałaś; róg?', 0),
(11268, 'plPL', 'Czy $gzniszczyłeś:zniszczyłaś; żywe trupy w Gjalerbron?', 0),
(11269, 'plPL', '$GPrzyniosłeś:Przyniosłaś; trochę tego puchu? Naprawdę by mi się przydał...', 0),
(11270, 'plPL', 'Nie obchodzi mnie, ile olbrzymów, smoków czy koboldów $gzabiłeś:zabiłaś; wcześniej. Wykonaj to zadanie i wróć, kiedy skończysz.', 0),
(11271, 'plPL', '$GZebrałeś:Zebrałaś; trochę puchu?', 0),
(11272, 'plPL', 'Dobrze cię znowu widzieć, $n. Chyba że jeszcze nie $gzabiłeś:zabiłaś; tego elfiego wynaturzenia – w takim razie na twoim miejscu bym się pospieszył.', 0),
(11275, 'plPL', '$GPrzyniosłeś:Przyniosłaś; jakieś odpowiednie rogi?', 0),
(11277, 'plPL', 'Przeszukaj każdy kąt i zakamarek!', 0),
(11278, 'plPL', '$GWróciłeś:Wróciłaś;!', 0),
(11279, 'plPL', 'Jak bez tych próbek mam ustalić, czy ten najnowszy szczep zarazy da się rozszerzyć na wszelkiego rodzaju stworzenia?', 0),
(11280, 'plPL', 'No, mów! Czy nasz mały eksperyment się udał?$B$BCzy protosmokowcowi smakowała przekąska? Rozpuścił się od środka?', 0),
(11281, 'plPL', 'Udało ci się wypróbować ten róg?', 0),
(11282, 'plPL', 'Ty zabić te wrykule? Oni twardzi jak skała!', 0),
(11283, 'plPL', 'Ty już skończyć zabijanie? Miasto Zimowego Skornu zaraz naprzeciwko!', 0),
(11285, 'plPL', 'Ty już spalić wszystko? Uważaj, żeby nic nie zostać niespalone.', 0),
(11286, 'plPL', 'Ile artefaktów $gzdołałeś:zdołałaś; zebrać z tej Stalowej Bramy?', 0),
(11288, 'plPL', '<Ares jest nieprzytomny.>', 0),
(11289, 'plPL', 'Na Światłość!', 0),
(11290, 'plPL', '$GOdzyskałeś:Odzyskałaś; plany bitewne Smokołupców?', 0),
(11291, 'plPL', 'Valgard nie padł? To niespodzianka.$B$BTo pewnie dzięki twojej pomocy. Na pewno nie dzięki Kellerowi.', 0),
(11292, 'plPL', 'Mam nadzieję, że nie wracasz z pustymi rękami. Myślałem, że się umówiliśmy.', 0),
(11296, 'plPL', 'Wciąż mam nadzieję, że moi łowcy żyją.$B$BŻądło wdów zabija powoli. Lubią utrzymywać ofiary przy życiu na tyle długo, by ich młode mogły się nimi obżerać po wykluciu.', 0),
(11298, 'plPL', '$GZdobyłeś:Zdobyłaś; te beczułki czy nie?', 0),
(11300, 'plPL', 'Daegarn? Szyfr?', 0),
(11301, 'plPL', '$GZdobyłeś:Zdobyłaś; te mózgi? Jeśli nie, chcę z powrotem moją piłę. Lepiej nie próbuj się z nią ulotnić.', 0),
(11305, 'plPL', '$GZdobyłeś:Zdobyłaś; próbkę, której potrzebuję, $n?', 0),
(11306, 'plPL', 'Jak idzie twój eksperyment, $n? Daj znać, jeśli masz jakieś pytania dotyczące nauki, która za tym stoi!', 0),
(11309, 'plPL', 'Masz już moje części?', 0),
(11310, 'plPL', '$GSkończyłeś:Skończyłaś; sprzątanie w Halgrind?', 0),
(11311, 'plPL', '$GPrzetrzebiłeś:Przetrzebiłaś; żywiołaki?', 0),
(11313, 'plPL', '$GOdzyskałeś:Odzyskałaś; jakieś rdzenie?', 0),
(11314, 'plPL', '$GZdołałeś:Zdołałaś; uzdrowić wisiorem którąś z moich sióstr?', 0),
(11315, 'plPL', '$GWróciłeś:Wróciłaś; z Tętniącej Polany?', 0),
(11316, 'plPL', '$GWidziałeś:Widziałaś; na własne oczy okropności Pokręconej Polany?', 0),
(11317, 'plPL', '$GOdnalazłeś:Odnalazłaś; wewnętrzny spokój przy kapliczce? Czy twój zamęt zniknął?', 0),
(11319, 'plPL', 'Pokręcona Polana to straszne miejsce. Nigdy nie sądziłam, że nasze domy mogą stać się czymś tak odrażającym.', 0),
(11322, 'plPL', '$GOdnalazłeś:Odnalazłaś; wewnętrzny spokój przy kapliczce? Czy twój zamęt zniknął?', 0),
(11324, 'plPL', '$n, $gwróciłeś:wróciłaś;. Jakie wieści o Ulfangu?', 0),
(11326, 'plPL', '$N, $gwróciłeś:wróciłaś;. Jakie wieści o Ulfangu?', 0),
(11327, 'plPL', 'To miejsce wygląda jak koszmar. Wrykule czy nie, nikt nie zasługuje na to, by paść ofiarą Królewskich Zakładów Chemicznych.$B$BDobrze, że stoję sobie bezpiecznie tutaj. $GZnalazłeś:Znalazłaś; już tę paczkę?', 0),
(11328, 'plPL', 'No, czego chceszsz ...hik?', 0),
(11329, 'plPL', 'Wyglądasz, jakbyś wciąż $gbył:była; w jednym kawałku. $GZdobyłeś:Zdobyłaś; trochę tej przynęty?', 0),
(11332, 'plPL', 'Zbiorniki z zarazą już zniszczone? Ta nowa zaraza wisi nad naszymi głowami jak pewna śmierć, $N!', 0),
(11333, 'plPL', '$GZnalazłeś:Znalazłaś; moją sakiewkę na składniki?', 0),
(11346, 'plPL', '$GOdzyskałeś:Odzyskałaś; księgę?', 0),
(11348, 'plPL', '$GWypróbowałeś:Wypróbowałaś; już runę?', 0),
(11349, 'plPL', '$GWróciłeś:Wróciłaś; z narzędziami?', 0),
(11350, 'plPL', '$GOdzyskałeś:Odzyskałaś; księgę?', 0),
(11351, 'plPL', '$GWróciłeś:Wróciłaś; z narzędziami?', 0),
(11352, 'plPL', '$GWypróbowałeś:Wypróbowałaś; już runę?', 0),
(11355, 'plPL', 'Co $godkryłeś:odkryłaś;?', 0),
(11358, 'plPL', '$GOdkryłeś:Odkryłaś;, jaki magnes przyciąga olbrzymy?', 0),
(11359, 'plPL', 'Przynosisz wieści o upadku Megalita?', 0),
(11365, 'plPL', 'Co $godkryłeś:odkryłaś;?', 0),
(11366, 'plPL', '$GOdkryłeś:Odkryłaś;, jaki magnes przyciąga olbrzymy?', 0),
(11367, 'plPL', 'Przynosisz wieści o upadku Megalita?', 0),
(11390, 'plPL', 'Hę? $GSkończyłeś:Skończyłaś; już z tym całym dźwiganiem?', 0),
(11391, 'plPL', 'Gargulce?! Widziałem je tam! $GZałatwiłeś:Załatwiłaś; wszystkie?$B$BDo czego ten świat zmierza, skoro krasnolud nie może nawet spokojnie kopać, żeby go ktoś nie napadł.', 0),
(11394, 'plPL', 'Sam nie wiem, $N, chyba nie $gzniszczyłeś:zniszczyłaś; ich jeszcze dość.', 0),
(11395, 'plPL', 'Dziwnie wygląda to urządzenie, które masz, $N. Pozwól, że mu się przyjrzę.', 0),
(11396, 'plPL', 'Sam nie wiem, $n. Chyba musisz rozwalić jeszcze kilka tych rzeczy.', 0),
(11397, 'plPL', 'Ciekawe, kiedy ostatnio patrzyłam, nie wyglądało na to, żebyś $gzniszczył:zniszczyła; ich już dość. Może zdwoisz wysiłki?', 0),
(11398, 'plPL', 'Co tam masz, $N? Pokaż mi to z bliska!', 0),
(11399, 'plPL', 'Wciąż nie $gzniszczyłeś:zniszczyłaś; dość kryształów Plagi. Dopóki tego nie zrobisz, nie ma nagrody.', 0),
(11410, 'plPL', 'Aż mnie świerzbi, żeby wypróbować nową przynętę.$b$bUdało ci się coś z Mroźną Płetwą?', 0),
(11415, 'plPL', '<Z gardła Ulfanga dobywa się niski warkot.>$B$BBjomolf i Varg nie są martwi!', 0),
(11416, 'plPL', 'Masz oczy orła?', 0),
(11417, 'plPL', 'Masz oczy orła?', 0),
(11418, 'plPL', 'Amulet Aderana zadziałał?', 0),
(11420, 'plPL', '$GZnalazłeś:Znalazłaś; instrukcję?', 0),
(11421, 'plPL', 'Czaszka Żmija stoi w płomieniach?', 0),
(11422, 'plPL', '<Jedno z martwych, rybich oczu Starej Lodowej Płetwy przygląda ci się uważnie, wyraźnie wypatrując trójzębu jego syna.>', 0),
(11423, 'plPL', 'Zwoje, $n? $GZdobyłeś:Zdobyłaś; je?', 0),
(11424, 'plPL', 'No to masz moje kości?', 0),
(11426, 'plPL', '$GZnalazłeś:Znalazłaś; mechanizm?', 0),
(11427, 'plPL', 'A to co? Wyglądam na niańkę?', 0),
(11428, 'plPL', '$GUwolniłeś:Uwolniłaś; Pokręconą Polanę od Opiekuna Zwiędłego Liścia?', 0),
(11429, 'plPL', 'Jak widzę, wciąż żyjesz. Najwyraźniej za mało się starasz.', 0),
(11432, 'plPL', '$N, trudno mi uwierzyć, że $grozprawiłeś:rozprawiłaś; się już z dostateczną liczbą uśpionych wrykuli. Wróć, gdy to zrobisz.', 0),
(11433, 'plPL', 'Trudno mi uwierzyć, że $grozprawiłeś:rozprawiłaś; się już z dostateczną liczbą uśpionych wrykuli. Wróć, gdy to zrobisz.', 0),
(11434, 'plPL', '$GZdobyłeś:Zdobyłaś; moje relikty, $N? Nikt w tym życiu nie zajdzie daleko na samej urodzie... nawet ja!', 0),
(11436, 'plPL', '<Zorek unosi brew, patrząc na ciebie.>', 0),
(11443, 'plPL', '$GZnalazłeś:Znalazłaś; te zapasy?', 0),
(11448, 'plPL', '<Stanwad burczy pod nosem.>', 0),
(11452, 'plPL', '$n, z jakimi wieściami przychodzisz?', 0),
(11453, 'plPL', '$n, z jakimi wieściami przychodzisz?', 0),
(11455, 'plPL', 'Masz dla mnie piżmo niedźwiedzia, kamracie?', 0),
(11456, 'plPL', '$GZdobyłeś:Zdobyłaś; mięso, którego potrzebujemy?', 0),
(11457, 'plPL', 'Dobrze cię znowu widzieć.', 0),
(11460, 'plPL', 'To ważne ćwiczenie, $n. Jeśli masz zostać $gsokolnikiem:sokolniczką;, musisz się nauczyć karmić swojego ptaka.', 0),
(11464, 'plPL', '$GWróciłeś:Wróciłaś;. Masz to, co mi się należy?', 0),
(11465, 'plPL', 'Twój sokół musi być stale karmiony, inaczej zje zdobycz, którą posyłasz go upolować.', 0),
(11466, 'plPL', 'Masz to, co moje, $N?', 0),
(11467, 'plPL', '$GZnalazłeś:Znalazłaś; skarb, $N?', 0),
(11468, 'plPL', 'Twój sokół musi być stale karmiony, inaczej zje zdobycz, którą posyłasz go upolować.', 0),
(11469, 'plPL', 'Gdzie ten tłuszcz? I nie próbuj mi wmawiać, że on go nie ma.$B$BTen Wielki Roy jest tak cholernie wielki, że to cud, że w ogóle jeszcze może się toczyć!', 0),
(11470, 'plPL', 'Teraz ty masz kontrolę, $n. Prowadź sokoła i przynieś mi te jaja.', 0),
(11471, 'plPL', 'No i jak, $N? Masz lunetę Jonaha?$B$BNie mogę uwierzyć ci na słowo w sprawie zabójstwa, wiesz? W końcu jestem piratką.', 0),
(11475, 'plPL', 'Krok 1: Przynieś Waltowi jego narzędzia.', 0),
(11476, 'plPL', 'Masz rechotka i kozika, mon?', 0),
(11478, 'plPL', 'Wieści od Donny\'ego?', 0),
(11483, 'plPL', 'Masz materiały na konstrukcję?', 0),
(11484, 'plPL', 'W mig wrócimy do zbierania naszych reliktów!', 0),
(11485, 'plPL', 'Nie daj sobie pyskować tym malkontentom!', 0),
(11491, 'plPL', 'Nie przejmuj się nim, $n. Przejdzie mu...', 0),
(11504, 'plPL', 'Kiełzarowie potrzebują twojej pomocy!', 0),
(11507, 'plPL', 'Wieści od Orfusa?', 0),
(11510, 'plPL', '$GZgubiłeś:Zgubiłaś; się?', 0),
(11511, 'plPL', 'Masz kostur?', 0),
(11512, 'plPL', 'Za... Zamarznięte serce Isuldofa?', 0),
(11527, 'plPL', 'Wszędzie zbuntowane wilki morskie i olbrzymy!', 0),
(11529, 'plPL', 'Żwawo, kamracie!', 0),
(11567, 'plPL', '$GZnalazłeś:Znalazłaś; zbroję?', 0),
(11568, 'plPL', 'Zrobione? Duchy zaznały spokoju?', 0),
(12174, 'plPL', 'Co tam masz, $gżołnierzu:żołnierko;?', 0),
(12181, 'plPL', 'Przesyłka wysoce zabójczego trującego gazu do Jadozłości? Zapraszam!', 0),
(12182, 'plPL', 'To ty jesteś $gtym dostawcą:tą dostawczynią;?', 0),
(12297, 'plPL', 'Witaj, $N.', 0),
(12298, 'plPL', 'Co tam masz, $gżołnierzu:żołnierko;?', 0),
(12481, 'plPL', 'Praca skrytobójcy nie jest tak efektowna, jak się wydaje.', 0),
(12918, 'plPL', 'Bardzo hojnie z twojej strony. Najmniej, co mogę zrobić, to nauczyć cię Doskonałości klejnotów.', 0),
(12952, 'plPL', 'Wystarczą. Nauczę cię Doskonałości klejnotów.', 0),
(13087, 'plPL', 'GDZIE MOJE MIĘSO!', 0),
(13089, 'plPL', 'Gulasz czeka...', 0),
(13130, 'plPL', '$GZgubiłeś:Zgubiłaś; się?', 0),
(13205, 'plPL', '$GZwędziłeś:Zwędziłaś; kupę tych wrykulskich toporów?', 0),
(13206, 'plPL', 'Co tam masz, $N?', 0),
(13268, 'plPL', 'Wyglądasz na kogoś, kto zna się na igle i nitce, więc może zdołam ci pomóc.$B$BPółnocne istoty humanoidalne noszą ubrania, które można szybko przerobić na tkaninę, jeśli się wie jak.$B$BZa kilka sztuk złota nauczę cię sztuki Zbierania tkanin, dzięki której zdobędziesz więcej tkaniny z humanoidów Północnej Grani.', 0);
