INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(11667, 'plPL', 'Stąpaj ostrożnie, wędrowcze.$b$bTe zwłoki to wszystko, co zostało z moich najlepszych ludzi.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(23557, 6, 0, 'plPL', 'Coście za jedni? Zlaliście się ze strachu...'),
(24178, 0, 0, 'plPL', '%s budzi się, zwęszywszy świeże mięso!'),
(24198, 0, 0, 'plPL', '%s traci panowanie nad sobą i atakuje zarówno wrogów, jak i sojuszników!'),
(27992, 1, 0, 'plPL', 'Bezpośrednie trafienie w Dom przy przystani! Obrońcy Smokołupców zostali zaalarmowani!'),
(27992, 2, 0, 'plPL', 'Wrykulski magazyn stoi w płomieniach! Obrońcy Smokołupców zostali zaalarmowani!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(17911, 'plPL', 'Ognia!', '', 0),
(22250, 'plPL', '', 'Ojej, pozwól, że zmienię ci te bandaże!', 0),
(22251, 'plPL', '', 'To powinno nieco spowolnić zakażenie.', 0),
(22295, 'plPL', '', 'Nigdy nie zaznałam takiego zimna, wędrowcze. Nawet tam, gdzie nie ma lodu i śniegu, zmarznięte pustkowia Północnej Grani dają się mocno we znaki.', 0),
(22297, 'plPL', 'Hej, wyglądasz znajomo. Czy myśmy się już spotkali?', '', 0),
(22299, 'plPL', 'Dam ci dobrą radę: nigdy nie ufaj gnomom.', '', 0),
(22300, 'plPL', 'Potrzebuję czegoś mocniejszego, Coot.', 'Potrzebuję czegoś mocniejszego, Coot.', 0),
(22302, 'plPL', 'Jak dorosnę, chcę być stajennym!', '', 0),
(22304, 'plPL', '', 'Ta karczma powstała, zanim przebudzili się dzicy z północy. Chwała choć za to Światłości!$B$BZostaniesz na dłużej?', 0),
(22305, 'plPL', 'Chcę obejrzeć twoje towary, Hazel.', 'Chcę obejrzeć twoje towary, Hazel.', 0),
(22307, 'plPL', 'Handel *hik* truciznami i alko... *hik* gorzałą to niebeshpieczna shprawa...', '', 0),
(22308, 'plPL', 'Potrzebuję kilku składników, Sorely.', 'Potrzebuję kilku składników, Sorely.', 0),
(22330, 'plPL', 'Cześć! Te nicponie, piraci w zatoce, trzymają nas w blokadzie! Pomożesz nam, zrzucając na nich kilka bomb?!$B$BNasz zdobyczny zeppelin będzie tu za niecałe $3078w min. Pilnuj, żeby być na pokładzie, kiedy odleci!', '', 0),
(22331, 'plPL', 'Cześć! Te nicponie, piraci w zatoce, trzymają nas w blokadzie! Pomożesz nam, zrzucając na nich kilka bomb?!$B$BNasz zdobyczny zeppelin zaraz tu będzie... chyba już go słyszę. Pilnuj, żeby być na pokładzie, kiedy odleci!', '', 0),
(22333, 'plPL', 'Jestem więźniem!$B$BZestrzelili mnie z nieba razem z moim pięknym zeppelinem. I za co? Za to, że woziłem ludzi i sprzęt dla Hordy? To żadna nowość!$B$BA teraz każą mi nim krążyć w kółko nad zatoką, żeby mogli bombardować piratów. Nie mam części, żeby go tak eksploatować! Ledwo trzyma się kupy na ślinę i drut!$B$BNie biorę odpowiedzialności za to, co ci się stanie, ale równie dobrze możesz wsiąść, zanim odleci.$B$BTo zbrodnia, mówię ci!', '', 0),
(22334, 'plPL', 'Jestem więźniem!$B$BZestrzelili mnie z nieba razem z moim pięknym zeppelinem. I za co? Za to, że woziłem ludzi i sprzęt dla Hordy? To żadna nowość!$B$BA teraz każą mi nim krążyć w kółko nad zatoką, żeby mogli bombardować piratów. Nie mam części, żeby go tak eksploatować! Ledwo trzyma się kupy na ślinę i drut!$B$BJeśli koniecznie chcesz im pomóc, wróci do portu za niecałą minutę.$B$BTo zbrodnia, mówię ci!', '', 0),
(22335, 'plPL', 'Jestem więźniem!$B$BZestrzelili mnie z nieba razem z moim pięknym zeppelinem. I za co? Za to, że woziłem ludzi i sprzęt dla Hordy? To żadna nowość!$B$BA teraz każą mi nim krążyć w kółko nad zatoką, żeby mogli bombardować piratów. Nie mam części, żeby go tak eksploatować! Ledwo trzyma się kupy na ślinę i drut!$B$BJeśli koniecznie chcesz im pomóc, wróci do portu za niecałe $3078w min.$B$BTo zbrodnia, mówię ci!', '', 0),
(22336, 'plPL', 'Mój zeppelin przybił do przystani. Choć jestem w niewoli, a on sam w opłakanym stanie, za dwie minuty znów odleci.', '', 0),
(22337, 'plPL', 'Zeppelin wyrusza na rundę nad zatoką za niecałą minutę! A, i gdyby ktoś miał ochotę mnie uwolnić, jestem na przystani.', '', 0),
(22367, 'plPL', 'Dniami i nocami tylko tu siedzę, robię amunicję i naciągam cięciwy kusz.$B$BPewnie też chcesz, żebym coś dla ciebie zrobił?', '', 0),
(22375, 'plPL', 'Od niezliczonych lat płoną te lasy. Podsyca je pradawna magia, a są one godowiskiem matki miotu i jej protosmokowców-małżonków.$B$BLecz teraz przebudziło się dawno zapomniane zło i znów pragnie zniewolić potomstwo matki miotu dla własnych celów.$B$BTe wrykule wywołały zamęt, przez który granice lęgowiska się poszerzają, a to zagraża twojemu ludowi.', '', 0),
(22380, 'plPL', '', 'Nie przerywać ostrzału! Odciąć im posiłki!', 0),
(22381, 'plPL', '', 'Ogień osłonowy, już!', 0),
(22382, 'plPL', '', 'Nie dajcie im połączyć się z głównymi siłami!', 0),
(22403, 'plPL', 'Ostatnie dziesięć szczepów z Podmiasta... wszystkie bezwartościowe!', '', 0),
(22404, 'plPL', 'Nie mogę pracować w takich warunkach! Potrzebujemy skutecznego szczepu!', '', 0),
(22406, 'plPL', 'W Podmieście robiliśmy postępy z naszą zarazą. A tu nagle szczep za szczepem zawodzi!', '', 0),
(22407, 'plPL', 'Królewskie Zakłady Chemiczne witają cię w Północnej Grani, $N. Co zatem uczynisz, by wspomóc nas w służbie Sylwanie?', '', 0),
(22463, 'plPL', 'Całe to strzelanie do Skorn i innych miejsc za horyzontem, i co myślisz, co mi z tego przyszło?$B$BZbieranie kul armatnich!$B$BNie na to się pisałem, wiesz?', '', 0),
(22464, 'plPL', '', 'Czas na odpoczynek, kochaniutki, czy tylko coś do jedzenia i chwila wytchnienia?$B$BJeśli ktoś na to zasługuje, to właśnie ty!', 0),
(22465, 'plPL', 'Co masz do jedzenia, Celeste?', 'Co masz do jedzenia, Celeste?', 0),
(22485, 'plPL', 'W samą porę! Zmywajmy się stąd.', '', 0),
(22486, 'plPL', 'Tak, chodźmy... ale nie wcześniej, niż zostawimy naszym gospodarzom z Przymierza coś na pamiątkę!', '', 0),
(22487, 'plPL', 'Mają w tym obozie skromne zapasy. Wielka szkoda by była, gdyby coś im się stało.', '', 0),
(22488, 'plPL', 'Kapitan Adams wysłał mnie tutaj, żebym zbadał, co się dzieje w Halgrind. Bliżej jednak podejść nie zdołałem. Opuszczona wieża wrykulów daje mi choć trochę osłony przed wścibskimi oczami.$B$BPorzuceni knują tam coś złego. Czuję to!', '', 0),
(22489, 'plPL', 'Ach, tak... niech płonie!', '', 0),
(22490, 'plPL', 'Już prawie skończone!', '', 0),
(22491, 'plPL', 'To was nauczy nie zadzierać z aptekarzem, wy psy Przymierza bez matek!', '', 0),
(22492, 'plPL', 'Wiejmy stąd, i to szybko.', '', 0),
(22493, 'plPL', 'Nie strzelać! Aptekarz idzie!', '', 0),
(22494, 'plPL', 'Jesteśmy twoimi dłużnikami, przyjacielu. Porozmawiaj z Lysandrem w Przystani Zemsty, on zadba o stosowną nagrodę dla ciebie.', '', 0),
(22495, 'plPL', 'Ahahaha! Muszę poznać tajemnice!', 'Ahahaha! Muszę poznać tajemnice!', 0),
(22496, 'plPL', 'Nie chcę już nic wiedzieć. Spraw, żebym zapomniał!', 'Nie chcę już nic wiedzieć. Spraw, żebym zapomniał!', 0),
(22497, 'plPL', 'Kto bada i kopie, ten odsłania prawdę.', 'Kto bada i kopie, ten odsłania prawdę.', 0),
(22498, 'plPL', 'Tu jesteśmy bezpieczni, TO nigdy nas tu nie dosięgnie!', 'Tu jesteśmy bezpieczni, TO nigdy nas tu nie dosięgnie!', 0),
(22499, 'plPL', 'Koniec jest bliski! To, Czego Nie Wolno Nazywać, jest prawie wolne!', 'Koniec jest bliski! To, Czego Nie Wolno Nazywać, jest prawie wolne!', 0),
(22500, 'plPL', 'TO nadchodzi! KRYJCIE SIĘ!', 'TO nadchodzi! KRYJCIE SIĘ!', 0),
(22501, 'plPL', 'Gdyby tylko było więcej czasu!', 'Gdyby tylko było więcej czasu!', 0),
(22502, 'plPL', 'Wybacz mi, o wielki. Nie chciałem poznać prawdy!', 'Wybacz mi, o wielki. Nie chciałem poznać prawdy!', 0),
(22503, 'plPL', 'Prawda cię wyzwoli. Tak jak my, zostaniesz z TYM na zawsze!', 'Prawda cię wyzwoli. Tak jak my, zostaniesz z TYM na zawsze!', 0),
(22504, 'plPL', 'Skoro znasz już prawdę, nie mogę pozwolić ci odejść!', 'Skoro znasz już prawdę, nie mogę pozwolić ci odejść!', 0),
(22505, 'plPL', 'Wszystko wkrótce się skończy. Wkrótce spoczniesz w objęciach Tego, Czego Nie Wolno Nazywać!', 'Wszystko wkrótce się skończy. Wkrótce spoczniesz w objęciach Tego, Czego Nie Wolno Nazywać!', 0),
(22506, 'plPL', 'Intruz! Przysłano cię, żeby nas zniszczyć!', 'Intruz! Przysłano cię, żeby nas zniszczyć!', 0),
(22507, 'plPL', 'Nie możesz odejść... TO nie może nas znaleźć!', 'Nie możesz odejść... TO nie może nas znaleźć!', 0),
(22508, 'plPL', 'Skoro tu jesteś, TO może być tuż za tobą!', 'Skoro tu jesteś, TO może być tuż za tobą!', 0),
(22509, 'plPL', 'Zakończę twoje życie, zanim pojmiesz straszliwą prawdę!', 'Zakończę twoje życie, zanim pojmiesz straszliwą prawdę!', 0),
(22510, 'plPL', 'Teraz musisz do nas dołączyć... na zawsze!', 'Teraz musisz do nas dołączyć... na zawsze!', 0),
(22552, 'plPL', 'Nie powinniśmy byli zostawiać tylu ludzi w Valgardzie. Admirał Keller, ten nieznośny egomaniak!$B$BJak mam wykonać rozkazy z tak nielicznym oddziałem? Potrzebuję dość ludzi, żeby zostali tu w twierdzy, a zarazem porządnie obsadzili Fort Wildervar, gdy będzie gotów!$B$BTeraz, gdy tu jesteś, mamy przynajmniej nadzieję, że uporamy się z naszymi kłopotami.', '', 0),
(22553, 'plPL', 'Doradzam kapitanowi w sprawach, którymi zechce się ze mną podzielić, ale mam wrażenie, że wolałby usłyszeć o nich od ciebie.', '', 0),
(22554, 'plPL', '', 'Tyle gąb do wykarmienia, a kto musi to robić? Ja!$B$BCałe gotowanie, sprzątanie i wszystko inne!', 0),
(22557, 'plPL', 'Przez wszystkie moje dni nie sądziłem, że ujrzę tak wspaniałe nowe rubieże.$B$BGdyby tylko nie skaziło ich zło i wiedza, która powinna pozostać ukryta.', '', 0),
(22558, 'plPL', 'Widziałem w życiu niejedno, ale to, co stało się z Ligą Odkrywców w Wąwozie Szeptów, przebija wszystko.$B$BCieszę się tylko, że uszedłem stamtąd w jednym kawałku!', '', 0),
(22593, 'plPL', 'Ziemia... jest zamarznięta. Jesteśmy tu jak kaczki na strzelnicy, te wozy na mięso nigdzie nie pojadą.', '', 0),
(22594, 'plPL', 'Najwyższy egzekutor Anselm chce raportu o sytuacji.', 'Najwyższy egzekutor Anselm chce raportu o sytuacji.', 0),
(22595, 'plPL', 'A jak to wygląda? Ziemia zamarzła na kamień!$B$BKoła tych wozów na mięso zbudowano najwyżej do jazdy po błocie. Żeby je wyciągnąć, potrzebujemy plugastwa i kilku łańcuchów.', '', 0),
(22614, 'plPL', '', 'Rozbitkowie z Przymierza wiedzą, że zginą, a mimo to walczą z nami zębami i pazurami.$B$BImponujące i żałosne zarazem.', 0),
(22615, 'plPL', '', 'To kwestia godzin, nim Przymierze na Wybrzeżu Wraków zostanie zmiażdżone. Są otoczeni, a my mamy przewagę liczebną.', 0),
(22616, 'plPL', '', 'Z woli Sylwany nasi wrogowie padną.', 0),
(22617, 'plPL', 'Najwyższy egzekutor Anselm prosi o twój raport.', 'Najwyższy egzekutor Anselm prosi o twój raport.', 0),
(22618, 'plPL', '', 'To te dwa działa na murze nas spowalniają. Bez ich osłony nasze siły mogłyby szturmować umocnienia bez żadnych strat.$B$BAlbo zniszczymy te działa, albo poczekamy, aż skończy im się amunicja. Wybór należy do Anselma, jak sądzę.', 0),
(22622, 'plPL', '', 'Oddajcie mi swe dusze, bym mogła zgładzić wroga!', 0),
(22636, 'plPL', '', 'Nie powstrzymacie mego dzieła! Mój mąż i król się przebudzi!', 0),
(22637, 'plPL', 'Proszę, wypuśćcie mnie stąd!', 'Proszę, wypuśćcie mnie stąd!', 0),
(22638, 'plPL', 'Klucz... musisz znaleźć klucz!', 'Klucz... musisz znaleźć klucz!', 0),
(22639, 'plPL', 'Chyba widziałam klucz u jednego z tych wrykulów.', 'Chyba widziałam klucz u jednego z tych wrykulów.', 0),
(22640, 'plPL', 'Nie chcę, żeby mnie zabrali do katakumb!', 'Nie chcę, żeby mnie zabrali do katakumb!', 0),
(22641, 'plPL', 'Nie chcę zostać złożona w ofierze!', 'Nie chcę zostać złożona w ofierze!', 0),
(22642, 'plPL', 'Odprawiają w katakumbach bezbożne obrzędy, a ja mam być ofiarą!', 'Odprawiają w katakumbach bezbożne obrzędy, a ja mam być ofiarą!', 0),
(22643, 'plPL', 'Czy nie ma bohatera, który mnie ocali?', 'Czy nie ma bohatera, który mnie ocali?', 0),
(22644, 'plPL', 'To już koniec.', 'To już koniec.', 0),
(22645, 'plPL', 'Och, dziękuję, dziękuję!', 'Och, dziękuję, dziękuję!', 0),
(22646, 'plPL', 'Dziękuję. Nie zapomnę ci tego!', 'Dziękuję. Nie zapomnę ci tego!', 0),
(22647, 'plPL', 'Pomścij moich przyjaciół, których już złożono w ofierze!', 'Pomścij moich przyjaciół, których już złożono w ofierze!', 0),
(22648, 'plPL', 'Musisz położyć kres temu szaleństwu, zanim będzie za późno!', 'Musisz położyć kres temu szaleństwu, zanim będzie za późno!', 0),
(22649, 'plPL', 'Dzięki ci, $gbohaterze:bohaterko;!', 'Dzięki ci, $gbohaterze:bohaterko;!', 0),
(22650, 'plPL', 'Wrykule są źli i trzeba ich zniszczyć!', 'Wrykule są źli i trzeba ich zniszczyć!', 0),
(22651, 'plPL', '$GOcaliłeś:Ocaliłaś; mi życie!', '$GOcaliłeś:Ocaliłaś; mi życie!', 0),
(22652, 'plPL', 'Dzięki niebiosom, że jesteś!', 'Dzięki niebiosom, że jesteś!', 0),
(22657, 'plPL', 'Krocz w Światłości, moje dziecko.', '', 0),
(22661, 'plPL', 'Ogniu, obdarz mnie wizją...', '', 0),
(22662, 'plPL', 'Łucznicy, w gotowości! Wstrzymać ogień!', '', 0),
(22663, 'plPL', 'Któż to, głupiec, śmie bez zapowiedzi wkraczać w dominium Jej Wysokości?', '', 0),
(22664, 'plPL', 'Wodo, obdarz mnie spokojem...', '', 0),
(22666, 'plPL', '%s wdycha delikatne smugi dymu unoszące się z kadzielnicy.', '', 0),
(22670, 'plPL', 'Dziękuję wam, duchy.', '', 0),
(22686, 'plPL', 'I to wszystko, co masz do powiedzenia?', '', 0),
(22687, 'plPL', 'Odeślijcie te szumowiny z powrotem do piekła! Ognia do woli!', '', 0),
(22688, 'plPL', 'Leci prosto na nas!', 'Leci prosto na nas!', 0),
(22689, 'plPL', 'OGNIA! OGNIA!', 'OGNIA! OGNIA!', 0),
(22690, 'plPL', 'Strzelajcie mu między oczy! Te bestie są tam wrażliwe!', 'Strzelajcie mu między oczy! Te bestie są tam wrażliwe!', 0),
(22691, 'plPL', 'Nadciąga najeźdźca!', 'Nadciąga najeźdźca!', 0),
(22692, 'plPL', 'Nie przepuśćcie tych potworów przez bramę! Trzymajcie się, żołnierze!', 'Nie przepuśćcie tych potworów przez bramę! Trzymajcie się, żołnierze!', 0),
(22693, 'plPL', '$GPanie:Pani;! Jestem tu, by ci pomagać i cię bronić.$B$BTwoje rozkazy?', '', 0),
(22697, 'plPL', 'Za Ymirona!', 'Za Ymirona!', 0),
(22698, 'plPL', 'Błagaj o życie...', 'Błagaj o życie...', 0),
(22699, 'plPL', 'Twój koniec się zbliża!', 'Twój koniec się zbliża!', 0),
(22701, 'plPL', 'Cierp, robaku!', 'Cierp, robaku!', 0),
(22702, 'plPL', 'Oddam życie za Ymirona!', 'Oddam życie za Ymirona!', 0),
(22729, 'plPL', 'Aranal, ledel! Ich los będzie waszym losem!', '', 0),
(22734, 'plPL', 'Nie tak szybko.', '', 0),
(22736, 'plPL', 'Twoja krew należy do mnie!', '', 0),
(22737, 'plPL', '%s odchrząkuje.', '', 0),
(22738, 'plPL', 'Rozglądam się po tej bazie i widzę tylko strach... Będziecie się bać, kiedy armie Króla Lisza rozsiądą się wygodnie w Wichrogrodzie? W Żelaznej Kuźni? NIE! Nie będziecie. A wiecie dlaczego? Bo będziecie martwi, oto dlaczego.', '', 0),
(22739, 'plPL', 'Więc kiedy poczujecie to mrowienie u nasady kręgosłupa i będziecie o krok od zmoczenia gaci, przyjmijcie to. Niech was to rozwścieczy. Ten strach to jedyne, co utrzyma was przy życiu.', '', 0),
(22740, 'plPL', 'Czy wyrażam się jasno? Rozumiecie, co mówię? Nie chcę więcej wysyłać do domów trumien ani listów.', '', 0),
(22744, 'plPL', '%s krzyczy z bólu, gdy harpun zostaje wyciągnięty.', '%s krzyczy z bólu, gdy harpun zostaje wyciągnięty.', 0),
(22747, 'plPL', 'Nie... nie... Nasi ludzie... Czaszka Żmija... niektórzy żyją...', 'Nie... nie... Nasi ludzie... Czaszka Żmija... niektórzy żyją...', 0),
(22748, 'plPL', 'Moje rany są zbyt ciężkie. Nie przeżyję... Nasi ludzie trzymani w klatkach... rytuał...', 'Moje rany są zbyt ciężkie. Nie przeżyję... Nasi ludzie trzymani w klatkach... rytuał...', 0),
(22749, 'plPL', 'Już po mnie... straciłem za dużo krwi... Zapomnij o mnie, powiedz Kellerowi... W środku wciąż są żywi ludzie...', 'Już po mnie... straciłem za dużo krwi... Zapomnij o mnie, powiedz Kellerowi... W środku wciąż są żywi ludzie...', 0),
(22750, 'plPL', 'Moja rodzina musi wiedzieć... Ja... dla nich... zawsze dla nich...', 'Moja rodzina musi wiedzieć... Ja... dla nich... zawsze dla nich...', 0),
(22751, 'plPL', 'Zostawili nas tu nabitych na pale jako ostrzeżenie dla innych... Kilku wciąż żyje... więźniowie...', 'Zostawili nas tu nabitych na pale jako ostrzeżenie dla innych... Kilku wciąż żyje... więźniowie...', 0),
(22752, 'plPL', 'Nie pozwól, by moja śmierć pozostała niepomszczona, $gnieznajomy:nieznajoma;... daj... im... popalić...', 'Nie pozwól, by moja śmierć pozostała niepomszczona, $gnieznajomy:nieznajoma;... daj... im... popalić...', 0),
(22759, 'plPL', '', 'Pospiesz się, $N!$b$bTen kryzys jest daleki od opanowania.', 0),
(22767, 'plPL', 'Chcesz się gdzieś dostać, $n? Moje nietoperze zawiozą cię tam w mgnieniu oka.', '', 0),
(22768, 'plPL', 'Muszę polecieć na „Bieżywiatr”. Sprawa służbowa!', 'Muszę polecieć na „Bieżywiatr”. Sprawa służbowa!', 0),
(22774, 'plPL', 'Sierżancie, pożycz mi swoją lunetę.', 'Sierżancie, pożycz mi swoją lunetę.', 0),
(22785, 'plPL', '', 'Odważne te żaby z Przymierza! Abordaż na niszczyciele Porzuconych z pełną załogą... jeśli to nie samobójstwo, to nie wiem, co nim jest.', 0),
(22787, 'plPL', 'Myślisz, że nie wiem, co próbujesz zrobić? Myślisz, że cię nie obserwowałem?', '', 0),
(22788, 'plPL', 'Nie powstrzymasz mojego wniebowstąpienia, mała istoto. Czas umierać!', '', 0),
(22789, 'plPL', 'Nie! Nie pokonasz mnie!', '', 0),
(22790, 'plPL', '', 'Ja i moje siostry witamy cię, wędrowcze.', 0),
(22797, 'plPL', 'Doskonale. Jakie wieści? Mamy już liczbę trupów?', '', 0),
(22798, 'plPL', 'No, wykrztuś to wreszcie! Jakie są złe wieści?', '', 0),
(22800, 'plPL', 'Silne bóle brzucha?', '', 0),
(22801, 'plPL', 'SILNE BÓLE BRZUCHA?', '', 0),
(22802, 'plPL', 'Jesteśmy Królewskimi Zakładami Chemicznymi! Wywoływanie bólu brzucha nie należy do naszych obowiązków!', '', 0),
(22803, 'plPL', 'Czy otaczają mnie sami amatorzy? Do jutra rana chcę mieć pełną analizę nowego szczepu! Bierz się do roboty, Ravien!', '', 0),
(22804, 'plPL', 'Witaj, $gnieznajomy:nieznajoma;. Jeśli szukasz miejsca, które potrzebuje twojej pomocy, właśnie je $gznalazłeś:znalazłaś;.$B$BUmarli budzą się, chodzą po ziemi i przypływają statkami zza wielkiego oceanu. Fiord staje się zbyt niebezpieczny nawet dla nas i wkrótce musimy wyruszyć na północ, do bezpieczniejszych krain.', '', 0),
(22805, 'plPL', 'Jestem tu, by ci pomagać i cię bronić.$B$BGdzie teraz uderzymy na wroga?', '', 0),
(22806, 'plPL', 'Pożycz mi, proszę, tę lunetę.', 'Pożycz mi, proszę, tę lunetę.', 0),
(22807, 'plPL', '', 'Podejdź bliżej, młode. Uszy już nie te, co kiedyś, a nie lubię podnosić głosu.', 0),
(22809, 'plPL', 'Kapitanie, jakimś cudem $gzgubiłem:zgubiłam; insygnia dowództwa.', 'Kapitanie, jakimś cudem $gzgubiłem:zgubiłam; insygnia dowództwa.', 0),
(22811, 'plPL', 'Wodzu Popielny Totemie, $gzapodziałem:zapodziałam; gdzieś znak, który mi dałeś.', 'Wodzu Popielny Totemie, $gzapodziałem:zapodziałam; gdzieś znak, który mi dałeś.', 0),
(22813, 'plPL', 'Za Ymirona!', 'Za Ymirona!', 0),
(22815, 'plPL', 'Oddam życie za Ymirona!', 'Oddam życie za Ymirona!', 0),
(22816, 'plPL', 'Brzydzicie mnie, wy małe stworzenia!', 'Brzydzicie mnie, wy małe stworzenia!', 0),
(22820, 'plPL', 'Patrzcie, kto przyszedł się pobawić.', 'Patrzcie, kto przyszedł się pobawić.', 0),
(22822, 'plPL', 'Nie czeka cię żadne wieczne życie!', 'Nie czeka cię żadne wieczne życie!', 0),
(22823, 'plPL', 'Złamię cię!', 'Złamię cię!', 0),
(22824, 'plPL', 'Twoja rasa to zaraza tego świata!', 'Twoja rasa to zaraza tego świata!', 0),
(22828, 'plPL', '', 'Mogę tylko mieć nadzieję, że leczenie zadziała.', 0),
(22829, 'plPL', '', 'Po prostu nie mam dość środków medycznych, by porządnie opatrzyć was wszystkich.', 0),
(22830, 'plPL', '', 'Nie martw się, żołnierzu. Yazmina się tobą zajmie.', 0),
(22831, 'plPL', '', '%s kręci głową.', 0),
(22832, 'plPL', 'Potrzebuję nietoperza wierzchowego, żeby przechwycić posiłki Przymierza.', 'Potrzebuję nietoperza wierzchowego, żeby przechwycić posiłki Przymierza.', 0),
(22845, 'plPL', 'Tyle zastosowań dla zarazy, a tak mało czasu!', '', 0),
(22854, 'plPL', '', 'Wszystkie są znakomite. Trudno będzie wybrać tylko jeden.', 0),
(22855, 'plPL', '', 'Chyba znalazłam ten, którego użyję. Teraz muszę zabrać się za jego rzeźbienie. Nie sądzę, żeby to było łatwe. Nawet nie wiem, jak brzmi godowy zew samicy yeti!', 0),
(22856, 'plPL', '', 'Większość podstawowego rzeźbienia mam za sobą, ale zanim będę mogła kontynuować, trzeba to wypróbować. Pomożesz mi w tym, $n?', 0),
(22857, 'plPL', 'Oddam życie za Straszliwego Króla!', 'Oddam życie za Straszliwego Króla!', 0),
(22859, 'plPL', 'Intruzi zostaną powstrzymani, mój panie.', 'Intruzi zostaną powstrzymani, mój panie.', 0),
(22860, 'plPL', 'Jeden z nas dostąpi dziś wyniesienia.', 'Jeden z nas dostąpi dziś wyniesienia.', 0),
(22863, 'plPL', 'Oto przybył Gunnar, syn Thorvarda! Szykujcie się na swoją zgubę!', '', 0),
(22867, 'plPL', 'Wrogowie Zimowego Skornu, zostaniecie rozszarpani na strzępy!', '', 0),
(22868, 'plPL', 'Przepędźcie tę hołotę z ojczyzny wrykulów!', '', 0),
(22869, 'plPL', 'AGH! Tylko nie znowu to pryskanie!', '', 0),
(22870, 'plPL', 'Co to za... AGH!', '', 0),
(22871, 'plPL', 'Na brodę Branna, PRZESTAŃCIE!', '', 0),
(22872, 'plPL', 'Krasnolud kaszle, parska i drży w klatce.', '', 0),
(22873, 'plPL', 'Z ust uwięzionego krasnoluda wydobywa się niski, rozpaczliwy jęk.', '', 0),
(22874, 'plPL', '%s słabo potrząsa prętami klatki.', '', 0),
(22875, 'plPL', '%s osuwa się bezsilnie na pręty klatki.', '', 0),
(22876, 'plPL', 'To TY $gprzerwałeś:przerwałaś; mi obiad? No, ty?', '', 0),
(22877, 'plPL', 'Jesteś za $gbrzydki:brzydka; i za $gchuderlawy:chuderlawa; na samicę yeti! A teraz mnie wkurzasz...', '', 0),
(22878, 'plPL', '', 'Jakże miło cię widzieć!$B$BJest robota do zrobienia, a czasu mało.', 0),
(22880, 'plPL', 'Czego ode mnie chcecie?', '', 0),
(22881, 'plPL', 'Puśćcie mnie, tchórze! Pokażę wam, z czego jest ulepiony krasnolud!', '', 0),
(22882, 'plPL', 'Co zrobiliście z mieszkańcami tej wioski!?', '', 0),
(22883, 'plPL', 'Gorth nie bać się, że zginąć. Ci Porzuceni po prostu poskładać go z powrotem.', '', 0),
(22884, 'plPL', 'Gorth czasem się mylić. Gorth dobrze zabijać ludzi, to Gorth zostać sierżant. Ale teraz Gorth nigdy nikogo nie zabijać!', '', 0),
(22885, 'plPL', 'Wrykule większe i silniejsze od nas. Ale my ładniejsze!', '', 0),
(22892, 'plPL', 'MÓÓÓZGIII!', '', 0),
(22893, 'plPL', 'Taki... głodny...', '', 0),
(22894, 'plPL', 'NAKARM MNIE...', '', 0),
(22895, 'plPL', 'JEDZENIE! ZJEŚĆ CIĘ!', '', 0),
(22896, 'plPL', 'Bliżej... podejdź bliżej...', '', 0),
(22898, 'plPL', 'PALI! TO PALI!', '', 0),
(22899, 'plPL', 'ARGHHHH...', '', 0),
(22900, 'plPL', 'Światło... takie jasne światło...', '', 0),
(22901, 'plPL', 'Złe światło... boli...', '', 0),
(22902, 'plPL', 'Precz... idź...', '', 0),
(22910, 'plPL', 'Może to był błąd, żeby w drodze tutaj przechodzić tak blisko Rozdartego Lasu i Gjalerbron.', '', 0),
(22927, 'plPL', 'Walczysz jak dziewczynka!', 'Walczysz jak dziewczynka!', 0),
(22928, 'plPL', 'Lepiej mi się ćwiczy na kukle treningowej.', 'Lepiej mi się ćwiczy na kukle treningowej.', 0),
(22929, 'plPL', 'Ćwiczysz, jakbyś jeszcze $gspał:spała;.', 'Ćwiczysz, jakbyś jeszcze $gspał:spała;.', 0),
(22930, 'plPL', 'Kiedy przyjdą maluczcy, nie będę się powstrzymywać tak jak przy tobie.', 'Kiedy przyjdą maluczcy, nie będę się powstrzymywać tak jak przy tobie.', 0),
(22931, 'plPL', 'Na pewno nie potrzebujesz przerwy, staruszko?', 'Na pewno nie potrzebujesz przerwy, staruszko?', 0),
(22932, 'plPL', 'Marnie ci idzie ta walka!', 'Marnie ci idzie ta walka!', 0),
(22933, 'plPL', 'Ćwiczenie czy nie, zaraz będziesz pluć zębami!', 'Ćwiczenie czy nie, zaraz będziesz pluć zębami!', 0),
(22934, 'plPL', 'No dalej, przestań próbować mnie trafić i wreszcie mnie traf!', 'No dalej, przestań próbować mnie trafić i wreszcie mnie traf!', 0),
(22936, 'plPL', 'Całe życie jestem żołnierzem. Walczyłem w wielu wojnach, pod wieloma sztandarami, ale zawsze były to cudze bitwy.$B$BNie tym razem. Każdy żołnierz Porzuconych, którego tu widzisz, przybył z jednego jedynego powodu. Arthas musi zginąć.', '', 0),
(22944, 'plPL', 'Miej się na baczności, wędrowcze, otaczają nas tu chodzące trupy.', '', 0),
(22945, 'plPL', 'Dziękuję ci, $gnieznajomy:nieznajoma;.', 'Dziękuję ci, $gnieznajomy:nieznajoma;.', 0),
(22946, 'plPL', 'Muszę wracać. Udanych łowów.', 'Muszę wracać. Udanych łowów.', 0),
(22947, 'plPL', 'Niech błogosławią ci duchy ziemi i powietrza.', 'Niech błogosławią ci duchy ziemi i powietrza.', 0),
(22948, 'plPL', '$GOcaliłeś:Ocaliłaś; mnie od pewnej śmierci. Mam u ciebie dług.', '$GOcaliłeś:Ocaliłaś; mnie od pewnej śmierci. Mam u ciebie dług.', 0),
(22949, 'plPL', 'Nie powinniśmy byli iść przez Rozdarty Las. Przecież wszyscy o tym wiedzą!', 'Nie powinniśmy byli iść przez Rozdarty Las. Przecież wszyscy o tym wiedzą!', 0),
(22950, 'plPL', 'Po tej ziemi chodzą dziwne duchy. Uważaj!', 'Po tej ziemi chodzą dziwne duchy. Uważaj!', 0),
(22951, 'plPL', 'Brali nas jednego po drugim. Jestem pewien, że są inni ocaleni.', 'Brali nas jednego po drugim. Jestem pewien, że są inni ocaleni.', 0),
(22952, 'plPL', 'Zawdzięczam ci życie, $gnieznajomy:nieznajoma;.', 'Zawdzięczam ci życie, $gnieznajomy:nieznajoma;.', 0),
(22953, 'plPL', 'Weź mnie! Jestem gotów umrzeć!', '', 0),
(22954, 'plPL', 'Rozkoszuj się ich cierpieniem, bracie!', '', 0),
(22955, 'plPL', 'Stań i przyjmij osąd!', '', 0),
(22956, 'plPL', 'Obyś $gumarł:umarła; w łasce Króla Lisza!', '', 0),
(22957, 'plPL', 'Walczymy ku chwale Ymirona! Umieramy w imię Króla Lisza!', '', 0),
(22958, 'plPL', 'Chwileczkę...', '', 0),
(22959, 'plPL', 'To tylko...', '', 0),
(22960, 'plPL', 'Piwo! Zwykłe piwo!', '', 0),
(22961, 'plPL', 'Nie ma w nim absolutnie nic niezwykłego.', '', 0),
(22962, 'plPL', 'Ty! Ani słowa o tym Grickowi! Słyszysz?', '', 0),
(22964, 'plPL', 'Duchu, wróć do mnie!', '', 0),
(22976, 'plPL', 'Jak ja w ogóle dałem się Petrovowi namówić na przyjazd tutaj z tymi nieudolnymi krasnoludami?!', '', 0),
(23008, 'plPL', '[Prymitywny wrykulski] Bjorns mottar haelgond sygar!', '[Prymitywny wrykulski] Bjorns mottar haelgond sygar!', 0),
(23009, 'plPL', 'Nikt nie będzie tak mówił o mojej matce!', '', 0),
(23017, 'plPL', 'My, siewcy zarazy, jesteśmy zwykle nieco bardziej praktyczni niż przeciętny aptekarz. Ostatecznie zajmujemy się logistyką rozsiewania zarazy.$B$BNie znaczy to, że nasze podstawy teoretyczne nie są solidne jak skała. Po prostu wolimy... zadania praktyczne.', '', 0),
(23041, 'plPL', '', '%s wygląda na osłabioną!', 0),
(23042, 'plPL', '', 'Dziękuję. Myślałam, że umrę, nie zobaczywszy znów moich sióstr!', 0),
(23043, 'plPL', '', 'Gdzie jestem? Co mi się stało? Ty... ty mnie $guwolniłeś:uwolniłaś;?', 0),
(23044, 'plPL', '', 'Wiedziałam, że Lurielle przyśle pomoc! Dziękuję ci, przyjacielu, i przekaż Lurielle moje podziękowania!', 0),
(23052, 'plPL', '', 'Liga Odkrywców uprzejmie pozwoliła mi się przyłączyć. Jednak przy niebezpieczeństwach Rozdartego Lasu i okolic, wygląda na to, że głupotą było przyjść tu bez pomocy.', 0),
(23061, 'plPL', 'Plemię Zimowego Skornu zwycięży!', '', 0),
(23062, 'plPL', 'Przepędźcie najeźdźców! Za królową Angerbodę!', '', 0),
(23063, 'plPL', 'Walczcie bez strachu, a val\'kyrie was nagrodzą!', '', 0),
(23064, 'plPL', 'Dość tej maskarady!', '', 0),
(23065, 'plPL', '', 'Ciężka to robota, składać te rzeczy do kupy!', 0),
(23066, 'plPL', '', 'Kość stopy łączy się z... kością biodrową! Kość biodrowa łączy się z tą... inną kością! Hmmmhmmmmhmmm...', 0),
(23068, 'plPL', '$GZgubiłem:Zgubiłam; przebranie worga.', '$GZgubiłem:Zgubiłam; przebranie worga.', 0),
(23073, 'plPL', '', 'Będzie mi brakować Obozu Zimowego Kopyta, ale rozumiem, czemu wódz Popielny Totem tak zdecydował. Dom to wygoda, na którą nie zawsze możemy sobie pozwolić.', 0),
(23076, 'plPL', 'Powinienem być w Twierdzy Utgard i walczyć u boku Ingvara! A zamiast tego muszę pilnować takich czerwi jak ty.', '', 0),
(23077, 'plPL', 'Nie pojmuję, czemu po prostu cię nie zabijemy.', '', 0),
(23078, 'plPL', 'Ingvar ma wobec ciebie plany, maluchu.', '', 0),
(23079, 'plPL', 'Wkrótce nadejdzie twój czas w Kręgu Sądu, czerwiu.', '', 0),
(23081, 'plPL', '%s traci panowanie nad sobą i atakuje zarówno wrogów, jak i sojuszników!', '', 0),
(23082, 'plPL', 'Składam tego człowieka w ofierze w imię naszego mrocznego pana!', '', 0),
(23083, 'plPL', 'Weź mnie, val\'kyrio! Jestem gotów na sąd!', '', 0),
(23084, 'plPL', 'Jestem gotów umrzeć!', '', 0),
(23085, 'plPL', '', 'Hej, nie widzish, że próbuję się tu napić?', 0),
(23086, 'plPL', '', 'No, to powinno wystarczyć. Chyba... *hik*.', 0),
(23087, 'plPL', 'Wrykul łapie się za gardło, zaczyna się krztusić i miotać.', '', 0),
(23089, 'plPL', '', 'Kości... ciało... mięśnie... ścięgna... chrząstki... wszystko łączy się tutaj, pod moją piłą.', 0),
(23091, 'plPL', 'Fuj, obrzydliwe!', 'Fuj, obrzydliwe!', 0),
(23092, 'plPL', 'To się NIE wydarzyło!', 'To się NIE wydarzyło!', 0),
(23093, 'plPL', 'Niedobrze mi.', 'Niedobrze mi.', 0),
(23094, 'plPL', 'Hehe, ekstra!', 'Hehe, ekstra!', 0),
(23095, 'plPL', 'Coś ty za zwyrodnialec?', 'Coś ty za zwyrodnialec?', 0),
(23096, 'plPL', 'Nie wiedziałem, że one tak potrafią.', 'Nie wiedziałem, że one tak potrafią.', 0),
(23097, 'plPL', 'To jest... wyjątkowe.', 'To jest... wyjątkowe.', 0),
(23098, 'plPL', 'To jest ta nowa zaraza Porzuconych?!', 'To jest ta nowa zaraza Porzuconych?!', 0),
(23099, 'plPL', 'Żyje!', '', 0),
(23100, 'plPL', 'Spokojniej z tą ręką, głupcze! Rozlewasz po podłodze rzadkie składniki!', '', 0),
(23101, 'plPL', 'Mieszanina! Rusza się!', '', 0),
(23102, 'plPL', '%s odwraca się w twoją stronę.', '', 0),
(23103, 'plPL', 'Eee...?', 'Eee...?', 0),
(23104, 'plPL', 'O rety.', 'O rety.', 0),
(23105, 'plPL', 'Nic mu nie jest?', 'Nic mu nie jest?', 0),
(23106, 'plPL', 'Kapitanowi się to nie spodoba.', 'Kapitanowi się to nie spodoba.', 0),
(23108, 'plPL', 'Łoo.', 'Łoo.', 0),
(23112, 'plPL', 'Greer, potrzebuję gryfa i kilku bomb do zrzucenia na Nowy Agamand!', 'Greer, potrzebuję gryfa i kilku bomb do zrzucenia na Nowy Agamand!', 0),
(23113, 'plPL', 'Proszę bardzo, $gchłopcze:dziewczyno;. Niech każda się liczy!', '', 0),
(23116, 'plPL', 'Czyli i my jesteśmy przeklęci?', '', 0),
(23117, 'plPL', '%s wskazuje na niemowlę.', '', 0),
(23119, 'plPL', 'Bogowie nas opuścili! Musimy się go pozbyć, zanim Ymiron się dowie!', '', 0),
(23120, 'plPL', '', 'NIE! Nie możesz! Błagam cię! To nasze dziecko!', 0),
(23121, 'plPL', 'To co mamy zrobić, żono? Inni nie mogą się dowiedzieć. Jeśli poznają tę odmienność, wszystkich nas stracą.', '', 0),
(23122, 'plPL', '', 'Ja... ja je ukryję. Ukryję je, dopóki nie znajdę mu domu, daleko stąd...', 0),
(23123, 'plPL', 'Chwała naszemu wspaniałemu królowi, Ymironowi!', 'Chwała naszemu wspaniałemu królowi, Ymironowi!', 0),
(23125, 'plPL', 'Nie okazuj litości tym wybrykom natury, Ymironie!', 'Nie okazuj litości tym wybrykom natury, Ymironie!', 0),
(23128, 'plPL', 'Okaż im litość, mój królu! To nasza krew i ciało!', 'Okaż im litość, mój królu! To nasza krew i ciało!', 0),
(23129, 'plPL', 'Osłabiają nas! Już samo ich istnienie rozcieńcza naszą siłę! Zniszczyć ich wszystkich!', 'Osłabiają nas! Już samo ich istnienie rozcieńcza naszą siłę! Zniszczyć ich wszystkich!', 0),
(23130, 'plPL', '%s daje znak, by zamilknąć.', '', 0),
(23134, 'plPL', 'Wrykule, wasz król błaga was, byście słuchali!', '', 0),
(23136, 'plPL', 'Tłum wstrzymuje oddech z przerażenia.', '', 0),
(23137, 'plPL', 'Nawet teraz, w naszej najczarniejszej godzinie, drwią z nas!', '', 0),
(23138, 'plPL', 'Gdzie są tytani w czasie naszej największej potrzeby? Nasze kobiety rodzą wybryki natury – zniekształcone karły, które nie potrafią nawet same ustać! Słabe i szpetne... Bezużyteczne...', '', 0),
(23139, 'plPL', 'Ymiron się trudził. Długo siedziałem na tronie i usilnie rozmyślałem nad naszą niedolą. Jest tylko jedna odpowiedź... jedna przyczyna...', '', 0),
(23140, 'plPL', 'Bo któż, jeśli nie sami tytani, mógłby rzucić taką klątwę? Co mogłoby mieć taką moc?', '', 0),
(23141, 'plPL', 'A odpowiedź brzmi: nic... Bo to tytani nas przeklęli!', '', 0),
(23143, 'plPL', 'Tego dnia wszyscy wrykule porzucą swą dawną wiarę! Wyrzekamy się naszych starych bogów! Wszyscy wrykule przysięgną wierność Ymironowi! Ymiron obroni naszą szlachetną rasę!', '', 0),
(23144, 'plPL', 'Tłum wiwatuje.', '', 0),
(23145, 'plPL', 'A oto mój pierwszy dekret dla wrykulów! Wszystkie zniekształcone niemowlęta zrodzone z wrykulskiej matki i ojca mają zostać zgładzone zaraz po narodzinach! Nasza krew musi zawsze pozostać czysta! Ci, którzy złamią dekret Ymirona, zostaną zabrani do Gjalerbron na egzekucję!', '', 0),
(23146, 'plPL', '%s uśmiecha się szeroko.', '', 0),
(23147, 'plPL', 'Przywiódł cię tu szamanizm... Jego woń przenika powietrze. *Król Lisz się śmieje* Kiedyś byłem szamanem.', '', 0),
(23148, 'plPL', 'Nie, sługo. $gTen:Ta; jeszcze nie jest $ggotów:gotowa;.', '', 0),
(23149, 'plPL', 'Czujesz to, śmiertelniku? Przenika mnie śmierć i spowija wszystko, czego dotknę. Wystarczy, że pstryknę palcami, a twoja dusza będzie marnieć w potępieniu przez całą wieczność.', '', 0),
(23150, 'plPL', 'Ale... To jeszcze nie twój czas, by służyć Królowi Liszowi. Tak, czeka cię większe przeznaczenie. Potęga... Musisz stać się $gpotężniejszy:potężniejsza;, nim zaczniesz mi służyć.', '', 0),
(23151, 'plPL', 'A teraz patrz, val\'kyrio. Przyjrzyj się, jak naciskam. Widzisz, że to jeszcze nie dojrzało? Patrz, jak pęka i bez życia spada na ziemię.', '', 0),
(23152, 'plPL', '', 'Mamy to dla ciebie przygotować, mój panie?', 0),
(23155, 'plPL', 'Oczywiście. Było przy zwłokach krasnoluda niedaleko stąd.', '', 0),
(23246, 'plPL', 'Wyrzeźbię tylko te runy, które moim zdaniem dadzą ci władzę nad olbrzymem.', '', 0),
(23247, 'plPL', 'Pomijam runy „północ” i „zachód”, bo nie jestem pewien, jak wpływają na olbrzyma. Dodaję też runę, która ograniczy czas, przez jaki możesz nim kierować.', '', 0),
(23248, 'plPL', 'Proszę bardzo, Runa rozkazu... mam nadzieję. Nie tak zjadliwa jak jej kuzynka od żelaznych krasnoludów, ale działa.', '', 0),
(23311, 'plPL', 'Powstańcie z ziemi, moi bracia!', '', 0),
(23312, 'plPL', 'Nasi żelaźni panowie mają dla nas zadanie!', '', 0),
(23315, 'plPL', 'Za mną w góry, by wypełnić plan naszych panów!', '', 0),
(23332, 'plPL', 'Nie zawiedziemy!', '', 0),
(23410, 'plPL', 'Atak gargulców! Chwytajcie za strzelby, chłopy!', '', 0),
(23438, 'plPL', 'Czyż nie jest piękna? Chcesz się nią przelecieć?', '', 0),
(23441, 'plPL', 'Mów ciszej, $N. Nie chcemy, żeby nas usłyszeli.', '', 0),
(23456, 'plPL', '', 'Tak? O co chodzi?$B$BCzas na nikogo nie czeka!', 0),
(23457, 'plPL', 'Chowałem to specjalnie dla ciebie, wielkoludzie!', '', 0),
(23488, 'plPL', 'Zbudowaliśmy to miejsce gołymi rękami! Krwią i łzami, przyjacielu.$B$BUwierz mi, kiedy to mówię: nie mamy zamiaru nigdy oddać Valgardu.', '', 0),
(23508, 'plPL', 'Zwykłe psy nie podchodzą teraz do mnie nawet na krok. Byłem zdruzgotany, kiedy się o tym dowiedziałem... Kochałem te zwierzaki.$B$BPlagowe ogary są jednak niezłym zastępstwem. Może nie są aż tak... miłe dla oka. Ale ja też nie jestem!', '', 0),
(23530, 'plPL', 'Padłem! Nie lękajcie się, bracia! Niech nic nie powstrzyma was przed dotarciem do Kamiennej Kuźni!', '', 0),
(23534, 'plPL', '%s krzyczy i wije się z bólu, po czym traci przytomność.', '', 0),
(23536, 'plPL', 'Ci obcy są słabi i łatwo ich zmiażdżyć.', '', 0),
(23538, 'plPL', 'Dobrze! Dobrze! Wciąż żyjesz. Więcej zabawy dla mnie!', '', 0),
(23539, 'plPL', 'Są wytrzymalsi, niż bym się spodziewał po ich wzroście.', '', 0),
(23542, 'plPL', '<Ulfang wyje i obwąchuje cię, a ty rozumiesz, co mówi.>$B$BDziwny biały worg z północy, Garwal, odebrał mi moją watahę. Musimy rozszarpać mu gardło, żebym znów został przewodnikiem stada.', '', 0),
(23548, 'plPL', 'Słyszałeś, Jethan? Nie dostaniesz tego trofeum ze Stalowego Pióra, skoro wiemy, że jest matką.', '', 0),
(23549, 'plPL', 'Czemu nie? Pomyśl tylko, o ile lepiej będzie wyglądało z pisklętami po obu stronach...', '', 0),
(23550, 'plPL', 'Jethan!', '', 0),
(23551, 'plPL', 'Co? Mówię tylko, że tak się to robi na Wzgórzach Grizli.', '', 0),
(23552, 'plPL', 'Trzymają narzędzia w skrzynkach, które wyglądają tak. Szukaj ich przy pawilonach.', '', 0),
(23558, 'plPL', 'Ahoj, mon! Co się dziać, ty słony cwaniaku!$B$BTu wszystko być kipisz, ty łajzo!', '', 0),
(23559, 'plPL', 'Wyglądać bardzo elegancko, bratku! Ty złupić jakiego tłustego kupca? Lepiej podzielić się bogactwem... nie być tchórzliwy sknera, mon!', '', 0),
(23560, 'plPL', 'Patrz tam, kamracie! Ten parszywy głupek pchać się komuś pod sam nos. Ten uparty majtek dostać za swoje, mon... pójść pod kil i zostać upiorem, mon.', '', 0),
(23561, 'plPL', 'Ile będzie mnie kosztować podkucie mułów?', '', 0),
(23562, 'plPL', 'Nie podkuwamy tu żadnych mułów. Zresztą teraz zajmujemy się wyłącznie sprawami wyprawy.', '', 0),
(23563, 'plPL', 'Nie rozumiesz! Jeśli zaraz nie będę gotowy do drogi, ktoś zajmie całą dobrą ziemię pod osadnictwo!', '', 0),
(23564, 'plPL', 'To nie mój problem! Jak tak ci pilno do budowy domu, to buduj go tu, w forcie, i przestań jęczeć!', '', 0),
(23565, 'plPL', 'To prawda, kamracie! Nie ma twardszych wilków morskich niż Korsarze z Morza Północnego, tuta, mon!$B$BLepiej nikogo nie drażnić, mon. Zapomnij o tym! Połowa głupich majtków skończyć, całując córkę kanoniera, kamracie!', '', 0),
(23566, 'plPL', 'A teraz, jeśli łaska, zabierz tego osła sprzed mojej kuźni...', '', 0),
(23567, 'plPL', 'To, proszę pana, jest muł!', '', 0),
(23568, 'plPL', 'Eee... co to było?', 'Eee... co to było?', 0),
(23569, 'plPL', 'Teraz ty być bezczelny i pyskaty, mon! Ty chcieć mnie wkurzyć, ty chudy psie, łajdaku?$B$BTo zmykaj, ty tchórzliwy szczurze. Do zobaczenia o świcie!', '', 0),
(23570, 'plPL', 'Witajcie w Forcie Wildervar, dzielni osadnicy! Czeka tam na was cały kontynent, gotów do zajęcia!', '', 0),
(23571, 'plPL', 'To prawda, Północna Grań to surowa kraina, ale nasz lud jest silny, wytrwały i sprosta zadaniu!', '', 0),
(23572, 'plPL', 'Zdobędziemy tę ziemię mieczem i ujarzmimy ją pługiem! To wy, mężczyźni i kobiety, zostaniecie zapamiętani jako ci, którzy okiełznali dziki kontynent!', '', 0),
(23573, 'plPL', 'Ale nie będziecie tam sami. Moi ludzie i ja przygotowaliśmy muły juczne z zapasami, których będziecie najbardziej potrzebować.', '', 0),
(23574, 'plPL', 'Siekiery, kilofy, ziarno, gwoździe, żywność, koce, woda... wszystko to czeka na was. I myślę, że moje ceny okażą się całkiem rozsądne.', '', 0),
(23575, 'plPL', 'Starczy dla wszystkich z nawiązką. Jeśli będziecie potrzebować innych towarów, śmiało pytajcie!', '', 0),
(23576, 'plPL', 'A teraz, moi wierni klien... eee, przyjaciele, ruszajcie i zdobądźcie tę ziemię dla naszego ludu!', '', 0),
(23577, 'plPL', 'Więc to ty jesteś nowym ważniakiem w okolicy, co?$B$B<Zorek spluwa na ziemię.>$B$BNo...', '', 0),
(23578, 'plPL', 'Nie znam się zbytnio na sztuce... ale wiem, co mi się podoba!', '', 0),
(23581, 'plPL', 'To porządna banda, mon, żaden parszywy pies nie będzie obgadywać moich kamratów i odejść bezkarnie!', '', 0),
(23605, 'plPL', '', 'Pamiętaj, kochanie, potrzebujemy działki z ładnym gorącym źródłem.', 0),
(23606, 'plPL', 'Oczywiście, kochanie.', '', 0),
(23607, 'plPL', '', 'I nie chcę na naszej ziemi żadnych okropnych wilków, olbrzymów ani brzydkich baranów!', 0),
(23608, 'plPL', 'Tak, kochanie. Zdajesz sobie sprawę, że do czasu zasiewów będziesz jadła na obiad baraninę ze srogich baranów...', '', 0),
(23609, 'plPL', '', 'Prędzej zarżnę tego twojego muła! I w ogóle po co przyprowadziłeś tu tę bestię?', 0),
(23610, 'plPL', 'Wolę słuchać jego ryczenia niż twojego, moja droga.', '', 0),
(23611, 'plPL', 'Chaga... choka\'jinn.', '', 0),
(23612, 'plPL', 'Na kolana i pokłon... przed kłem i pazurem!', '', 0),
(23613, 'plPL', 'Nie da się walczyć z ta potęga!', '', 0),
(23614, 'plPL', 'Wy wszyscy przegrać!', '', 0),
(23615, 'plPL', 'Teraz ja cię pokroić!', '', 0),
(23616, 'plPL', 'Ty wyjść stąd w kawałkach!', '', 0),
(23617, 'plPL', 'Śmiesz rzucać wyzwanie Zimowemu Skornowi?! Nadzieję cię na twoją własną marną flagę!', '', 0),
(23618, 'plPL', 'Ofiary same do nas przychodzą? Rozumu nie masz!?', '', 0),
(23619, 'plPL', 'Twoje szczątki pójdą na pożarcie rekinom z Zatoki Sztyletu!', '', 0),
(23622, 'plPL', '<Stara Lodowa Płetwa spogląda na ciebie nieufnie, mruga rybim okiem i kiwa głową raz, krótko, dając znak, że możesz odejść.>', '', 0),
(23623, 'plPL', 'Długi dom zniszczony! W oddali słychać alarm.', '', 0),
(23634, 'plPL', '$n, chciałbym zamienić z tobą słowo.', '', 0),
(23649, 'plPL', 'Chyba widziałam klucz u jednego z tych wrykulów z Gjalerbron na górze.', 'Chyba widziałam klucz u jednego z tych wrykulów z Gjalerbron na górze.', 0),
(23656, 'plPL', 'Na co się gapisz, szczurze zęzowy? Har, har... żartuję tylko, kamracie!', 'Na co się gapisz, szczurze zęzowy? Har, har... żartuję tylko, kamracie!', 0),
(23657, 'plPL', 'Nie ma nic lepszego niż dobry trunek w towarzystwie dobrych kompanów... *hik*!', 'Nie ma nic lepszego niż dobry trunek w towarzystwie dobrych kompanów... *hik*!', 0),
(23658, 'plPL', '„Jaaaaaaaaaarrr... doprowadza mnie to do obłędu!” Zaraz... to chyba nie tak szło...', '„Jaaaaaaaaaarrr... doprowadza mnie to do obłędu!” Zaraz... to chyba nie tak szło...', 0),
(23659, 'plPL', 'Siadaj i napij się, kamracie! I przy okazji weź też jednego dla mnie!', 'Siadaj i napij się, kamracie! I przy okazji weź też jednego dla mnie!', 0),
(23660, 'plPL', '...ten parszywy pies miał dwie drewniane nogi, hak zamiast lewej ręki, dwoje szklanych oczu i drewniany nos!', '...ten parszywy pies miał dwie drewniane nogi, hak zamiast lewej ręki, dwoje szklanych oczu i drewniany nos!', 0),
(23661, 'plPL', 'Wspaniale, kolejny baranek ofiarny.', '', 0),
(23662, 'plPL', 'Tak nam śpieszno umierać?', '', 0),
(23663, 'plPL', 'Ty także będziesz służyć Królowi Liszowi.', '', 0),
(23665, 'plPL', '...a on na to: „Pewnie, że nie widzę podwójnie! Przecież mam tylko jedno oko!”', '...a on na to: „Pewnie, że nie widzę podwójnie! Przecież mam tylko jedno oko!”', 0),
(23666, 'plPL', 'Witaj, maleństwo. Przyszło się pobawić?', '', 0),
(23667, 'plPL', 'Twoje życie za Króla Lisza!', '', 0),
(23668, 'plPL', 'Mam ci do pokazania tyle cudów.', '', 0),
(23669, 'plPL', 'Zawsze znajdzie się miejsce dla jeszcze jednego.', '', 0),
(23670, 'plPL', 'Pocałować córkę kanoniera? Przecież nawet nie znam tej panny...', 'Pocałować córkę kanoniera? Przecież nawet nie znam tej panny...', 0),
(23671, 'plPL', 'Słyszałem, że Terry opchnął jeden z tych obrazów za tysiąc sztuk złota. Może i ja wejdę w ten handel sztuką!', 'Słyszałem, że Terry opchnął jeden z tych obrazów za tysiąc sztuk złota. Może i ja wejdę w ten handel sztuką!', 0),
(23678, 'plPL', 'Zerwany z krzaka w sam raz dojrzały.', '', 0),
(23685, 'plPL', 'Jarp? Jar chcesz lecieć? Narp... Nie-nie-nie-narp ma mo-mo-mo-mowy!', '', 0),
(23686, 'plPL', 'Oficjalna sprawa Ligi Odkrywców, McGoyver. Zabierz mnie do Posterunku Ligi Odkrywców!', 'Oficjalna sprawa Ligi Odkrywców, McGoyver. Zabierz mnie do Posterunku Ligi Odkrywców!', 0),
(23690, 'plPL', 'Przeklęta żaba! Tak, przystałem do załogi z Południowych Mórz – masz z tym jakiś problem, kamracie? Posiekam cię tu i teraz!', '', 0),
(23694, 'plPL', 'Głupie dziecko, nie powstrzymasz tego, co wprawiłem w ruch! A teraz giń!', '', 0),
(23696, 'plPL', 'Naprawdę $gmyślałeś:myślałaś;, że stając do walki ze mną, masz jakąkolwiek nadzieję na ocalenie przyjaciół?', '', 0),
(23705, 'plPL', 'Jarrrrrrr! Nigdy nie dostaniesz mojej lunety, zęzowa pijawko!', '', 0),
(23758, 'plPL', 'Witaj, wędrowcze. Jestem Hidalgo, mistrz łowów i sokolnik światowej klasy. Ta maszyna do zabijania, którą widzisz na moim ramieniu, to Excelsior.$B$BPewnie myślisz sobie: „A czym w ogóle zajmuje się sokolnik?” Otóż powiem ci – polujemy! Sokolnictwo to sztuka polowania na zwierzynę z pomocą ptaka drapieżnego. Może chcesz się nauczyć polować z wytresowanym drapieżnikiem? Hidalgo może cię tego nauczyć!', '', 0),
(23787, 'plPL', '<Stworzenie dziobie cię w rękę.>', '', 0),
(23788, 'plPL', '<Sokół skrzeczy łapczywie, domagając się czerwia.>', '', 0),
(23789, 'plPL', '<Nakarm skalnego sokoła czerwiem.>', '<Nakarm skalnego sokoła czerwiem.>', 0),
(23794, 'plPL', 'Lepiej się nie wychylaj, „kamracie”! Jeśli wiesz, co mam na myśli!$B$BJarrrr!', '', 0),
(23795, 'plPL', '', 'Wkrótce, mój ukochany. Wkrótce się przebudzisz, a całe Azeroth pozna strach!', 0),
(23796, 'plPL', '', 'Przebudź się, Ymironie, czas twego dalszego panowania jest bliski.', 0),
(23797, 'plPL', '', 'Nie śpij już dłużej, mój ukochany. Z potęgą Króla Lisza za plecami sprawisz, że świat zadrży.', 0),
(23798, 'plPL', '', 'Czemu ten rytuał trwa tak długo? Twój pan obiecał, że twoja pomoc przyspieszy cały proces!', 0),
(23799, 'plPL', '', 'Podwójcie wysiłki! Król Ymiron się przebudzi, a potem dostąpi wyniesienia!', 0),
(23802, 'plPL', '', 'Rytuał postępuje zbyt wolno. Potrzeba więcej ofiar!', 0),
(23807, 'plPL', 'To ja prowadzę tu walki. Chcesz się założyć, to graj spokojnie – każdy przyłapany na ustawianiu walk przejdzie się po desce.$B$BSam tego dopilnuję!', '', 0),
(23808, 'plPL', 'Skarby krwawych elfów nie mają sobie równych. Liczy się nie tylko złoto, jedwab czy klejnoty, z których je wykonano – sama robota sin\'dorei jest cenna.', '', 0),
(23809, 'plPL', 'Taruk przysłał mnie po to, co jesteś mu winien.', 'Taruk przysłał mnie po to, co jesteś mu winien.', 0),
(23810, 'plPL', 'Nie wystawiaj mnie na próbę, parszywy psie! Szkolono mnie w sztuce Krwawych Rycerzy!', '', 0),
(23812, 'plPL', 'Zapłacę! Zapłacę! Iiii! Proszę, nie rób mi krzywdy!', '', 0),
(23814, 'plPL', '', 'Dzień w dzień Szalony Jonah Sterling każe mi tylko szorować pokład.$B$BSzorować pokład?!$B$BJestem magiem, ja NIE szoruję! A przynajmniej nie w zwyczajny sposób.', 0),
(23818, 'plPL', '', 'Bądź cicho, dobrze? Jeśli ktoś się połapie, już po nas.', 0),
(23819, 'plPL', '', 'No dobra, chłopaki! Kto zamawiał rum z korzeniami? Może ty, Jacku?', 0),
(23820, 'plPL', '', 'Spokojnie, skarbie. Ten jest na koszt firmy.', 0),
(23821, 'plPL', 'Darmowy rum? Toż to mój ulubiony rodzaj!', '', 0),
(23822, 'plPL', 'Na słodkiego Neptulona! To był... jeden kieliszek... za dużo!', '', 0),
(23823, 'plPL', '<Ten pirat najwyraźniej za dużo wypił. Wygląda na to, że na razie jest nieprzytomny.>', '', 0),
(23824, 'plPL', '<Dyskretnie przeszukaj kieszenie pirata w poszukiwaniu zapłaty dla Taruka.>', '<Dyskretnie przeszukaj kieszenie pirata w poszukiwaniu zapłaty dla Taruka.>', 0),
(23825, 'plPL', 'Na co się gapicie? Nalejcie mi jeszcze!', '', 0),
(23826, 'plPL', '', 'To co podać? Rum? Piwo?$B$BA może coś innego?', 0),
(23827, 'plPL', 'Chcę postawić Jackowi drinka. Najlepiej coś... wyjątkowo mocnego.', 'Chcę postawić Jackowi drinka. Najlepiej coś... wyjątkowo mocnego.', 0),
(23828, 'plPL', '', 'Chcesz wywinąć numer Jackowi na oczach jego chłopaków?$B$BDo tego trzeba sporej dawki... głupoty. Cóż, to będzie cię kosztować. Nie zaryzykuję życia za mniej niż sztukę złota. I lepiej poczekaj, aż zejdę ci z drogi, zanim coś zrobisz.', 0),
(23829, 'plPL', 'Masz tu sztukę złota, kup sobie coś ładnego.', 'Masz tu sztukę złota, kup sobie coś ładnego.', 0),
(23830, 'plPL', 'Jasne, kochana. Dopisz to do rachunku Harry\'ego, dobra? Wisi mi kolejkę!', '', 0),
(23831, 'plPL', '', 'No i proszę, $n! Ten tłuszcz na pewno załatwi sprawę! A teraz prawdziwe szorowanie!', 0),
(23832, 'plPL', '', 'Patrz, jak idą! Lśnią czystością!', 0),
(23833, 'plPL', 'Jarrrr! Jeśli szukasz mojego skarbu... to musisz o niego walczyć!', '', 0),
(23834, 'plPL', 'Co... *hik*?!', 'Co... *hik*?!', 0),
(23835, 'plPL', 'Dość... koniec z grogiem!', 'Dość... koniec z grogiem!', 0),
(23848, 'plPL', 'Jarrrrr... znowu martwy!', '', 0),
(23851, 'plPL', 'Tak odpłacasz się swojemu panu, ty pchlarzu? Arrrrrgghh!!', '', 0),
(23853, 'plPL', '', 'Lepiej się stąd zmywaj, $n. Nie chcę, żeby ktoś powiązał śmierć Jonaha ze mną.$B$BI tak trudno będzie mi się ustanowić przywódczynią tej zgrai, nawet jeśli nie będą wiedzieć, że kazałam zabić ich poprzedniego szypra.', 0),
(23854, 'plPL', '%s pożera ciało swego pana.', '', 0),
(23855, 'plPL', 'Wiele zmian przychodzi na ląd i wodę: wy, oni... wiele zmian.$B$BTe zmiany zagrażają sposobowi życia w Kamagua. Co zrobisz?', '', 0),
(23856, 'plPL', 'Nie w moim żywiole, co? Walt nie wie, co mówi! W pojedynkę wytłukłem żelazo z tych krasnoludów i rozbiłem obóz, żeby obserwować, co się dzieje na wykopaliskach.', '', 0),
(23857, 'plPL', 'Koleś, o tam, jest mocno zdenerwowany z powodu swojego dywanu.', '', 0),
(23858, 'plPL', 'Dobry wieczór, szefuniu.', 'Dobry wieczór, szefuniu.', 0),
(23859, 'plPL', 'Rafowa krowa i jej nowy byk odnajdują prawdziwą miłość.', '', 0),
(23868, 'plPL', 'Walt przysłał mnie po sztabki czarnorytu.', 'Walt przysłał mnie po sztabki czarnorytu.', 0),
(23869, 'plPL', 'Przy... przy... przypuszczarp, że jar chcesz wrócić na posterunek. Jarp?', '', 0),
(23870, 'plPL', 'Jarp.', 'Jarp.', 0),
(23871, 'plPL', 'Stół warsztatowy Walta jest gotowy do użycia.', '', 0),
(23872, 'plPL', '<Wejdź na stół warsztatowy i pozwól Waltowi umieścić cię w kombinezonie golema.>', '<Wejdź na stół warsztatowy i pozwól Waltowi umieścić cię w kombinezonie golema.>', 0),
(23873, 'plPL', 'Oto moje doskonałe dzieło!', '', 0),
(23875, 'plPL', 'ŁOO, ŁOO, ŁOO! Stać, chłopaki!', '', 0),
(23876, 'plPL', 'Wszystkie krasnoludy wybuchają śmiechem.', '', 0),
(23878, 'plPL', 'O drodzy panowie kamienia i stali, co... powtarzam... CO wy z tym zamierzacie zrobić?', '', 0),
(23880, 'plPL', 'Stary, to nigdy nie zadziała. Żelazne krasnoludy nigdy nie dadzą się nabrać na tę kupę złomu!', '', 0),
(23883, 'plPL', 'Nie jesteś w swoim żywiole, Lebronski! Nie na miejscu! Te żelazne krasnoludy nie będą wiedzieć, co je trafiło! A może wrócisz do rozwiązywania zagadki gigantycznej kupy na twoim dywanie i zostawisz prawdziwych naukowców w spokoju przy pracy!', '', 0),
(23885, 'plPL', '', 'Płaczę ze śmiechu! Błagam, niech to śmieszne przestanie!', 0),
(23889, 'plPL', 'Gdyby tylko nasz tatko dożył tej chwili!', '', 0),
(23890, 'plPL', 'Co ty wyprawiasz, stary? Lebronski NIE życzy sobie, żebyś włóczył swoje luźne metalowe części po jego dywanie.', '', 0),
(23891, 'plPL', 'Odlot, stary. Ta kupa śrubek może jednak dać radę...', '', 0),
(23898, 'plPL', 'Chwała wielkiemu stwórcy.', '', 0),
(23903, 'plPL', 'Stój! Natychmiast się przedstaw!', '', 0),
(23904, 'plPL', 'Wstęp do tej sekcji wzbroniony!', '', 0),
(23905, 'plPL', 'Nigdy tu nie widziałem nikogo takiego jak ty.', '', 0),
(23906, 'plPL', 'Czekaj! Stój!', '', 0),
(23907, 'plPL', 'Stój!! Stój!!! Złom teraz sam chodzi?', '', 0),
(23908, 'plPL', 'Zła odpowiedź!', '', 0),
(23910, 'plPL', 'No tak... mój błąd. Na czym to ja skończyłem?', '', 0),
(23911, 'plPL', 'Chwała wielkiemu stwórcy!', '', 0),
(23912, 'plPL', 'Oczywiście, masz rację. Kontynuuj.', '', 0),
(23913, 'plPL', 'Wybacz mi moją zuchwałość!', '', 0),
(23914, 'plPL', 'Przynosisz wieści od stwórcy?', '', 0),
(23915, 'plPL', 'Podwoimy wysiłki!', '', 0),
(23916, 'plPL', 'Praca musi trwać. Podwoić wysiłki.', '', 0),
(23917, 'plPL', 'Brontes widzi wszystko.', '', 0),
(23918, 'plPL', 'Nie ociągać się.', '', 0),
(23919, 'plPL', 'Kontynuować rozbiórkę.', '', 0),
(23920, 'plPL', 'Posiłki w drodze. Funkcjonowanie musi trwać bez zakłóceń.', '', 0),
(23921, 'plPL', 'Zniszczyć plagę ziemnych.', '', 0),
(23929, 'plPL', 'Jestem $ggotów:gotowa;, Walt.', 'Jestem $ggotów:gotowa;, Walt.', 0),
(23969, 'plPL', 'Umarli powstają i szukają zemsty na każdym, kto ośmieli się przejść przez ich włości. Zawróć!', '', 0),
(23970, 'plPL', 'Z rozdartej ziemi skradziono sakrament. Tarcza Aesirytów przepadła. Niepokój będzie wieczny.', '', 0),
(23971, 'plPL', 'Kostur furii burzy skradziony. Klątwa na tę ziemię! Burze nigdy nie ustaną!', '', 0),
(23972, 'plPL', 'Zamarznięte serce Isuldofa będzie trawić tę ziemię, dopóki nie zostanie zwrócone. Biada tym, którzy je trzymają, bo dopadnie ich klątwa zamarzniętej krwi...', '', 0),
(23973, 'plPL', 'Męka dziesięciu tysięcy lat czeka każdego, kto będzie na tyle głupi, by przywdziać Pradawną zbroję kvaldirów. Strzeżcie się mgły i oparów, śmiertelnicy, bo wraz z nimi nadejdzie wasz koniec.', '', 0),
(23974, 'plPL', 'Poszczęściło mi się. Niewielu taurenów zostaje chłopcami okrętowymi na takiej fregacie! Grezzix pozwala mi nawet obsadzać te niesamowite czółna bojowe.', '', 0),
(23975, 'plPL', 'Nie mam czasu na pogawędki, Lou. Zabierz mnie na Cypel Łajdaków.', 'Nie mam czasu na pogawędki, Lou. Zabierz mnie na Cypel Łajdaków.', 0),
(23977, 'plPL', 'Jego moc płynie przeze mnie! JESTEM BOGIEM!', '', 0),
(23978, 'plPL', 'ABDUL SILNY JAK BYK!', '', 0),
(23979, 'plPL', 'RZUCASZ MI WYZWANIE? MAM SIŁĘ DZIESIĘCIU MĘŻCZYZN!', '', 0),
(23997, 'plPL', 'Ognia! Ognia, wy tchórzliwe psy morskie!', '', 0),
(24025, 'plPL', 'Ahoj! Szukasz miejsca na pokładzie „Siostry Miłosierdzie”, kamracie? Dobrze $gtrafiłeś:trafiłaś;...', '', 0),
(24028, 'plPL', 'Ognia! Ognia, dla łupów, moi dzielni!', '', 0),
(24029, 'plPL', 'Może i wygrał za życia, ale po śmierci wygrywać nie będzie! OGNIA!', '', 0),
(24429, 'plPL', 'Moi bracia się przebudzili. Twoje wysiłki poszły na marne...', '', 0),
(24430, 'plPL', 'Twoja ofiara przyszła za późno, maluchu. Czujesz, jak mgła się wokół ciebie zaciska? Kvaldirowie powracają...', '', 0),
(24432, 'plPL', 'Patrz na morza, bo twoja zguba nadejdzie z przypływem.', '', 0),
(24433, 'plPL', 'Z mgły i oparów nadciągają kvaldirowie. Uciekaj, póki oddychasz powietrzem żywych...', '', 0),
(24434, 'plPL', 'Jestem Atuik, wódz Kalu\'ak z Kamagua.', '', 0),
(24951, 'plPL', 'Panie, potrzebuję kolejnej fruwającej maszyny...', 'Panie, potrzebuję kolejnej fruwającej maszyny...', 0),
(25731, 'plPL', 'Sprzedajecie coś z tych rzeczy?', 'Sprzedajecie coś z tych rzeczy?', 0),
(25734, 'plPL', 'Patrz na mój kozik, ty paskudny rechotku! Patrz i pokaż mi, kto śmie zadzierać z moimi braćmi!', '', 0),
(25737, 'plPL', 'Na co ty się gapić, kamracie?', '', 0),
(25738, 'plPL', 'Yyy... żaba mówi, że jesteś zdrajcą, „kamracie”.', 'Yyy... żaba mówi, że jesteś zdrajcą, „kamracie”.', 0),
(25743, 'plPL', 'Czy na pewno chcesz przekupić Olgę?', 'Czy na pewno chcesz przekupić Olgę?', 0),
(25744, 'plPL', 'Nigdy nie rozumiałem, czemu niektórzy piraci zakopują swoje skarby. Ja... wolę mieć je na wyciągnięcie ręki.', '', 0),
(25748, 'plPL', 'Parowy lodołamacz Przymierza „Północna Włócznia” pływa stąd do Przystani Menethilów na Bagniskach, za morzem, we Wschodnich Królestwach.', '', 0),
(25763, 'plPL', 'Nasz błogosławiony wielki żółw morski, Zielona Wyspa, płynie stąd do Portu Moa\'ki na Smoczych Pustkowiach.', '', 0),
(25765, 'plPL', 'Siema. Chcesz wrócić do Starego Świata? Poleć z klasą na Polany Tirisfal na pokładzie „Chmurocałusa”.', '', 0),
(26185, 'plPL', 'Walczyliśmy w dolinach i na szczytach Góry Hyjal, na ruchomych piaskach Silithusu, przeciw straszliwym armiom Legionu. Jesteśmy bezimiennymi synami i córkami Przymierza bez twarzy. Na Światłość i potęgę Przymierza, pierwszy cios należy do nas, a ostatni cios to wszystko, co ujrzą nasi wrogowie.$B$BJesteśmy 7. Legionem.', '', 0),
(26260, 'plPL', 'Spustoszymy żywych... to znaczy Plagę, oczywiście.', '', 0),
(26689, 'plPL', 'Dokąd mam cię dziś wysłać?', '', 0),
(26697, 'plPL', 'Muszę się szybko dostać do Twierdzy Zimowej Straży!', 'Muszę się szybko dostać do Twierdzy Zimowej Straży!', 0),
(27024, 'plPL', '', 'Chcesz polecieć, wędrowcze?$B$BA może trapi cię coś innego?', 0),
(27152, 'plPL', '%s rzuca Mroźny grobowiec na $n.', '', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(27293, 'plPL', '', 'Niech Elune czuwa nad tobą, wędrowcze.', 0),
(27294, 'plPL', 'Przysłał mnie admirał Keller, Emilune. Proszę, wyślij mnie do Twierdzy Zachodniej Straży!', 'Przysłał mnie admirał Keller, Emilune. Proszę, wyślij mnie do Twierdzy Zachodniej Straży!', 0),
(27302, 'plPL', '', 'Tylko tak Harry w ogóle ze mną rozmawia! Muszę cały czas nosić tę głupią maskę...', 0),
(27303, 'plPL', 'Harry powiedział, że mogę polecieć jego bombowcem na wykopalisko Bael\'guna. Jestem $ggotów:gotowa;!', 'Harry powiedział, że mogę polecieć jego bombowcem na wykopalisko Bael\'guna. Jestem $ggotów:gotowa;!', 0),
(27337, 'plPL', '', 'Miłej podróży! To bilet w jedną stronę!', 0),
(27351, 'plPL', 'Wytrwałość czy głupota? Bez znaczenia. Niech to będzie dla ciebie nauczka, śmiertelniku!', '', 0),
(27388, 'plPL', 'Wrogowie zaciskają krąg wokół nas ze wszystkich stron, a wszyscy starsi mówią o porzuceniu tego obozu. Ja twierdzę, że powinniśmy stanąć do walki jak wojownicy, którymi jesteśmy.', '', 0),
(27727, 'plPL', 'Gończe, twoje mięso armat... eee, twój lud będzie cennym zasobem w walce z wrykulami. Czy powiedziałem „zasobem”? Chodziło mi o „sojusznika”.', '', 0),
(29296, 'plPL', 'Brama Błękitnego Szafiru jest atakowana!', '', 0),
(29297, 'plPL', 'Brama Zielonego Szmaragdu jest atakowana!', '', 0),
(29298, 'plPL', 'Brama Czerwonego Słońca jest atakowana!', '', 0),
(29299, 'plPL', 'Brama Purpurowego Ametystu jest atakowana!', '', 0),
(29300, 'plPL', 'Brama Żółtego Księżyca jest atakowana!', '', 0),
(29304, 'plPL', 'Brama Żółtego Księżyca została zniszczona!', '', 0),
(29305, 'plPL', 'Brama Purpurowego Ametystu została zniszczona!', '', 0),
(29306, 'plPL', 'Brama Czerwonego Słońca została zniszczona!', '', 0),
(29307, 'plPL', 'Brama Zielonego Szmaragdu została zniszczona!', '', 0),
(29308, 'plPL', 'Brama Błękitnego Szafiru została zniszczona!', '', 0),
(29591, 'plPL', 'Ciemność czeka.', '', 0),
(29592, 'plPL', 'Łączę się... z nocą.', '', 0),
(29925, 'plPL', 'Wschodni Cmentarz został zdobyty przez Przymierze!', '', 0),
(29926, 'plPL', 'Zachodni Cmentarz został zdobyty przez Przymierze!', '', 0),
(29927, 'plPL', 'Południowy Cmentarz został zdobyty przez Przymierze!', '', 0),
(29928, 'plPL', 'Wschodni Cmentarz został zdobyty przez Hordę!', '', 0),
(29929, 'plPL', 'Zachodni Cmentarz został zdobyty przez Hordę!', '', 0),
(29930, 'plPL', 'Południowy Cmentarz został zdobyty przez Hordę!', '', 0),
(30483, 'plPL', 'Idą po ciebie.', '', 0),
(30484, 'plPL', 'Poddaj się strachowi.', '', 0),
(30485, 'plPL', 'Zabij ich wszystkich... zanim oni zabiją ciebie.', '', 0),
(30486, 'plPL', 'Zwrócili się przeciwko tobie. Teraz... zemścij się.', '', 0),
(30487, 'plPL', 'Powtórz sobie jeszcze raz, że to nie są twoi prawdziwi przyjaciele.', '', 0),
(30488, 'plPL', 'Nie ma ucieczki. Nie w tym życiu. Nie w następnym.', '', 0),
(30489, 'plPL', 'Jesteś pionkiem niewidzialnych sił.', '', 0),
(30490, 'plPL', 'To BYŁA twoja wina.', '', 0),
(30498, 'plPL', 'Z przyjemnością cię wypatroszę!', 'Z przyjemnością cię wypatroszę!', 0),
(30499, 'plPL', 'Rzucę cię psom na pożarcie!', 'Rzucę cię psom na pożarcie!', 0),
(30500, 'plPL', 'Z twoich wnętrzności będzie piękny naszyjnik.', 'Z twoich wnętrzności będzie piękny naszyjnik.', 0),
(30501, 'plPL', 'Giń, czerwiu!', 'Giń, czerwiu!', 0),
(30502, 'plPL', 'Przychodzisz po śmierć!', 'Przychodzisz po śmierć!', 0),
(30503, 'plPL', 'Pluję na ciebie!', 'Pluję na ciebie!', 0),
(30504, 'plPL', 'Skomlący wieprzu!', 'Skomlący wieprzu!', 0),
(30505, 'plPL', 'Ugglin oo bjorr!', 'Ugglin oo bjorr!', 0),
(30506, 'plPL', 'Haraak foln!', 'Haraak foln!', 0),
(30507, 'plPL', 'Przychodzisz po śmierć!', 'Przychodzisz po śmierć!', 0),
(30508, 'plPL', 'Zjem twoje serce!', 'Zjem twoje serce!', 0),
(30958, 'plPL', 'Czym mogę służyć?', '', 0),
(31357, 'plPL', 'GOTUJĘ TU!', '', 0),
(31359, 'plPL', 'Czego potrzebujesz?', '', 0),
(31588, 'plPL', 'Wrykul umiera, bo przebudzono go w niewłaściwy sposób.', '', 0),
(31589, 'plPL', 'Zakłócenie rytuału przebudzenia sprawia, że wrykul umiera.', '', 0),
(31590, 'plPL', 'Przez niewłaściwe użycie różdżki przebudzenia uśpiony wrykul wyzionął ducha.', '', 0),
(32323, 'plPL', 'Dzień dobry!', '', 0),
(32325, 'plPL', '', 'Masz dla mnie jakąś płatną robotę?', 0),
(33057, 'plPL', '<Silnik głośno warczy.>', '', 0),
(33058, 'plPL', '<Wsiądź do bombowca i wróć na Cypel Łajdaków.>', '<Wsiądź do bombowca i wróć na Cypel Łajdaków.>', 0),
(33072, 'plPL', 'Komnata reliktu jest atakowana!', '', 0),
(33073, 'plPL', 'Do komnaty się wdarto! Relikt tytanów jest bezbronny!', '', 0),
(33082, 'plPL', '', 'Tylko szybko, wędrowcze. Jestem znużona i nie mam czasu na uprzejmości.', 0),
(33436, 'plPL', '', 'Dziękuję ci, śmiertelniku, za uwolnienie mnie od tej klątwy. Błagam cię, weź to ostrze.', 0),
(33437, 'plPL', '', 'Nie przyniosło mi nic prócz nieszczęść. Może znajdziesz kogoś, kto zdoła powstrzymać jego moc.', 0),
(34401, 'plPL', 'Pradawna Brama Strażników się otwiera!', '', 0),
(36993, 'plPL', 'OGNIA! OGNIA!', '', 0),
(38681, 'plPL', 'OGNIA! OGNIA!', '', 0),
(54704, 'plPL', 'Czy my się znamy?', '', 0);
